window.__D("text/sefer-hasichot-rayatz/c009",{"p":[[4301620294,"הוד כ\"ק אאמו\"ר הרה\"ק ברבים בכלל און ביחידות בפרט, דעם סדר הלימוד ועבודה פון הוד כ\"ק רבינו הזקן. פאַר מעזריטש איז הוד כ\"ק רבינו הזקן געווען אַ של\"ה איד<sup data-n=\"650\">15</sup>, געדאַוונט אין של\"ה'ס סידור; און קומענדיק פון הוד כ\"ק רבינו המגיד ממעזריטש וויסענדיק שוין ווער ער איז — אַ נשמה חדשה<sup data-n=\"651\">16</sup> בגילוי — און וואָס פאַר אַ עבודה האָט מען אויף אים אַרויפגעלייגט מלמעלה און וועלכע כוחות עצמיים ופנימיים האָט מען אים צוליב דעם געגעבן, ווי אויך וועלכע מסירת­נפש נסיונות ער וועט מוזן דורכגיין, האָט הוד כ\"ק רבינו הזקן זיך איבערגעגעבן מיט אַ מסירת נפש עצמי אויסצופירן די כוונה עליונה<sup data-n=\"652\">17</sup>.\nביי די חב\"ד חסידישע מסיבות ווערן דערציילט סיפורים און דברי תורה וואָס די זקני חסידי הוד כ\"ק רבינו הזקן האָבן מקבל געווען פון הוד כ\"ק רבינו הזקן און האָבן דאָס איבערגעגעבן מדור לדור בדיוק האותיות.\nווי עס איז שוין גערעדט געוואָרן מערערע מאָל ביי פאַרשידענע מסיבות איז בעפאָר הוד כ\"ק רבינו הזקן איז געגאַנגען דעם ערשטן מאָל צו הוד כ\"ק רבינו המגיד ממעזריטש האָט ער געהאַט אַ חדר יונגעלייט תלמידים וועלכע ער האָט מדריך געווען, און ווען ער איז צוריקגעקומען פון מעזריטש<sup data-n=\"653\">18</sup>, האָט ער זיי מגלה געווען דעם נייעם דרך אין עבודה, און האָט אָנגערופען זיינע תלמידים: חסידי חב\"ד.\nה. ווי עס איז דערמאָנט אין אַנדערע שיחות איז באַלד ווי הוד כ\"ק רבינו הזקן איז געקומען מביקורו במעזריטש<sup data-n=\"653\">18</sup> האָט ער אָנגעהויבן זאָגן תורה חסידות אויף אידיש און זייער קורץ, ווי עס איז פאַרצייכנט אין אַן אַנדער אָרט באריכות אַז חסידות חב\"ד איז בעיקרה מוחין — השכלה — אָבער די כוונה פנימיות פון דער השכלה איז עס זאָל זיין גילוי המדות.\nאין דער התגלות תורת החסידות איז פאַראַן אַ סדר אמרים — \"ווערטער\" — בקיצור מופלג און אין אידיש<sup data-n=\"655\">19</sup>. שפּעטער מיט יאָרן זיינען געווען מאמרים קצרים אויף פסוקי תנ\"ך, מאמרי חז\"ל, מאמרי הזוהר<sup data-n=\"656\">20</sup> — באַוואוסט אונטער דעם נאָמען \"די להבין'ס\"<sup data-n=\"657\">21</sup>. און תורת חסידות חב\"ד און עבודת החסידות האָט אָנגעפילט די קעפּ און הערצער פון חסידי חב\"ד מדור לדור — ברוכים יהיו הם ובני ביתם בתוך כלל אחב\"י ה' עליהם יחיו.\nדי עטליכע ווערטער וואָס זיינען דאָ געזאָגט געוואָרען, איז חוץ דעם וואָס זיי זיינען זייער וויכטיג און נוגע צו וויסן ווי אַזוי עס איז געווען די הנהגת החסידים בכל דור ודור, איז דאָס אויך אַ הוראה בחיים פון חיי החסידים בהוה.",[["650","15","ראה שיחת פורים שנה זו (לעיל ע' 99). וש\"נ."],["651","16","ראה שיחת ש\"פ וישב כ\"ו כסלו תש\"ו (לעיל ע' 22). וש\"נ."],["652","17","ראה גם שיחת יום א' דחג הפסח תש\"ו (לעיל ס\"ע 27). רשימה דש\"פ נצבים שנה זו (לקמן ע' 150 ואילך)."],["653","18","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."],["653","18","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."],["655","19","ראה גם שיחת יום ב' דחג השבועות שנה זו. ליל ב' דר\"ה תש\"ח (לקמן ע' 130. ע' 160)."],["656","20","ראה גם אגרות­-קודש ח\"ג ע' שמ. ח\"ד ס\"ע רעג (הועתק ב\"היום יום\" טו סיון). \"סקירה כללית\" בהוספה למאמרי אדמו\"ר הזקן — הקצרים ע' תקפט ואילך."],["657","21","כו\"כ נדפסו במאמרי אדמו\"ר הזקן — ענינים."]]],[4301620295,"חסידים בעדאַרפן וויסן ווער זיי זיינען און פון וואַנען זיי וואַקסן; אַז זייערע טאַטעס און מאַמעס, זיידעס און באָבעס זיינען געווען מסירות נפש מיטגלידער אין דער חב\"ד משפחה. זיי — די חסידישע אור אור עלטערן — האָבן מיט­געמאַכט דעם גרעסטן מסירת נפש אויף אויפשטעלן — מיט ג­ט'ס ב\"ה הילף — די חסידות חב\"ד היימען, און זיי זיינען גילדערנע רינגעלעך אין דעם שלשלת חסידות חב\"ד.\nעס איז זיכער אַז אַלע פאָטערס און מוטערס וואָס האָבן אין די אַלטע צייטן — בשעת די התחלת התיסדות חסידות חב\"ד — דורכגעלעבט שווערע ליידען און רדיפות יאָרן, האָבן זוכה געווען צו דעם ריכטיקן עולם הבא שכר, אַז זייערע נשמות צוזאַמען מיט די נשמות פון זייערע קינדער — חסידים נשמות, זיינען זיך מתענג אין עדן גן אלקים, אין די היכלי הקודש פון אבותינו רבותינו הקדושים; און זיינען מעורר רחמים אויף זייערע קינדס קינדער אַז זיי זאָלן מצליח זיין בכל עניניהם בגשמיות וברוחניות.\nו. די חסידות חב\"ד מסירות נפש הנהגה און הדרכה, האָט בעלויכטן דעם עדת החסידים און האָט געשאַפן די חסידות חב\"ד היימען. יעדער פון משפחת חסידי חב\"ד, זין און טעכטער, האָט מיט אַ איבערגיגעבענעם מסירות נפש אָפּגעהיט דעם חב\"ד חסידישען פירונג אין עניני הנהגת הבית און אין דער הדרכה פון די קינדער; און אַ דאַנק זייערע מסירות נפש הנהגה, האָבן זיי — בעזרת השם יתברך — דורך געפירט אַלעס, און האָבן זוכה געווען צו בנים ובנות דורכגעדרונגענע מיט מדות חסידות.\nעס איז פאַראַן אַ גאָר אַלטער וואָרט, וואָס חסידי חב\"ד הראשונים האָבן איבערגעגעבן ביים פאַרבריינגען מיט אינגערע חסידים בזמנם, וואָס זיי האָבן געהערט פון הוד כ\"ק רבינו הזקן ווען ער איז דעם ערשטען מאָל געקומען פון מעזריטשער מגיד<sup data-n=\"653\">18</sup>:\nעיקר החסידות איז מדות טובות. ניט השכלה — חכמה, ניט הבנה — בינה, ניט השגה — דעת, איז עיקר חסידות חב\"ד. דער עיקר חסידות חב\"ד איז מדות טובות. נאָר בכדי עס זאָל זיין מדות טובות בעדאַרף מען האָבן מוחין — שכל — אָבער דאָס — מוחין ושכל — זיינען מער ניט ווי צוליב מדות טובות. דער עיקר איז מדות טובות, און צוליב דעם האָט מען געגעבן מוחין.\nאין אָט דער תורה האָט הוד כ\"ק רבנו המגיד ממעזריטש איבערגעגעבן להוד כ\"ק רבינו הזקן דעם יסוד ועיקרי החסידות וואָס הוד כ\"ק רבינו הבעש\"ט האָט מגלה געווען.\nעס טוט זייער וויי צו ריידען ברבים און בפרטיות אין דעם ענין פון דער הנהגה והדרכה וואָס די צעירי חסידי חב\"ד — אין דער חומריות גופניות רעש'דיקער מדינת אַמעריקע — זיינען זיך אַליין מדריך און מתנהג.\nדי הנהגה און הדרכה וואָס די אַמעריקאַנער צעירי וזאטוטי תלמידי התמימים זיינען זיך מתנהג און מדריך, איז בעגרינדעט אויף דעם הגברת החומר על הצורה: איך וויל, איך דאַרף, מיר קומט.\nדאָס איז דער הונטערגרונט פון אַמעריקאַנער זאטוטי תלמידי התמימים פון גרויס ביז קליין. פון דעם בחיר התלמידים — בעיני עצמו — ביז דעם קלענסטן, שרייט אין לערנען מיט קולות",[["653","18","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."]]],[4301620296,"משונות אַז עס הערט זיך אין אַלע אַרומיקע פיל­שטאָקיקע הייזער.\nז. אין מיינע קינדער יאָרן האָב איך געהערט בשעת אַ פאַרבריינגען פון זקני החסידים — ר' אהרן און יקותיאל מלמדי דאָקשיץ<sup data-n=\"659\">22</sup>, ר' מאיר מרדכי, און מורי ר' ניסן<sup data-n=\"660\">23</sup> — ווי אַ איידים אויף קעסט, אַ למדן, האָט יאָרן לאַנג גע­לערנט בקול וזמרה בהתמדה גדולה, צוליב דער קאַץ וועלכע האָט זיך געשפּילט אונטער זיין טיר מיט אַ עכבר; און ער האָט געמיינט אַז דאָס איז זיין שווער און שוויגער הערן זיך צו ווי ער לערנט.\nעס טוט זייער וויי, עס איז פשוט אַ האַרץ ווייטאָג צו זען ווי די יונגעלייט, די בחורים — תלמידים האָבן מדות רעות; זיי לערנען חסידות און ווייסען ווי עס דאַרף זיין און מכל מקום האָבן זיי מדות רעות. אַז ניט נאָר עס איז שווער צו קוקן אויף זייערע ד' אמות, נאָר דער קוקן אויף זייערע פנים'ער רופט אַרויס אַ גועל נפש.\nחסידי חב\"ד בכלל, תלמידי תומכי-תמימים דליובאַוויטש בפרט און תלמידי תומכי-תמימים באַמעריקע בפרטיות, דאַרפן און מוזן זיך טיף פאַרטראַכטען אויף דעם מצב הפרוע.\nעס איז אַ כללות'דיקער ירוד ירדנו, מען איז זייער פאַרפּראָסטעט געוואָרן; עס פעלט אינגאַנצן דער ענין עבודה שבלב, ניט נאָר אין פועל נאָר אפילו אין רצון און מכל שכן אין עונג.\nדער \"ירד ירדנו\" זעט זיך אָן אין אַלע דרגות, פון דעם חסידישן בעל עסק און בעל מלאכה ביז דעם בן תורה. אַלע פון גזע החסידות זיינען, געלויבט השי\"ת, דורכגעדרונגען מיט געבאָרענע דרכי ומדות חסידות, וואָס חסידישע קינדער ירש'ענען פון זייערע עלטערן חסידים; אָבער דאָס איז ניט גענוג, ווייל דאָס ווערט אָפּגעשוואַכט אין דעם וואָכענדיקען טומעלדיקן אַמעריקאַנער הוא­הא פרנסה לעבן.\nחסידות חב\"ד איז בעיקרה דער גילוי פון מדות טובות אין דעם טאָג­טעגליכן לעבן: לייגן זיך שלאָפן אַ חסיד, שלאָפן אַ חסיד מיט חסידישע חלומות און צום אויפשטיין מיט חסידישע אויסגערוטע און שטאַרקע עבודה כוחות.\nח. חסידות חב\"ד איז אַ צוזאַמענ­שטעל פון חב\"ד שבמוח און מדות שבלב. און דער תכלית איז, אַז די השכלה שבמוח חב\"ד זאָל בריינגען דעם טוב טעם אין מדות, אַז מען זאָל דערהערן דעם טוב טעם פון געטליכ­קייט אין קיום המצוות בפועל.\nאויף פשוט'ע עברי הייסט דאָס, אַז די השכלה און השגה וואָס אין חסידות, איז נאָר בשביל העבודה; וויסן ווי ארומ­צוגיין דעם נפש הבהמית מיט זיינע חכמה'לאַך און המצאה'לאַך.\nדער נה\"ב איז דאָך אַ אומן ב­מלאכתו<sup data-n=\"661\">24</sup> און קומט צו יעדן מיט זיינע חכמה'לאַך, איז אויף דעם האָט מען געגעבן השכלה והשגה פון חסידות",[["659","22","נזכרו כו\"כ פעמים ביחד — ראה שיחת י\"ב תמוז תש\"ח. חורף ה'שי\"ת. ליל שמח\"ת ה'שי\"ת (לקמן ע' 247. ע' 351. ע' 374). ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 185. וש\"נ. — אודות ר' אהרן קוגל מדוקשיץ — ראה שיחת יום א' דחה\"ס תש\"ח (לקמן ע' 167). אודות ר' יקותיאל דייטש מדוקשיץ — ראה ספר השיחות שם ע' 14. שם ע' 47."],["660","23","ראה אודותו לעיל ע' 41. וש\"נ."],["661","24","ראה ספר השיחות תרפ\"ח­תרצ\"א ע' 119."]]],[4301620297,"איינצונעמען דעם נה\"ב. וואָס דערפאַר האָט מען דאָך געזאָגט אַז חסידים זיינען קלוגע<sup data-n=\"662\">25</sup>, וואָס דורך דער השכלה פון חסידות ווייסן זיי אוסצודרייען זיך פון די חכמה'לאַך פון נה\"ב, אָבער השכלה אַליין איז דאָך גאָרניט.\nהוד כ\"ק אבותינו רבותינו האָבן מזהיר געווען אנ\"ש אַז מען זאָל ניט הערן לימוד און חזרת מאמרי דא\"ח פון אַ חסיד וואָס טוט ניט אין עבודה בכלל און עבודת התפלה בפרט<sup data-n=\"663\">26</sup>.\nתורת חסידות חב\"ד איז אַ תורה שלימה וואָס בנינה און התגלותה איז אַ ציור שלם פון מוחין און מדות, כהכלל הידוע אַז מוחין זיינען מעורר און מגלה מדות. ד. ה. אַז מוחין זיינען נאָר אַ \"צוליב זאַך\"<sup data-n=\"664\">27</sup>, ווייל דער עיקר איז דאָך מדות — אהבת ה' ויראתו ית'. אָבער להיות אַז די התעוררות און גילוי המדות קומט נאָר דורך דעם השגת המוח, דערום מוז מען האָבן אַ השגה אלקית. אָבער אַלע מוזן וויסן דעם אמת אַז דער עיקר ענין החסידות איז מדות טובות; און דער וואָס טוט ניט אין עניני עבודה, הן אין אריכות התפלה בהתעוררות המדות שבלב, און הן אין תיקון ובירור המדות בפועל, איז זיין נאָמען אַלס משכיל געוואָרן אין דער חסידות חב\"ד וועלט אַ גנאי נאָמען: ער איז דאָך אַ משכיל!...\nט. ווי איך האָב שוין פיל מאָל דערציילט האָב איך אין מיינע קינדער יאָרן געהערט פיל סיפורים וועגן דעם לעבן און פירונג פון די חסידישע היימען.\nצווישן די זקני חסידי חב\"ד וואָס פלעגען קומען אין ליובאַוויטש להוד כ\"ק אאמו\"ר הרה\"ק, זיינען געווען זקנים מופלגים וועלכע זיינען נאָך אין זייער קינדערהייט געפאָרן מיט זייער פאָטערס צו הוד כ\"ק אדמו\"ר האמצעי, און פלעגן דערציילן פערשידענע הת­עוררות און עבודה ווערטער.\nהחסיד הזקן ר' שמואל ברוך נ\"ע וואַרשעווער<sup data-n=\"643\">8</sup> האָט דערציילט אַז ער איז געווען אַ תלמיד ביי זיינעם אַן עלטער פעטער החסיד ר' ירחמיאל צבי, און אַז די זקני חסידי תלמידי הוד כ\"ק רבינו הזקן הראשונים האָבן גע'חזר'ט איינע פון די ערשטע תורות וואָס זיי האָבן געהערט מהוד כ\"ק רבינו הזקן ווען ער איז געקומען פון מעזריטש<sup data-n=\"653\">18</sup>.\nאין יענעם מאמר האָט הוד כ\"ק רבינו הזקן מבאר געווען באריכות — לויט די ווערטער מאמרים וואָס הוד כ\"ק רבינו הזקן פלעגט זאָגן די ערשטע צייט קומענדיק פון מעזריטש — אַז תורה בכלל און תורת החסידות בפרט זאָל מען הערען נאָר פון דעם וואָס איז אַ עובד, פון דעם וואָס האָרעוועט אויף תיקון המדות. און אַז מען זאָל זיך היטן פון אַ חסידישן שקרן. דער וואָס איז אַ אומר דברי חסידות ואינו עושה.\nחסידות בעדאַרף מען הערן נאָר פון אַ בעל עבודה; פון דעם וואָס איז אַ מאריך בתפלתו; פון דעם וואָס ליגט מבקר זיין מחשבותיו דיבוריו ומעשיו צי זיי זיינען ווי חסידות וויל האָבן. פון אַזאַ עובד זאָל מען הערן און איינהערין זיך און מגפף ומחבב זיין יעדן ווארט.\nאך! ווי גליקלעך אין רוחניות ההשגה פון חסידות און אין הנהגה פון מדות",[["662","25","ראה גם ספר השיחות תורת שלום ע' 14. ספר השיחות תש\"ד ע' 154."],["663","26","ראה גם שיחת ש\"פ וישלח י\"ט כסלו תש\"ו (לעיל ס\"ע 17 ואילך). לקמן סעיף ט."],["664","27","בהנחה אחרת: ד. ה. אז מוחין זיינען נאָר צוליב מדות."],["643","8","ראה אודותו: שיחת חג הפסח תרצ\"ד סט\"ו. ספר השיחות תרפ\"ח­תרצ\"א ע' 97. וש\"נ. נזכר לקמן ע' 114. ע' 137. ע' 239. ע' 241. ע' 369."],["653","18","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."]]],[4301620298,"חסידות, זיינען די בחורים און די יונגעלייט וואָס האָבן זיך געריבן און רייבן זיך אַרום חסידים בעלי עבודה.\nעס טוט זייער וויי צו צוזען די יונגעלייט, די תלמידים וואָס האָבן מדות רעות. תמורת זה וואָס חסידות בעדאַרף זיי מטהר זיין פון זייער אהבת עצמם און פון זייערע מדות רעות ווי גאוה ושקר וכו', איז גאָר פאַרקערט אַז די אַזוי גערופענע — בדמיונם — השכלה פון חסידות ווערט טמא פון זייער ישות און גאוה.\nי. די משפיעים ליגן נאָר אין דעם ווי אַזוי צו געבן די תלמידים אַ געשמאַק אין אַ וואָרט השגה והבנה. אָבער אין דעם אמת'ן האָבן זיי בעדאַרפט טאָן אין דעם אַז די תלמידים זאָלן דערהערן דעם ניט געשמאַק פון זיך. איידל גערעט, אָבער באמת איז דער סרחון און ריח רע פאַרדרייט די קאָפּ און מאַכט פינסטער אין די אויגן.\nמען קען די משפיעים אויך ניט באַ­שולדיקן. די יונגע לייט, די בחורים, ווילן גאָר ניט הערן; זיי האָבן פאַר­שטאָפּט די אויערן, אודנין סתימין, עינין סתימין<sup data-n=\"667\">28</sup>. יעדער האַלט אַז ער איז אַנדערש. \"ער\" ווייס וואָס אַ חסיד איז; אַז אַ חסיד בעדאַרף לערנען און פאַרשטיין חסידות און אַז דער עיקר אָבער זיינען די מדות חסידות וואָס דאָס איז — מער אָדער ווייניגער — תלוי אין עבודת התפלה. אָבער ער איז אַנדערש.\nמיט וואָס איז ער אַנדערש?\nאויף דעם האָט ער פאַרשידענע תירוצים און טיפע גרינדליכע — לויט זיין מיינונג וואָס ווערט אָנגעפירט פון דעם נפש הבהמית — אמתלאות. זיין נפש הבהמית — דער חכם<sup data-n=\"668\">29</sup> להרע<sup data-n=\"669\">30</sup> — זאָגט אים אַז ער איז אַ חסיד. אַרבעטן אויף עבודת התפלה, אַרבעטן אויף מדות טובות, דאָס זיינען קלייניקייטען; ער איז לעילא'דיק פון דעם, ער שטייט העכער.\nאַי, מיט וואָס שטייט ער העכער?\nדער ענטפער איז אַז ער שטייט אויף \"קאווילעס\", אויף הילצערנע פיס. וואָס דורך די הילצערנע פיס ווערט ער טאַקע העכער, אָבער דאָס זיינען הילצערנע פיס; ד. ה. אַז די הויכקייט זיינע איז אַ הילצערנע, אַ טויטע — בריינגט ניט קיין חיות ניט אין דעם פאַרשטאַנד און ניט אין דעם בפועל ממש פון מדות טובות ואהבת ישראל.\nאַזאַ איינעם, רופט חסידות אַ חיצון<sup data-n=\"670\">31</sup>; אַז ווען ער דאַווענט שוין אַמאָל יע באריכות איז על פי רוב קוקט ער אין אַלע זייטן צי זעט מען אַז ער איז אַ עובד און איז מאריך בתפלתו. איין אמן יהא שמי' רבא ענטפערט ער ניט, ער איז אַ חסיד — זאָגט ער — וואָס טוט ניט צוליב גן עדן שכר.\nער איז אַ חסיד.\nמיט וואָס?\nמיט ביטול.\nאָבער דער ביטול איז מקור הרע.\nביי אַ חסידישן פאַרבריינגען ווען ער איז מצייר אין אריכות ההסבר כמה בעלי חסרונות אין העדר עבודה. אין",[["667","28","ראה שיחת פורים תש\"ו (לעיל ע' 25)."],["668","29","ע\"פ ירמי' כד, יב."],["669","30","ראה פרקי דר\"א פי\"ג. וראה גם שיחת ל\"ג בעומר תש\"ח. פורים תש\"ט (לקמן ע' 226. ע' 306)."],["670","31","ראה גם ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 97. 143. 184. 292."]]],[4301620299,"העדר הכרת חסרונות עצמו איז ער דער נאַר וואָס בתוך הריפות.\nאַלץ מיינט דעם אַנדערן. און ווען ער זיצט שוין אַמאָל ביי אַ פאַרבריינגען ובפרט אַז ער זינגט נאָך אַ חסידישען ניגון מיינט ער שוין אַז ער איז אַ חסיד אויך.\nיע, ער ווייסט אויך אַז חסידות איז ביטול, נאָר ניט מבטל זיין זיך, נאָר יענעם.\nיא. ווען הוד כ\"ק אאמו\"ר הרה\"ק האָט מיך ממנה געווען אַלס מנהל פועל פון תומכי-תמימים<sup data-n=\"671\">32</sup>, זיינען אַמאָל געקומען צו מיר עטליכע בחורים מיט אַן אָנקלאַגע אויף די משגיחים ומשפיעים אַז זיי טויגן ניט<sup data-n=\"672\">33</sup>, און זיי פאַרלאַנגען אַז מען זאָל אַרייננעמען אין דער הנהלה עטלעכע עלטערע תלמידים אַלס באי­כח פון די תלמידים.\nאין מיינע הרצאות — פון צייט צו צייט — להוד כ\"ק אאמו\"ר הרה\"ק וועגן עניני תומכי-תמימים, האָב איך דערפילט מיין חוב אַלס מנהל און האָב דערציילט להוד כ\"ק אאמו\"ר הרה\"ק אַז די תלמידי תומכי-תמימים קלאָגן זיך אויף די משגיחים ומשפיעים, און מאָנען ביי מיר אַלס מנהל איך זאָל אַרייננעמען אין דער הנהלת הישיבה באי­כח פון די עלטערע תלמידים.\nהוד כ\"ק אאמו\"ר הרה\"ק האָט מיר געענטפערט אויף אַלע מיינע פראַגן כסדר הקבוע, און איך האָב אַלס פאַרשריבן כמנהגי בכל עת. אויף דער בקשה פון די עלטערע תלמידים האָט מיר הוד כ\"ק אאמו\"ר געענטפערט אַז איך זאָל זיי — די עלטערע תלמידי התמימים — זאָגן זיי זאָלן קומענדיקן מאָנטאָג אָדער מיטוואָך אַריינגיין צו אים אין דער שעה קבועה וואָס ער האָט אויף דעם קובע געווען.\nאיך האָב איבערגעגעבן דעם ענט­פער לתלמידי התמימים.\nדי עלטערע תלמידים וואָס זיינען געווען ניט צופרידן מיט מיין שטרענ­גער הנהלה דורך די משגיחים ומשפי­עים, זיינען געווען זייער צופרידן פון דעם וואָס הוד כ\"ק אאמו\"ר הרה\"ק האָט ממלא געווען זייער בקשה, זיי האָבן אין דעם געזען אַ געוויסע אומצופרידנקייט — אַז הוד כ\"ק אאמו\"ר הרה\"ק איז ניט צופרידן מיט דעם אופן הנהלה ווי איך פיר תומכי-תמימים, און זיינען געווען בטוח אין זייער דערפאלג בהנוגע זייערע הצעות אין הנהלת<sup data-n=\"673\">34</sup> תומכי-תמימים.\nווען די תלמידים האָבן בעדאַרפט אַריינגיין להוד כ\"ק אאמו\"ר הרה\"ק האָט ער געהייסן אויך רופן ר' מיכאל מש­פיע<sup data-n=\"674\">35</sup> און הרה\"ג ר\"ז משגיח<sup data-n=\"675\">36</sup> און מיך.",[["671","32","ראה לקמן ע' 234. וש\"נ."],["672","33","ראה ספר השיחות תורת שלום ע' 75 ואילך, ובהערה 4 שם: בעת ההיא, הנה קבוצה מתלמידי תו\"ת לא רצו לקבל עליהם מרות המשפיעים, כ\"א ללמוד ד\"ח בפ\"ע, וכנראה שבמענה ע\"ז באה שיחה זו."],["673","34","בהנחה אחרת: הנהגת."],["674","35","החסיד ר' מיכאל בלינער. נק' בשם ר' מיכאל נעוולער. — ראה אודותו ספר השיחות תורת שלום ס\"ע 39 ואילך. ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 221. שיחת ליל א' דחג השבועות תש\"ח (לקמן ע' 234)."],["675","36","הר\"ר זאב וואלף ב\"ר משה אברהם לעוויטין (תר\"ח­תר\"ע). חתנו של הרה\"ח ר' גרשון דובער מפּאַהאַר. — ראה קונטרס עץ החיים ע' 52. אגרות­-קודש אדמו\"ר מהורש\"ב ח\"א ע' רכט. אדמו\"ר מהוריי\"צ ח\"א ע' שב. ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 205 הערה 27. ועוד."]]],[4301620300,"ווען מיר אַלע — די הנהלה און די עלטערע תלמידים — זיינען אַריין להוד כ\"ק אאמו\"ר הרה\"ק, האָט הוד כ\"ק אאמו\"ר הרה\"ק געזאָגט:\nדער מנהל פועל פון תומכי-תמימים האָט מיר איבערגעגעבן התאוננות פון די עלטערע תלמידים, און אַז איר ווילט איך זאָל קובע זמן זיין אויסצוהערן אייערע התאוננות אויף דער הנהלה.\nאויף אייער התאוננות, בעדאַרף מען לייען ביי פסח דעם בעל עגלה<sup data-n=\"676\">37</sup> די בייטש, ער ווייס אַ עצה צו געוויסע בעלי חיים פויליאַקעס.\nיב. ווען הוד כ\"ק רבינו הזקן האָט געדאַרפט אַוועק פאָרן פון מעזריטש, איז דער מלאך הקדוש<sup data-n=\"677\">38</sup> געגאַנגען אים בעגלייטען. האָט דער מלאך הקדוש געזאָגט צום בעל עגלה<sup data-n=\"678\">39</sup>: זאָלסט שמייסן די פערד אַז זיי זאָלן פאַרגעסן אויף דעם היי און האָבער און זאָלן וויסן זייער פליכט צו שלעפּן דעם וואָגן. אַז מען איז אַ בעל הבית אויף דעם גופניות'דיקן פערד, יעמאָלט קומט מען צו דעם מענטשליכער אמת'דיקער הויך פון מעלת הנשמה.\nיע! מנהלים פון תומכי-תמימים האָבן פיינע רוחניות'דיקע אַרבעט. ניט נאָר לערנען חסידות און ריידען עניני עבודה, נאָר מען בעדאַרף אויסרייניקן און אַמאָל אויך דורכלעכערען די הבנה און עבודה אויערלעך ביי די תלמידים, אַז זיי זאָלן קענען מקבל זיין און דערהערן אין אַ פנימיות וואָס מען רעדט צו זיי. מילא, די עלטערע תלמידים האָבן אַסאַך דורכגעמאַכט, אָבער די יונגע לייט דאַרפן אָנהויבן טאָן אין עבודה און מברר זיין די מדות רעות.\nאין יאָר תר\"ס בערך איז געווען אַ גרויסער פאַרבריינגען און דער טאַטע האָט גערעדט באריכות אין דעם ענין אַז חסידות חב\"ד מיינט מדות חסידות<sup data-n=\"679\">40</sup>.\nאַז אָך און וויי אויף דעם איצטיקן העדר העבודה אין עבודת התפלה. ווי ווייט מען איז פאַרפאָרן פון די ווערטער. מען האָט אַראָפּגעפירט חסידות אין אַ אָרט וואָס איז היפך לגמרי. ווען איז דאָס געווען אַז מען זאָל זיין חסידים אָן עבודת התפלה.\nמען דאַרף אָנהויבן טאָן אין עבודה.\nדער דאַוונען דאַרף זיין מיט אַ צובראָכנקייט. אין דאַוונען בעדאַרף זיין מרירות און נאָכדעם שמחה. אָבער אַז די שמחה איז פון דעם וואָס ער האָט געהאַט מרירות טויג נישט.\nאין קריאת שמע שעל המטה דאַרף זיין די החלטה צו ווערן בעסער, וכידוע מהחסיד ר' גרשון דוב נ\"ע<sup data-n=\"680\">41</sup> שהיה אומר קודם השינה<sup data-n=\"681\">42</sup>: מאָרגן דאַרף מען ווערן גאָר אַן אַנדערער<sup data-n=\"682\">43</sup>.",[["676","37","נזכר לקמן ע' 118 ובהנסמן בהערה 44 שם."],["677","38","הרה\"ק ר' אברהם בן הרב המגיד ממעזריטש."],["678","39","ראה (בשינויים) שיחת ליל י\"ט כסלו תרצ\"ג סכ\"ה. ספר השיחות תר\"פ­תרפ\"ז ע' 152. אגרות­-קודש ח\"ד ריש ע' תקנז. חי\"ד ע' תמ. לקו\"ש ח\"א ע' 118."],["679","40","ראה לעיל ע' 112. שיחות: י\"ג אלול שנה זו. ליל שמח\"ת, י\"ט כסלו תש\"ט (לקמן ע' 150. ע' 281. ע' 289). וראה גם ספר השיחות תורת שלום ע' 48."],["680","41","ראה אודותו לעיל ע' 5. וש\"נ."],["681","42","ראה לעיל שם. וש\"נ."],["682","43","בסוף ההנחה הובא: \"קטע משיחת כ\"ק אדמו\"ר שליט\"א\" — ואולי שייך כאן: די סיבה פון דקות'דיקן טמטום המוח איז ווייל מ'קריאת שמע'ט זיך ניט. אַז מען לייגט זיך שלאָפן ווי אַ איד, ער באַרעכנט די ענינים פון טאָג, און מאַכט אַ החלטה טובה אַז מאָרגן זאל זיין אַנדערש און מען זאָל זיך טאַקע פאַרנעמען מיט אַ עבודה, און פאַר דעם שלאָף טראַכט מען דברי תורה ביז מען ווערט אַנטשלאָפן; איז אז מען ווערט אַנטשלאָפן ווי אַ איד, שלאָפט אַ איד און עס שטייט אויף אַ איד מיט אַ חיות'דיקען מודה אני. אבער אַז מען פאַלט צו שלאָפן אָן אַ חשבון, שלאָפט מען פּראָסט; און אַ פּראָסטער שלאָפן איז פּראָסט, און מען שטייט אויף אַ פאַרשלאָפענער."]]],[4301620301,"מען דאַרף דערהערן דעם ניט גוט ווי עס איז יעצט און מאַכן די החלטה צו ווערן בעסער. אָבער אַז מען פילט אַ צופרידנקייט פון דעם גופא — פון דעם דערהערן אַז אַזוי ווי עס איז איצט איז ניט גוט — טויג דאָס ניט.\nאין דאַוונען דאַרף מען זיין צובראָכן ביי זיך און דאָס אַליין דאַרף בריינגען צו עבודה.\nעס איז דאָ אַ אויסשפּראַך אין ב' נוסחאות: א) חסידים זיינען בעלי עבודה. ב) בעלי עבודה זיינען חסידים.\nדער ביאור דערפון בעדאַרף מען ריידן באריכות גדולה. נאָר דער קיצור הענין איז:\n\"חסידים זיינען בעלי עבודה\", הפי­רוש אַז די גאַנצע יגיעה פון חסידים אין השכלה והשגה איז נאָר בשביל עבודה.\n\"בעלי עבודה זיינען חסידים\", הפי­רוש אַז דורך עבודה קען מען צוקומען צו די העכסטע מדריגות פון השכלת החסידות.\nהחלטה אַליין איז ניט גענוג. די החלטה אַז אַזוי ווי מען איז טויג ניט און אַז מען דאַרף ווערן בעסער, דערמיט אַליין איז מען ניט יוצא. עס דאַרף טאַקע זיין אַ בכן, אָבער בלייבן ביים בכן אַליין איז גאָרניט — מען דאַרף דעם פועל ממש, די עשי' בפועל.\nדי יונגעלייט דאַרפן האָבן אַ ביטוש כללי. על דרך ווי דער טאַטע האָט אַמאָל געזאָגט<sup data-n=\"683\">44</sup> אַז אַ רב פון אַ שטאָט וואָס ביי זיך אין דער היים איז ער אַ גאַנצער ציור, פלעגט פאָרן אין ליובאַ­וויטש; קומענדיק אין קראַסניאַע אָדער רודניאַ (התחנות הסמוכות לליובאַוויטש) פלעגט פסח דער בעל עגלה אַ געשריי טאָן: רבי'ל! קומט זעצט זיך מיט מיר אויפן וואָגען. דאָס פלעגט פועל'ן דעם ביטוש כללי.\nמען דאַרף זיך דאָך שעמען, עס איז דאָ אַ רבי: דער אַלטער רבי, דער מיטעלער רבי, די ווייטערדיקע רביים, וועלכע האָבן זיך מוסר נפש געווען איינצופלאַנצען ביי חסידים מדות טובות, און צום סוף, אַזוי ווי מען איז.\nתמימים! חסידים! מען בעדאַרף זיך נעמען פאַר דעם עבודת החסידות אַרבעט, און השי\"ת, בזכות הוד כ\"ק אבותינו רבותינו הקדושים, וועט אונז געוויס העלפן.",[["683","44","ראה ספר השיחות תש\"א ע' 35."]]],[4301620302,"<h4>סעודת אחרון של פסח תש\"ז</h4>\nא. אין דעם ענין פון דבקות זאָגט דער אַלטער רבי אַ משל פון צוויי אוהבים נאמנים הדבוקים זה בזה, וואָס איינער איז פאַר'דבק'עט אין דעם צווייטען אין זיין עצם, וואָס אפילו ווען ער איז ניטאָ מיט אים צוזאַמען, איז מחשבה מקשר. וואָס כמו\"כ איז דאָך דער ענין ההתקשרות פון די נשמה בגוף מיט דעם שרש הנשמה, עס איז דאָך נאָר אַ הארה ומקצת הנשמה מלובש אין גוף און זי איז זיך מקשר מיט'ן עצם הנשמה למעלה, וואָס דאָס איז די מדריגה פון יחידה וואָס זי איז מקבל פון יחיד<sup data-n=\"684\">1</sup> און בחי' יחיד איז משפיע אין יחידה. הגם באמת איז דאָך כל מדריגות הנשמה אפילו מדריגת נפש מקבל פון אלקות, נאָר בכדי צו האָבען אַ ידיעה אין די ענינים דאַרף מען האָבען אַ חוש אין רוחניות. און ווי דער טאַטע האָט געזאָגט, אַז בכדי צו האָבען אַ חוש אין רוחניות דאַרף מען האָבען הפשטת ה­גשמיות, וועט מען דאַמאָלסט פאַרשטיין וואָס איז אַ גשם פון אַ אידן.\nב. החסידים ר' אבא ציאַסניקער<sup data-n=\"685\">2</sup> און ר' הענדל<sup data-n=\"686\">3</sup> פלעגען אין ליובאַוויטש עסען שבת ביי דעם טיש פון טאַטען. ר' אבא ציאסניקער איז געווען אַ זקן. קליינער­הייט איז ער געבליבען אַ קיילעכדיקער יתום און האָט זיך אויפגעצויגען צווישען חסידים. ער האָט זיך אויפגעהאָדעוועט ביי זיינעם אַ פעטער, אַ פשוט'ער איד, אַ מאַרק­איד, וועלכער איז נאָך געפאָהרען צו דעם אַלטן רבי'ן.\nאיינמאל שבת ביי דעם טיש האָט דער טאַטע געבעטען ר' אבא ציאסניקער ער זאָל עפּעס דערציילען מימי קטנותו. האָט ר' אבא דערציילט, אַז אַמאָל האָט אים זיין פעטער געזאָגט, אַז ער האָט געהערט פון אַלטן רבי'ן אַ ענין, ווי אַזוי אַ איד דאַרף זאָגען \"מה טובו\".\nדעם תוכן הענין האָט ער איהם ניט געקענט איבערזאָגען, נאָר די ווערטער וואָס ער האָט געהערט פון אַלטן רבי'ן: אָט אַזוי דאַרף אַ איד זאָגען מה טובו.\nאבא ציאסניקער האָט אָבער גע­וואוסט, אַז זיין פעטער איז יענע צייט ערגעץ ניט געפאָרען, פרעגט ער ביי אים: ווען זענט איר געווען ביי דעם רבי'ן? ענטפערט אים דער פעטער: וואָס מיינסטו — יעצט? דאָס זאָג איך דיר, וואָס איך האָב געהערט מיט 30 יאָר צוריק!\n— אָט אַזוי האָט דער חסיד געלעבט מיט אַ וואָרט וואָס ער האָט געהערט פון רבי'ן 30 יאָר צייט, און דאָס איז געווען אַ איש פשוט.\nמיר האָבן גאָרניט קיין השגה אין דעם הפלאת המעלה פון אַ איש פשוט. די פשיטות פון אַ פשוט'ען אידען דערלאַנגט אין פשיטות העצמות<sup data-n=\"687\">4</sup>, וואָס כשם ווי מיר האָבען קיין ידיעה ניט אין התפשטות אלקות און מכ\"ש אין די פשיטות העצמות, אַזוי פאַרשטייען מיר ניט דעם עילוי והפלאה פון די פשיטות פון אַ פשוט'ען אידען.\nאַ פשוט'ער איד אַז ער שטייט מיט זיין פערד און וואָגען אין מאַרק און מיט אַמאָל רייסט זיך אַרויס פון אים: \"אַי,",[["684","1","ראה לקו\"ת פ' ראה כה, א. סה\"מ תרצ\"ו ע' 57. וש\"נ."],["685","2","ראה אודותו לעיל ע' 89. וש\"נ."],["686","3","ראה אודותו לעיל ע' 17. וש\"נ."],["687","4","ראה לעיל ע' 3. וש\"נ."]]],[4301620303,"רבונו של עולם!\" אַן אַ הכנה און אָן אַ פאַרוואָס, האָבען מיר דאָך גאָר ניט קיין ווערטער אַרויסצוגעבען וואָס דאָס מיינט, מיט דעם אויסגעשריי איז ער דאָך מברר דעם פערד און וואָגען און דעם גאַנצען וועג אויף וועלכען ער איז געפאָרען. וויפיל מען זאָל ניט ריידען וועגען דעם, וועלען ווערטער ניט דער­ליינגען אַרויסצוגעבען די הפלאה פון דעם אויסגעשריי פון אַ פשוט'ן אידען: \"אַי, רבונו של עולם!\", מען דאַרף האָבען אַ געפיהל אין דעם.\nג. אַ חסיד שטייט ניט מיטן וואָגן אין מאַרק. אַ חסיד איז אומעטום חסיד; אין מאַרק. אין שטוב, אין סטאָר, אין גאַס.\nד. לחיים! דער אויבערשטער זאָל ממלא זיין יעדערען וואָס אים פעלט, און דער אויבערשטער זאָל אַריינגעבען יעדערן דעה צו וויסן וואָס אים פעלט.\nה. כ\"ק אדמו\"ר שליט\"א ביקש את ר' מיכאל דוואָרקין<sup data-n=\"688\">5</sup> שילמד את התמימים דפה די אַלטע ליובאַוויטשער ניגונים.\nויאמר ר' מיכאל הנ\"ל: זיי זיינען ביי זיך שטאַרק אין דער דעה, זיי זאָגען אַז זיי קענען גוט.\nוענה כ\"ק אדמו\"ר שליט\"א:\nעס איז דאָך ידוע דער וואָרט פון זיידען (מהר\"ש נ\"ע) עס איז דאָ גוט און עס איז דאָ נאָך בעסער<sup data-n=\"689\">6</sup>.\nו. אחרי שר' מיכאל דוואָרקין ניגן הניגון של ר' מיכל זלאָטשעווער<sup data-n=\"690\">7</sup> אמר כ\"ק אדמו\"ר שליט\"א:\nאיך בין מכיר טובה מיכאל דוואָרקין, וואָס צוליב זיינעם אַ ניגון האָב איך אַמאָל זוכה געווען צו הערען פון טאַטען אַ ביאור בכמה שעות אין דעם ענין פון אורות דתוהו אין כלים דתיקון.\nוהמעשה שהי' כך הי'<sup data-n=\"691\">8</sup>:\nאיך פלעג אָפט האָבען אומגעריכטע אורחים; דער טאַטע פלעגט אָפט זיין ביי מיר אַ אורח. איינמאָל איז דער טאַטע געגאַנגען צו מיר, דורכגייענדיק די חדרים האָט ער געדאַרפט דורכגיין אַ פאָדער­שטיבעל (דאָרט איז געווען אַמאָל די סוכה, און נאָכדעם אַ וועראַנדע אין גאָרטען); וועלנדיק אַריינגיין אין דעם פאָדער דורכגאַנגס שטיבעל, ערשט מיט אַמאָל לויפט אַריין מיכאל דוואָרקין פון הויף אין דעם פאָדער­שטיבעל און הויבט אָן טאַנצען אַרום חדר מיט דעם ניגון בשפת רוסית: \"ניעט, ניעט, ניקאַוואָ, קראָמיע באָגאַ אַדנאַוואָ\" (זהו תרגום של אין עוד מלבדו). — אַז ר' מיכאל האָט געטאַנצט, איז ער געווען אינגאַנצען רויט, געטאַנצט מיטן גאַנצען עצם.\nדער טאַטע איז געבליבען שטיין אונטער דער טיר — ווייל ער האָט אים ניט געוואָלט שטערען — ביז וואַנען מיכאל דוואָרקין איז צוריק אַרויס פון פאָדער­צימער.\nהאָט דער טאַטע דאַמאָלסט מיר געזאָגט, אַז דער ניגון ביי מיכאל'ן איז דאָך געקומען פון וואַלד, אַ וואַלד ניגון (ר' מיכאל הי' עסקו ביער), דאָס נעמט זיך דאָך ניט ביי אים פון זוהר אָדער פון עץ חיים — נאָר פון וואַלד. וביאר לי אז הענין באריכות אורות דתהו בכלים דתיקון.",[["688","5","הרב מיכאל ב\"ר חיים יצחק דוואָרקין. נפטר בברוקלין נ.י. ערב שבועות תש\"ט."],["689","6","אגרות­-קודש ח\"ד ע' שמ. ח\"י ע' יג. חי\"ד ע' תלו."],["690","7","ע\"ד ניגון זה — ראה בהנסמן לעיל ע' 99 הערה 1."],["691","8","בהבא לקמן — ראה גם ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 302. וש\"נ."]]],[4301620304,"כ\"ק אדמו\"ר שליט\"א שאל את ר' מיכאל דוואָרקין, אם הוא זוכר את הניגון. וענה ר' מיכאל: דאָס איז ניט קיין ניגון, דאָס איז אַ התבוננות.\nוהעיר ע\"ז כ\"ק אדמו\"ר שליט\"א: אַ הפשטה'דיקע התבוננות. עס איז דאָ אַ התבוננות בהלבשה און עס איז דאָ אַ הפשטה'דיקע התבוננות.\nבכלל מיכאל'ס עבודה דאַרף ניט קיין ביאורים...\nז. מיר זיינען אָרעם אין השכלה, מיר זיינען אָרעם אין הבנה, מיר זיינען אָרעם אין ידיעה, מיר זיינען קטני ידיעה; ומכל שכן זיינען מיר אָרעם אין הרגש, צו דערהערען דעם ענין פון אהבת ישראל.\nמקיים זיין אַ מצוה טוען מיר מיט קבלת עול, און די מלאכים דערלייגען וואָס ס'פעלט; עס איז דאָ אַ מלאך מיכאל, אַנדערע מלאכים, דער אויבערשטער האָט זיך מיט וועמען אַ קער טאָן זיך. אָבער אין דעם ענין פון אהבת ישראל, פעלט אינגאַנצען דער הרגש. אויב איינער האָט פרנסה ווישט מען זיך שוין אָפּ די הענט און מען פטר'ט זיך שוין. עס דאַרף דאָך אָבער אַרען דער אַנדערער, עס דאַרף אים פאַראַהרען דער זולת — און דאָס פעלט.\nדאָס איז גורם אַז דער איש הפשוט לערנט זיך אָפּ פון אים. ער טראַכט זיך: אויב דער בן תורה האָט ניט קיין געשמאַק אין וואָס מען דאַרף האָבען אַ געשמאַק, און האָט אַ געשמאַק אין דעם וואָס מען דאַרף ניט האָבען אַ געשמאַק, היינט וואָס זאָל ער שוין טאָן.\nדער איש הפשוט ווייס דאָך ניט פון זיין מעלה אין פשיטות העצמות, וואָס באמת דאַרף זיך גאָר דער בן תורה אָפּלערנען פון אים, אָבער דער איש הפשוט ווייס דערפון ניט; במילא קוקענדיק אויפן בן תורה ווי אַזוי ער פירט זיך ניט כדבעי, שאַדט דאָס אים אין זיין הנהגה.\nח. לחיים! דער אויבערשטער זאָל געבען אַ געזונטען תמיד אין גשמיות און אין רוחניות.\nעוד הפעם אמר:\nלחיים! דער אויבערשטער זאָל געבען אַ פרייליכע וואָך, איך מיין ניט נאָר די וואָך, נאָר בכלל אַז די וואָכעדיגע טעג זאָלן זיין פרייליך, מען זאָל האָבן פרנסה, זיין רייך און קענען טאָן אין עבודה מיט הרחבה, מען זאָל זיין געזונד, רייך, פרום. נו — קלוגער.\nעוד הפעם אמר:\nלחיים! דער אויבערשטער זאָל געבען מען זאָל ווערען מענטשען, וועט מען נאָכדעם בעטען מען זאָל זיין חסידים.\nט. אַמאָל<sup data-n=\"692\">9</sup> בין איך געגאַנגען שפּאַ­צירן מיט'ן טאַטן אין ראָסטאָוו. שפּאַצי­רנדיג אויף אַ געוויסע גאַס זיינען מיר צוגעקומען צו אַ הויז וואו מען האָט געאַרבעט נייע מאַשינען. דער טאַטע האָט זיך אָפּגעשטעלט און זיך צוגעקוקט צו די נייע מאַשין און אַ זאָג געטאָן: אַ טיפע המצאה.\nצוריק­גייענדיק, זאָגט דער טאַטע אַז מען דאַרף זיך פאַרטראַכטן וואָס מ'קען דערפון אָפּלערנען אַ ענין אין עבודה. וואָרום עס איז דאָך דאָ אַ כוונה אין די השגחה פרטית: אַז פּונקט יעצט איז מען געגאַנגען שפּאַצירן און גראַדע אויף די",[["692","9","ראה שיחת ליל ב' דחה\"פ תש\"ח. יום אחש\"פ תש\"ט (לקמן ע' 204. ע' 322). וראה גם שיחת יום ב' דחה\"ש שנה זו (לקמן ע' 133)."]]],[4301620305,"גאַס און אָנגעטראָפן צו זען די נייע מאַשין, דאַרף מען דערפון עפּעס אָפּ­לערנען אין עבודה.\nאָט אַזוי איז די דרכי החסידות, אַז קיין זאַך איז ניט קיין גולם; יעדער זאַך וואָס מען זעט — רעדט און דערציילט, דאַרף מען דערפון עפּעס אָפּלערנען אין עבודה<sup data-n=\"693\">10</sup>.\nי. ווען איך בין געווען אַ קינד האָט דער טאַטע מיט מיר עטלעכע מאָל געלערענט די הגדה של פסח<sup data-n=\"694\">11</sup>. ער פלעגט מיט מיר אַלעמאָל לערנען אביסל העכער ווי איך האָב געקענט פאַרנעמען, מער ווי מיין בית קיבול האָט פאַרנומען. וואָס אַזוי איז דער דרך החינוך והשפעה, ניט נאָר ממלא זיין דעם בית קיבול פון תלמיד, נאָר צו מאַכען אַ טיפערען תוך אין דעם בית קיבול, אַז ער זאָל קענען צונעמען העכער ווי זיין בית קיבול פאַרנעמט.\nדער טאַטע האָט מיר אַזוי געלע­רענט:\n\"סדר של פסח\":\nפסח מלשון דילוג<sup data-n=\"695\">12</sup>, איבערשפּרינגען פון גאָר גאָר אונטען ביז גאָר גאָר הויך, פונדעסטוועגען איז אין דילוג אויך דאָ אַ סדר.\n\"יסדר על שולחנו קערה בג' מצות זה על זה, הישראל ועליו הלוי ועליו הכהן\":\nדער יסוד איז ישראל, \"ועליו\" — מלשון עלי': \"ועליו הלוי ועליו הכהן\" — מדריגת ישראל קען נתעלה ווערן צו מדריגת כהן.\nדורך וואָס קען מען צוקומען צו די עלי', דאָס איז דורך עבודת התפלה. דער דאַוונען אַליין איז גוט, אָבער דער דאַוונען דאַרף האָבן אַ \"פאַרן\" דאַוונען — מ'קען וויינען און שוויצן אין דאַוונען, אָבער אויב ער האָט נאָכדעם דעם הרגש אַז ער האָט עפּעס אויפגעטאָן — טויג עס ניט. דער \"פאַרן\" דאַוונען דאַרף האָבן קריאת שמע שעל המטה — אויסוויינען זיך אין קריאת שמע שעל המטה. דער קריאת שמע שעל המטה דאַרף האָבן די החלטה אַז מ'דאַרף ווערן בעסער, שטרעבען צו אַ עלי'. און דורך דעם גייט מען אַריין אין די טיר פון תפלה.\nיא. ניגנו ניגון שמח. אח\"כ אמר כ\"ק אדמו\"ר שליט\"א:\nאַז מ'גייט אין ?ַאי (קאַמפף) גייט מען מיט אַ פריילעכן מאַרש<sup data-n=\"696\">13</sup>. אַ סאָלדאַט אַז ער טראַכט צו קומען אַהיים אַ שלם בגופו, איז ער קיין סאָלדאַט ניט. אַ סאָלדאַט אַז ער גייט אין מלחמה טראַכט ער נאָר מנצח זיין דעם שונא. פריער דאַרף ער וויסען אַז דער מנגד איז אים אַ שונא אין נפש, און ניט נאָר אים אַליין, נאָר זיין ווייב און זיינע קינדער און אַלעמען; און ער דאַרף אים מנצח זיין — ניט נאָר כובש זיין, נאָר מוחה זיין ד. ה. אָפּמעקן דעם שונא אינגאַנצען. איז אַז דער סאָלדאַט גייט אין ?ַאי, גייט ער מיט אַ מאַרש.\nאָט אַזוי איז אויך אין עבודת התפלה,",[["693","10","ראה גם ספר השיחות קיץ ה'ש\"ת ע' 11. 73. 133. כתר שם טוב (הוצאת קה\"ת, תשנ\"ט) הוספות סימן רכג ואילך. וש\"נ."],["694","11","ראה גם שיחת יב תמוז שנה זו (לקמן ע' 140). רשימת היומן חג הפסח תרצ\"ה (\"רשימות\" חוברת צ ע' 6)."],["695","12","ראה פרש\"י בא יב, יא. שם, יג."],["696","13","ראה ספר השיחות תש\"ה ע' 3. ע' 59. שיחות: י\"ט כסלו ויום אחש\"פ תש\"ט (לקמן ע' 290. ע' 323). לקו\"ש חכ\"ד ע' 320."]]],[4301620306,"דאַרף מען זינגען אַ פריילעכן ניגון. אין ניגונים זיינען פאַראַן ניגונים פון התפשטות און עצמית'דיגע ניגונים — אויסער די טאַנצענדיגע ניגונים וואָס זיינען \"קיי­שפּיי\", פאַראַן ניגונים וואָס זיינען מעורר שמחה, און פאַראַן ניגונים וואָס זיינען מעורר מרירות. אין דאַוונען דאַרף מען האָבען שמחה, און אין קריאת שמע שעל המטה — מרירות, דערפאַר איז אין דאַוונען דאַרף מען זינגען אַ ניגון של שמחה.\nדי חב\"ד ניגונים זיינען עצמית'דיגע, ובפרט די ניגונים פון אַ רבי'ן, און בפרט דער ניגון פון די פיר פעהל, וואָס דאָס קלאַפּט אָן אין די טיר פון רבי'ן אין געה\"ע, אַז דער רבי זאָל נמשך ווערען צו זיינע חסידים הנמשכים אחריו<sup data-n=\"697\">14</sup>.\nכ\"ק אדמו\"ר שליט\"א צוה לנגן את הניגון של הד' בבות מאדמו\"ר הזקן נ\"ע. ובכה הרבה בעת הניגון.\nניגנו עוד ניגונים: \"האָפּ קאָזאַק\" ועוד ניגונים שמחים, ואח\"כ בירך כ\"ק אדמו\"ר שליט\"א ברכת המזון. השיריים מהכוס מסר תיכף להר\"א סימפסאָן לחלק להמסובים.",[["697","14","ראה גם שיחת פורים שנה זו (לעיל ע' 101)."]]],[4301620307,"<h3>קטע משיחת ל\"ג בעומר, תש\"ז<sup data-n=\"698\">1</sup></h3>\nא. הוד כ\"ק רבינו הזקן איז געווען אַ של\"ה איד<sup data-n=\"699\">2</sup>. דאָס הייסט ער האָט געלערנט דעם של\"ה און געדאַוונט מיט די כוונות פון של\"ה. און בכלל אין אַלע זיינע הנהגות האָט ער זיך געפירט ווי די גדולי התורה אין יענעם זמן.\nכידוע, פלעגן די לומדים אין יענעם זמן זיך האַלטן אָפּגעזונדערט פון די פּראָסטע אידן, וועלכע זיינען ברובם גע­ווען בעלי מלאכות, שוסטער, שניידער און אויך מאַרק הענדלער און דאַרפס­גייער.\nדי רבנים, שוחטים, מלמדים און סתם לערנער פלעגן זיך אָפּזונדערן פון די פּראָסטע אידן אפילו אויך אין די בתי מדרשים.\nדי התבדלות איז דערגאַנגען אַזוי ווייט, ביז מען האָט זיך אָנגעהויבן שעמען מיט די פּראָסטע אידן, מען האָט זיי זעלטן געגעבן אַ עלי', די יאָרצייטן און אבלים פון די פּראָסטע אידן האָט מען ניט גערן צוגעלאָזן צום עמוד.\nהוד כ\"ק רבינו הזקן האָט געהאַט יונגע לייט, גדולים בתורה, פאַר וועלכע ער פלעגט זאָגן אַ שיעור גמרא והלכה, און זיי האָבן געהאַט זייער אייגענעם מנין און האָבן זיך מתרחק געווען בכל מיני ריחוק והבדלה פון די פשוטע אידן.\nווען הוד כ\"ק רבינו הזקן איז צוריקגעקומען פון מעזריטש, האָבן זיינע תלמידים יונגע לייט באַמערקט אַ שינוי אין זיין הנהגה בהנוגע צו די פּראָסטע אידן. ניט נאָר האָט ער אויפ­געהערט זיך מתרחק זיין פון זיי, נאָר ער האָט זיי גאָר אָנגעהויבן מקרב זיין<sup data-n=\"700\">3</sup>.\nביי די יונגע לייט איז די זאַך גע­",[["698","1","נדפס עם מ\"מ והערות מכ\"ק אדמו\"ר נשיא דורנו בסה\"מ תש\"ח ע' 190 ואילך."],["699","2","[ראה שיחת פורים שנה זו (לעיל ע' 99). וש\"נ."],["700","3","ראה שיחת י\"ג אלול שנה זו. שיחת י\"ט כסלו תש\"ח (לקמן ע' 149. ע' 181)."]]],[4301620308,"וואָרן זייער מוקשה, זיי האָבן אָבער ניט געהאַט די דרייסטקייט צו פרעגן אים וועגן דעם.\nהוד כ\"ק רבינו הזקן האָט מרגיש געווען אַז די יונגע לייט זיינען פאַר­וואונדערט אויף זיין נייער הנהגה.\nהאָט הוד כ\"ק רבינו הזקן דאַן פאַר זיי איבערגעזאָגט די תורה וואָס דער מעזריטשער מגיד האָט אים איבערגע­געבן בשם מורנו הבעש\"ט<sup data-n=\"701\">4</sup>:\nהוּלט האָבן אַ אידן איז אַ מצוה דאורייתא. אין יעדער מצוה איז פאַראַן די עשה פון דער מצוה און די לא תעשה. און אַזוי אויך אין דער מצוה פון אהבת ישראל איז ואהבת לרעך<sup data-n=\"702\">5</sup> די עשה און לא<sup data-n=\"703\">6</sup> תשנא את אחיך<sup data-n=\"704\">7</sup> די לא תעשה. די פשיטות פון דעם פשוטן אידן, זיין תפלה, זיין זאָגן תהלים נאָכן דאַוונען, זיין טאָן אַ מצוה ווייל השי\"ת האָט געהייסן, איז גורם אַ נחת רוח למעלה<sup data-n=\"705\">8</sup>.\n* * *\nדי חסידישע הדרכה איז אַז יעדער איד, אָן אונטערשייד, אַ למדן צי אַ פשוטער, בעדאַרף זיך אַליין שטעלן די פראַגע צו וואָס בעדאַרף מען מיך אויף דער גשמיות'דיקער וועלט. די נשמה איידער זי איז אַראָפּ אין גוף האָט דאָך געלעבט למעלה אין געטלעכקייט, און אַראָפּקומענדיק למטה אין גוף מוז זי זיך דאָך אָנטאָן אין גשמיות'דיקע זאַכן, וואָס דאָס איז דאָך אַ גרויסע ירידה פאַר דער נשמה, וכמאמר \"ירידת הנשמה בגוף\".\nאָבער די ירידה איז \"צורך עליה\", אַז דוקא דורך דער ירידה קומט די נשמה צו די העכסטע דרגות אין געטלעכקייט, און אָט די פשוטע אידן מיט זייער הנהגה פשוטה, באַלד אויפשטייענדיק לויפן דאַוונען בצבור, זאָגן אַ קאַפּיטל תהלים און ענטפערן אמן און אמן יהא",[["701","4","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."],["702","5","קדושים יט, יח."],["703","6","שם, יז]."],["704","7","כשיראה לו שנאה וידע שהוא שונאו אינו עובר ע\"ז הלאו, אמנם עובר על לא תקום ולא תטור (ס' החינוך מצוה רלח), בכ\"ז כתב כאן ל\"ת דלא תשנא. וי\"ל: א) ע\"פ מש\"כ הרמב\"ם הל' דעות פ\"ו ה\"ה. אבל לכאורה אין זה מספיק, שהרי ברמב\"ם שם מבאר בזה: ולא הזהירה תורה אלא כו'. וראה ג\"כ שם ספ\"ז (ע\"ד מש\"כ בס' החינוך). וי\"ל ב) מפני שלא תשנא — היא קודמת והסיבה (בנפש האדם) ל\"לא תקום ולא תטור\" — כמובן. ג) ס\"ל בדברי הרמב\"ם כהכס\"מ שם דגם כשמראה השנאה עובר. וידוע שקו\"ט האחרונים בדברי הכס\"מ ובהסתירה מסהמ\"צ להרמב\"ם מל\"ת שב [קונטרס אהבת ישראל (קה\"ת, תשל\"ז) ע' 9 בהערה]."],["705","8","[בהנחה בלתי מוגה: אַז דער אַלטער רבי איז געקומען דעם ערשטן מאָל פון מעזריטש, איז ער שוין געווען אין אַ מדריגה פון אַ משפיע, ער האָט געהאַט אַ סאַך תלמידים. האָבן זיי אים געפרעגט וואָס פאַר אַ חידוש האָט ער געהערט אין מעזריטש? האָט דער אַלטער רבי געענט­פערט, אז ער האָט דאָרט געהערט אַ נייעם פירוש אויף דעם \"אהבתי אתכם אמר ה'\" (מלאכי א, ב) — האָלט האָבן אַ אידן ווייל ער איז אַ איד. אין מעזריטש האָט ער געקראָגן אַ חוש אין האָלט האָבן אַ אידן, און דאָס האָט אים געגעבן אַ ליכ­טיקייט אין אהבת השם.\nאין יענעם זמן זיינען דאָך פשוטע אידן גע­ווען אָפּגעפרעגט, עס זיינען געווען באַזונדערע מנינים פאר זיי: אַ שניידערשע שול, אַ שוסטער שול, אַ בעל עגלה שול.\nדער אַלטער רבי האָט געלערנט אַז מען דאַרף האָלט האָבען אַ פשוטן אידן; ניט נאָר מביני מדע, די דריי­קעפּלעך, נאָר די פשוטע אידן וואָס אין זיי איז פאַראַן די פשיטות העצמות."]]],[4301620309,"שמי' רבא, שאַפן דעם גרעסטען קורת רוח למעלה<sup data-n=\"706\">9</sup>.\n* * *\nזקני<sup data-n=\"707\">10</sup> החסידים פלעגן דערציילן וואָס זיי האָבן מקבל געווען פון די זקני החסידים הראשונים פון ליאָזנע דעם סיפור הידוע<sup data-n=\"708\">11</sup> וועגן איינעם פון די גבירים חסידים, וועלכע זיינען געווען שטאַרק מקושר צו הוד כ\"ק רבינו הזקן און פלעגן געבן גרויסע סכומים געלט לרבינו הזקן אויף החזקת ארצנו הקדושה און אויף פדיון שבוים.\nאיינער אַזאַ חסיד, וועלכער איז גע­ווען אַ גרויסער עושר, האָט שוין חתונה געמאַכט די קינדער און די קינדער זיינען אויך געווען גוט אָפּ, האָט זיך אָנגענומען חתונה מאַכן די קינדער פון זיינע קרובים און צוגעזאָגט פאַר זיי פיינע נדנ'ען, און בכלל געפירט אַ רייכן שטאט, איז אָבער מיט אַמאָל געוואָרן נתהפך הגלגל און ער איז געוואָרן אַ יורד ר\"ל, געבליבן אַ גרויסער אביון און דערצו נאָך אַ גרויסער בעל חוב. איז ער אַוועקגעפאָרן צום אַלטן רבי'ן און האָט פאַר אים אויסגעגאָסן זיין ביטער האַרץ.\nאויסהערנדיק זיין מצב האָט דער אַלטער רבי אויפגעהויבן דעם קאָפּ און געזאָגט, מיט אַ ניגון, כדרכו בקדש הקדשים: דו האָסט אַלץ דערציילט,",[["706","9","בהנחה בלתי מוגה: דער ענין בקצרה איז: די ירידת הנשמה למטה איז דאָך אויף להתלבש בגוף, וואָס דער גוף מיט זיינע מעשה'לאַך איז דאָך ניט אַזאַ שיינער מהות; וואָס די כוונה אין דער ירידה איז ניט נאר להעלות הנשמה למעלה ממדריגתה נאָר אויף מעלה זיין דעם כללות העולם ווי דער משל הידוע פון דעם \"ליווער\" (ראה תו\"א ד, א), און דער אהבתי אתכם וכו' איז דאָך אויף דער נשמה המלובשת בגוף. אהבת ישראל איז צו אַלעמען גלייך, האָלט האָבן אַ פשוט'ן אידן וויילע ער איז אַ איד, וואָס די פשיטות העצמות איז אין אַ פשוט'ן אידן, און אַ איש פשוט איז פשיטות העצמות.\n{* * *}\nדער טאַטע האָט אַמאָל געזאָגט אַז דער עיקר ענין המוחין איז צו פאַרשטיין די מעלה פון פשיטות; ניט פשיטות וואָס קומט מצד השכל, נאָר פשיטות בעצם<sup data-n=\"e15\">*</sup>.\nמען דאַרף ליגן אין אַ ענין. אַז מען לעבט זיבעציג יאָר — איך מיין ניט בלויז לעבן, נאָר לעבן זיבעציג יאָר אין עבודה — דאָס מיינט לעבן הונדערט יאָר און טאָן זיבעציג יאָר אין חסידות — קאָן מען פאַרשטיין וואָס פשיטות איז.\nאַלע מעלות וואָס מען רעדט אין עצמות קומט דאָס ניט צו די מעלת הפשיטות, און די פשיטות העצמות איז אין אַ איד פשוט<sup data-n=\"e16\">**</sup>.\nאַ פשוט'ער איד, אַז ער שטייט אויף אינדער­פרי, זיין אמונה, זיין זאָגן אַ קאַפיטל תהלים פאַרן דאַוונען, זיין דאַוונען [אַ איד זאָגט ניט אַז ער דאַרף אָפּדאַוונען, ער האָט אָפגעדאַוונט; נאָר זאָגט: ער האָט געדאַוונט, ער האָט נאָך ניט געדאַוונט, ער דאַרף גיין דאַוונען וכו']. ער האָט האָלט תפילין; ער האָט האָלט אַ אידן; דאָס איז זיין פנימיות, דאָס איז ער בעצם. ער מאַכט חתונה קינדער און טראַכט ניט פון וואַנען וועט ער נעמען, מען דאַרף דאָך האָבן אַ עקזיסטענץ כמו שאומרים אוה\"ע, און ער טראַכט דאָס ניט, ער האָט בטחון."],["707","10","בהנחה בלתי מוגה: מען דאַרף זיך שטענדיג פרעגן: אויף וואָס דאַרף מען מיך דאָ. ובנוסחא אחרת: אויף וואָס דאַרף מען זיך, פרעגט מען ניט."],["708","11","ראה בארוכה אגרות­-קודש ח\"ט ע' רעג ואילך. מקומות שצויינו בהערה הבאה."],["e15","*","נוסחא אחרת: אז דער גאַנצער ענין פון מוח איז נאָר אויף צו פאַרשטיין דעם ענין הפשיטות, ניט שכל'דיג פאַרשטיין פשיטות, נאָר דערהערן דעם ענין הפשיטות."],["e16","**","נוסחא אחרת: וואָס פשיטות העצמות איז פאַראַן באַ אַ פשוטן אידן. — ראה לעיל ע' 3. וש\"נ."]]],[4301620310,"וואָס דו דאַרפסט, און אויף וואָס דאַרף מען דיך זאָגסטו<sup data-n=\"709\">12</sup> גאָר ניט!\nדער חסיד איז געפאַלן חלשות און דער משרת האָט אים אַרויסגעפירט פון רבינס חדר. קומענדיק צו זיך האָט ער זיך גענומען באַטראַכטן וואָס דער רבי האָט אים געזאָגט, האָט ער אויף אַלץ פאַרגעסן און זיך גענומען צו תורה ותפלה כראוי.\nנאָך אַ געוויסער צייט האָט הוד כ\"ק רבינו הזקן געהייסן אים אַריינרופן.\nווען דער חסיד האָט דערהערט, אַז הוד כ\"ק רבינו הזקן רופט אים איז ער געוואָרן זייער צובראָכן, באַרעכנענדיק זיך נאָך אַמאָל און נאָך אַמאָל דעם מאמר הקדוש, וואָס כ\"ק רבינו הזקן האָט אים געזאָגט \"דו זאָגסט אַלץ וואָס דו דאַרפסט אָבער אויף וואָס דאַרף מען דיך זאָגסטו ניט\", האָט ער זייער גע­וויינט, געפאַסט און געטאָן אין עניני עבודה.\nווען ער איז אַריין להוד כ\"ק רבינו הזקן איז ער געווען ביי זיך צובראָכן כחרס הנשבר, האָט אים הוד כ\"ק רבינו הזקן געזאָגט:\nאיצטער אַז דו ווייסט און פילסט דעם אמת הוי' לעולם<sup data-n=\"710\">13</sup>, אַז דער אמת איז הוי' הי' הוה ויהי' כאחד<sup data-n=\"711\">14</sup>, און צו דעם אמת קומט צו אַ נשמה בגוף, קענסטו שוין פאָרן אַ היים און דער אויבערשטער ברוך הוא זאָל דיר מצליח זיין.\nאון אַזוי איז געווען<sup data-n=\"712\">15</sup>.\n* * *\nדער טאַטע האָט אַמאָל איינעם גע­זאָגט<sup data-n=\"713\">16</sup> אַז עס זיינען דאָ צוויי נאַראָנים. עס איז דאָך אַ גלגל החוזר בעולם<sup data-n=\"714\">17</sup>. איז דער וואָס זיצט אויף דעם ראָד און לאַכט איז ער דאָך אַ נאַר. שוטה, וואָס לאַכסטו, עס איז דאָך נאָר אַ ראָד. דער וואָס זיצט אונטער דעם ראָד און דער",[["709","12","ראה לקמן הוספה א<sup data-n=\"e17\">*</sup> נוסחא אחרת<sup data-n=\"e18\">**</sup>. וראה ג\"כ התמים ח\"ה ע' נג<sup data-n=\"e19\">***</sup>. ואפשר שאירע כעין זה פעמים אחדות<sup data-n=\"e20\">****</sup>."],["710","13","[תהלים קיז, ב."],["711","14","זח\"ג רנז, סע\"ב (ברע\"מ). פרדס שער א (שער עשר ולא תשע) פ\"ט. שעהיוה\"א פ\"ז (פב, א)."],["712","15","בהנחה בלתי מוגה: אַרויסגייענדיק האָבען אים חסידים מסביר געווען: פריער האָסטו געמיינט אַז דו ביסט אַ מאַכער, דו האָסט זיך רייך געמאַכט און דו האָסט זיך אָרעם געמאַכט, האָסט געמיינט אַז כחי ועוצם ידי וכו'; אָבער איצט אַז דו ווייסט שוין אַז אַלץ איז פון אויבערשטען קענסטו אַהיים פאָרען און דער אויבערשטער וועט העלפן. ונסע לביתו והצליח ונעשה גביר]."],["713","16","בארוכה בשיחת שמח\"ת תרצ\"ו אות יג [ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 32 ואילך. וש\"נ."],["714","17","ראה שבת קנא, ב]."],["e17","*","סה\"מ תש\"ח ע' 194 (אגרות­-קודש ח\"ג ע' קכ)."],["e18","**","וז\"ל: באזני מצלצל אותו המאמר אשר אמר הוד כ\"ק מורנו הגדול נ\"ע בעת שהחסיד משקלאוו התאונן לפניו על מר מצבו וכי דרוש לו לשלם חובות, להשיא את בנותיו, ושיהי' לו לחם חקו.\nהשיב הוד כ\"ק מורנו הגדול. . \"דו זארגסט אלץ אויף דעם וואָס דו בעדאַרפסט, אויף דעם אויף וואָס מען דאַרף דיך זאָרגסטו גאָרניט\"."],["e19","***","נדפס באגרות­-קודש ח\"ג ע' תלט ואילך."],["e20","****","ראה אגרות­-קודש ח\"ב ע' תקמא: \"ספור זה שמעתי מאתו כפי ששמען בכמה נוסחאות, כי ענין זה הי' עם איזה חסידים בזמנים שונים\". ובאגרות­-קודש ח\"ג ע' קנה: \"דוא זאָגסט (נ\"א דוא זאָרגסט) אַלץ ואָס דו בעדאַרפסט אויף ואָס מיא דאַרף דיך זאָגסט (נ\"א זאָרגסטו) גאָר ניט\". וראה גם שיחת ל\"ג בעומר תש\"ח (לקמן ע' 225). לקמן ע' 251 הערה 70. סה\"מ תרפ\"ט ע' 159."]]],[4301620311,"ראָד איז אויף אים וויינט. איז ער אַ נאַר. וואָס וויינסטו, עס איז דאָך אַ ראָד אַ גלגל החוזר.\nאַז מען איז רייך און מען איז אויפן ראָד, בעדאַרף מען טראַכטן, אַז עס איז מער ניט ווי אַ ראָד, וואָס דרייט זיך כסדר און עס האָט ניט קיין קיום לדורות, אָבער אַ פסוק חומש, אַ פסוק תהלים, טאָן אַ טובה אַ אידן, דאָס איז אַ דבר המתקיים. עס האָט אַ נצחיות'דיקן לעבן און בריינגט נצחיות'דיקע פירות און פירי פירות, וכמאמר<sup data-n=\"715\">18</sup> זכות אבות לא תמו און לא יתמו לעד ולנצח נצחים.\n* * *\nמען דאַרף זיין בשמחה. אַז מ'קוקט זיך צו צו זיך געפינט מען אַמאָל פלעקן וואָס מ'דאַרף אויסוואַשען, אָבער דאָס דאַרף אַלץ זיין בשמחה.\n* * *\nעס איז דאָ אַ קורצע תורה פון הוד כ\"ק רבינו הזקן פון די ערשטע יאָרן פון זיין נשיאות<sup data-n=\"716\">19</sup>, וועלכע ער האָט געזאָגט בשם רבו, דעם מעזריטשער מגיד בשם מורינו הבעש\"ט:\nאהבת ישראל מיינט האָלט האָבן אַ אידן אַן קיין שום חילוק, צי אַ למדן צי אַ פשוטער איד, און דער אופן האהבה אין אהבת ישראל בעדאַרף זיין אַ ברידער­לעכע<sup data-n=\"717\">20</sup>, וואָס די התגלות האהבה איז אין נשיקה<sup data-n=\"718\">21</sup>, אָט אַזוי ווי אהבת התורה איז, אַז מען איז מחבב און מייקר די מענטעלע פון אַ ספר תורה<sup data-n=\"719\">22</sup>.\n* * *\nאַה! וואָס פאַר אַ געשמאַקע זאַך אַ איד איז. דער אויבערשטער ווייסט דאָך וואָס פאַר אַ געשמאַקע זאַך אַ איד איז, האָט ער דאָך אים געדאַרפט געבן עס זאָל זיין גוט אין גשמיות און אין רוחניות.\nווען איך בין נאָך געווען גאָר יונג, איז געווען אַ זמן וואָס עס איז געווען, ל\"ע, אַ עת צרה, ר\"ל פאַר אידן. פרנסה איז געווען זייער שווער, און בכלל די רדיפות מצד הממשלה אין דאַמאָלסטיקן רוסלאַנד. — ליובאַוויטש איז געווען אויפן גרעניץ פון \"טשערטא\" (תחום המושב<sup data-n=\"720\">23</sup>) לעבן סמאַלענסק, און טאָמער, אַ איד פלעגט אַריבערגיין די גרעניץ",[["715","18","מחלוקת בשבת (נה, א) אבל כן הוא המסקנא בויקרא רבה (פל\"ו, ו). ועיג\"כ ירושלמי סנהדרין פ\"י ה\"א. אגדת בראשית פ\"י. זח\"א קסח, א. זח\"ג קעד, א. ת\"ז תי' כ\"א (נז, ב). תיקונים מזהר חדש (קיג, ע\"ד)."],["716","19","[בהנחה בלתי מוגה: וואָס ער האָט געזאָגט אין די ערשטע צייטען — דאַמאָלסט האָט דאָס ניט געהייסען מאמרים נאר צעטלען — אַ פּאָר שורות וואָס ער האָט געזאָגט אויף טייטש אז אַלע זאָלן פאַרשטיין. — איז דאָ אַ תורה פאַר­שריבען אויף אַ צעטיל]."],["717","20","מעלתה שאינה פוסקת ואין בה שינוים. ראה לקו\"ת ר\"פ בהר ועוד."],["718","21","שהיא באה ונמשכת מחמת פנימיות אהבה שבלב, שאותיות הדבור אין יכולים להכיל אה\"ר זו. לכך אינה מתלבשת בדבור רק בבחי' נשיקין (תו\"א ס\"פ תרומה. וראה ג\"כ לקו\"ת שה\"ש בתחילתו)."],["719","22","[בהנחה בלתי מוגה: אַז מען טרעפט אַ אידן אין גאַס, דאַרף מען אים אַ קוש טאָן, ווי מ'קושט אַ מענטעלע פון אַ ספר תורה<sup data-n=\"e21\">*</sup>."],["720","23","ע\"ד \"תחום המושב\" — גזירת גירוש בנ\"י מן הכפרים — ראה בארוכה \"מבוא\" לאגרות­-קודש כ\"ק אדמו\"ר מהורש\"ב ח\"ד ע' 5 ואילך. וש\"נ."],["e21","*","ראה ספר השיחות תש\"א ע' 32 (הועתק ב\"היום יום\" טז תמוז). תש\"ג ע' 139. תש\"ד ע' 163. אגרות­-קודש ח\"ח ע' פח. רשימת היומן של רבינו מיום ה', כ' מ\"ח תרנ\"ו — סה\"מ תש\"ט ע' 87."]]],[4301620312,"פון \"טשערטא\" איינקויפן אַביסל פלאקס וכדומה, פלעגט אַ פּאָליציי מאַן, וואָס האָט געוואָלט אַ טרונק בראָנפן אים אַרעסטירן וכו'.\nאין יענעם זמן איז אַמאָל געווען אַ שטאַרקער פאַרבריינגען. האָט דער טאַטע דאַן געזאָגט: דער אויבערשטער ווייסט דאָך די געשמאַקייט וואָס איז דאָ אין אַ איד, דאַרף ער זיי געבן עס זאָל זיין גוט בגשמיות וברוחניות<sup data-n=\"721\">24</sup>.",[["721","24","כ\"ק אדמו\"ר שליט\"א צוה לנגן את ניגון הדביקות­חב\"ד שהיה מזמר אאמו\"ר נ\"ע בתפלת שבת, ובעת שנגנו את הניגון היה בדביקות עצומה ודמעות נזלו מעיני קדשו. אח\"כ צוה לנגן את הניגון של ד' בבות מאדמו\"ר הזקן ואח\"כ אמר:\nדעם אַלטען רבי'נס ניגון איז \"יחידות\", נאָך יחידות דאַרף מען נעמען אַ ביסעל משקה און זינגען אַ פרייליכען ניגון<sup data-n=\"e22\">*</sup>]."],["e22","*","נוסחא אחרת: נאָך יחידות דאַרף מען זינגען אַ פרייליכען ניגון און גיין אַ טאַנץ."]]],[4301620313,"<h3>ליל א' דחג השבועות תש\"ז בסעודה</h3>\nא. (במענה על שאלת א' מהמסובים אמר כ\"ק אדמו\"ר שליט\"א:) דער תקיעת שופר וואָס איז געווען אין מתן תורה האָט אַדורכגענומען דעם גאַנצען כדור הארץ.\nאין איינע פון די מאמרים וואָס דער טאַטע האָט געזאָגט שבועות, ווען איך בין נאָך געווען אַ קינד און ניט געווען בערך צו פאַרשטיין,\n— מיין מלמד ר' ניסן<sup data-n=\"722\">1</sup> פלעגט מיר דערציילען פון די אַלע מאמרים וואָס דער טאַטע האָט געזאָגט ווען איך בין נאָך געווען אַ קינד, און האָט מיר דערביי געזאָגט<sup data-n=\"723\">2</sup>: אַז דו וועסט עלטער ווערען און וועסט ביי מיר פרעגען, וועל איך דיר דאַמאָלסט זאָגען באריכות<sup data-n=\"724\">3</sup> —\nהאָט דער טאַטע געזאָגט: מן השמים השמיעך וגו'<sup data-n=\"725\">4</sup>, השמיעך איז דער פירוש, ער האָט דיר געמאַכט דערהערען, ער האָט דיר געמאַכט פאַר אַ כלי דו זאָלסט קענען דערהערען, ניט נאָר האָט מען דיר געגעבען אורות נאָר אויך כלים לקבלה, ע\"ד כלים דתיקון.\nב. עס איז אַמאָל געווען אַ שטאַר­קער פאַרבריינגען ביים טאַטן, עס האָט זיך דאַמאָלט גערעדט דער חילוק פון נפש האלקית און נפש הבהמית. האָט דער טאַטע דאַן געזאָגט:\nאיך האָב ניט ליב קיין אריכות, אריכות דאַרף זיין פאַר'ן דאַוונען און אין דאַוונען, חסידות איז איין וואָרט:\n\"עיקר החסידות איז מדות<sup data-n=\"726\">5</sup>, הבנה והשגה וואָס אין חסידות איז נאָר בשביל לעורר המדות. מדות איז צוליב דאַוונען, און דאַוונען איז צוליב מדות, דער רבי<sup data-n=\"727\">6</sup>",[["722","1","ראה אודותו לעיל ע' 41. וש\"נ."],["723","2","ראה גם שיחת ליל ב' דחה\"ס שנה זו (לעיל ע' 66)."],["724","3","ראה גם לקמן ע' 161. ע' 318. וראה לעיל ע' 66."],["725","4","ואתחנן ד, לו."],["726","5","ראה גם שיחת ליל שש\"פ שנה זו (לעיל ע' 112. ע' 117)."],["727","6","כ\"ק אדמו\"ר הזקן."]]],[4301620314,"און די רביים אחריו האָבן געהאָרעוועט אַז ביי חסידים זאָל זיין אין דאַוונען להבת שלהבת, אויסברענען די ניט גוטע מדות און אויפפלאַקערען די גוטע\".\nדער לימוד החסידות איז, אַז דער קרעמער זאָל האָבען מיט וואָס צו גיין אין קראָם, און דער מלמד מיט וואָס צו גיין אין חדר.\nאַה! ווי מען איז היינט ווייט פון די אַלע ענינים, מען איז ווייט אפילו פון דעם אַמאָליגען חסידישן מיטוואָך ומכ\"ש פון די עבודה פון שבת און יום טוב.\nאין ניגון איז דאָ דריי בבות. דער ניגון פאַרן דאַוונען, דער ניגון אין דאַוונען און דער ניגון נאָכן דאַוונען. דאָס איז אַלץ איין און דער זעלבער ניגון. דאָס זיינען די געגועים פאַרן דאַוונען, די געגועים אין דאַוונען, און די געגועים נאָכן דאַוונען.\nדער חילוק פון אַ עובד און אַ משכיל, אַ משכיל דאַווענט און אַ עובד טוט. אַ משכיל דאַווענט און איז צופרידען פון זיין דאַוונען, אָבער צו עבודה בפועל קומט דאָס ניט. אַ עובד טוט, השכלה מהיכי תיתי, אָבער זיין צו­פרידענקייט איז פון טאָן, עבודה בפועל.\nזכות אבות לא תמו<sup data-n=\"728\">7</sup>, \"זכות אבות\" די קלאָהרקייט וואָס די אבות החסידות האָבען אַריין געבראַכט, אַז מען זאָל דערהערן דעם אייגענעם ניט גוט און טאָן ווי מ'דאַרף טאָן; דאָס איז לא תמו, דאָס איז שטענדיק.\nג. מען האָט געדאַרפט מאַכען אַ קביעות לערנען דעם \"תורת שלום\"<sup data-n=\"729\">8</sup> יעדען טאָג עטלעכע שורות, מען דאַרף ניט קיין פולע, עטלעכע שורות איז גענוג, דאָרט זעט מען ווי מ'דאַרף לעבן ווי אַ חסיד.\n(על שאלת א' מהמסובים אמר:) דער לשון אין די שיחות \"תורת שלום\" איז ניט מדויק, בכלל זיינען דאָס הנחות געשריבען אין ראשי פרקים מיט דער כוונה שפּעטער זיי ממלא צו זיין און עס איז אַזוי געבליבן, אָבער דער עיקר איז דאָך ניט וואָס עס שטייט אויף דעם פּאַפּיר, מען דאַרף לעבען מיט דעם.\nד. (ניגנו ניגון ואמר א' מהמסובים: דאָס איז אַ אַלטער ניגון, ווי מ'האָט אים געזונגען אין ליובאַוויטש. וענה כ\"ק אדמו\"ר שליט\"א) אַה! די אלטע, די אַלטע ניגונים, די אַלטע ווערטער, די אַלטע הנהגות; היינט איז אַלץ טאנדעט<sup data-n=\"730\">9</sup>. אַמאָל פלעגט אַ שניידער אַליין נייען דעם בגד מיט אַ נאָדעל, ער פלעגט זיך טאַקע אַמאָל פאַרשטעכען די פינגער, אָבער דער בגד איז געווען גוט געמאַכט; היינט איז אַלץ טאנדעט, מאַשינאָווע: אַ טאנדעטנער עובד, אַ טאנדעטנער משכיל, און אַ טאנדעטנער למדן.\nה. חסידות מאָנט ניט קיין ריבוי, חסידות איז גענוג איין וואָרט נאָר צום תוך.\nעס איז אַמאָל אַ חסיד — איך וויל ניט פורש בשמו זיין — אַריין צום טאַטען אויף יחידות און זיך מתאונן געווען: מען לערנט חסידות און עס דערנעמט ניט, מען דאַווענט און עס דערנעמט ניט.\nהאָט דער טאַטע אים געענטפערט: וואָס וואונדערסטו זיך, אַז דער דאַוונען",[["728","7","ראה שיחת ל\"ג בעומר תש\"ז (לעיל ע' 127). וש\"נ."],["729","8","יצא לאור בפעם הראשונה — ברוקלין, תש\"ו."],["730","9","זול, מאיכות גרועה."]]],[4301620315,"איז ווי דער לערנען, און דער נאָכן דאַוונען איז ווי דער דאַוונען.\nמען גייט אויף יחידות און מען טאַנצט אַ ריקוד נאָך יחידות<sup data-n=\"731\">10</sup>, מען פּאַטשט מיט די הענט און מען טאָפּעט מיט די פיס און מען מיינט אַז מען איז יוצא מיט דעם קלאָגען זיך, מיט די התאוננות.\nו. (ניגנו ניגון, והעיר א' מהמסובים, שניגון זה שלח<sup data-n=\"732\">11</sup> החסיד ר' פסח מאַלאַסטאָווקער<sup data-n=\"733\">12</sup> ע\"י אברך א' לנגן לפני החסיד ר' הלל מפּאַריטש נ\"ע<sup data-n=\"734\">13</sup>.\nוענה כ\"ק אדמו\"ר שליט\"א): יע, מען האָט געזונגען דעם ניגון אָדער אַן אַנדערן ניגון, אָבער דער זינגען איז געווען צוליבן דאַוונען, און אַז מ'האָט געדאַוונט האָט זיך במילא געזונגען.",[["731","10","ראה לעיל ע' 110. וש\"נ."],["732","11","ראה ספר הניגונים ח\"א ע' נד."],["733","12","מצעירי חסידי רבינו הזקן ואח\"כ מחסידי אדמו\"ר האמצעי והצ\"צ. מכתב ממנו נדפס ב\"התמים\" חוברת ו ע' סב [רחצ, ב] ואילך. ראה אודותו: אגרות­-קודש ח\"ו ע' קעא. ספר השיחות תרפ\"ח­תרצ\"א ע' 244. תרצ\"ו­ה'ש\"ת ע' 221. ועוד."],["734","13","ראה אודותו לעיל ע' 29. וש\"נ."]]],[4301620316,"<h3>יום ב' דחג השבועות תש\"ז בסעודה</h3>\nא. ווען דער אַלטער רבי איז געגאַנגען פון מעזריטש<sup data-n=\"735\">1</sup> און איז דורכגעגאַנגען שקלאָוו, האָט ער דאָרטן געזאָגט אַ תורה, אַ \"ווערטער­תורה\"\n— ווי מ'האָט שוין אַמאָל דערציילט<sup data-n=\"736\">2</sup> אַז אין די ערשטע צייטן פון די נשיאות פון אַלטן רבי'ן האָט ער געזאָגט קורצע תורות וואָס מ'האָט גערופען: \"ווערטער\" —\nער האָט געזאָגט: \"נשמות זיינען פנימיים און מלאכים זיינען חיצוניים\"<sup data-n=\"737\">3</sup>.\nאיז געוואָרן אַ גרויסער טומעל, עס האָט זיך איבערגעקערט אַ וועלט; צו זאָגען אַזאַ זאַך, ובפרט אַזאַ למדן זאָל דאָס זאָגען.\nהאָבן זיי אים געפרעגט: פון וואַנען איז די ראי'? אַלץ דאַרף האָבען אַ ראי' פון דער תורה.\n— בכלל האָבן דאַמאָלסט די עולם'עשע געהאַט טענות צום בעש\"ט, אַז ער האָט פאַרפּראָסטעט די תורה און די אידן, דער בעש\"ט האָט דאָך מקרב געווען פּראָסטע אידן און פלעגט פאַר זיי זאָגן תורה בפשיטות —\nאַז דער רבי — אדמו\"ר הזקן — האָט גערעדט די מעלה פון נשמות אויף מלאכים, אַז נשמות זיינען פנימיים און מלאכים חיצוניים; האָבן זיי אים גע­פרעגט פון וואַנען איז די ראי'?\nהאָט דער רבי זיי געענטפערט: עס איז דאָך אַ פסוק:\nאַז די מלאכים זיינען געקומען צו אברהם אבינו שטייט: \"ויאכלו\"<sup data-n=\"738\">4</sup> — זיי האָבן זיך געמאַכט ווי זיי עסן, נראין",[["735","1","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."],["736","2","ראה גם שיחת ליל שש\"פ שנה זו (לעיל ע' 111). וש\"נ."],["737","3","ראה תניא אגה\"ת פ\"ד. סה\"מ תרנ\"ז ע' ערה. ועוד."],["738","4","וירא יח, ח."]]],[4301620317,"כאוכלין<sup data-n=\"739\">5</sup>, זיי האָבן ניט געגעסען נאָר זיי האָבן באַוויזן ווי זיי וואָלטן געגעסן, איז דאָס דאָך ע\"ד ווי אַ \"חיצון\" — ער מאַכט זיך פאַר אַ בקי און פאַר אַ למדן און באמת איז ניט אַזוי, לייגט ער דאָך. אָבער נשמות, וואו זיי געפינען זיך זיינען זיי ווי דער אמת איז: אַז משה רבינו איז עלה בהר, שטייט אַז \"לחם לא אכל ומים לא שתה\"<sup data-n=\"740\">6</sup>, אַ נשמה למטה עסט — דאָס איז דער סוד הבירורים, אָבער אַז די נשמה איז עולה למעלה — איז \"לחם לא אכל ומים לא שתה\". דערפאַר ווערן מלאכים אָנגערופען חיצוניים און נשמות פנימיים.\nדער חילוק פון אַ למדן און אַ איש פשוט איז: אַ למדן איז אַ בעל מוח, במילא איז דאָ חילוקים: אַ געשמאַקע תורה, ניט קיין געשמאַקע, אַ הפלאה'­דיקע תורה. אָבער ביי אַ איש פשוט איז דאָך אַלץ בהשוואה, דער ואמת הוי' לעולם<sup data-n=\"741\">7</sup> פון פשיטות העצמות דערהערט זיך ביי דעם איש פשוט<sup data-n=\"742\">8</sup>.\nוואָס איז דער וואונדער, אַז מען האָט אַמאָל געלעבט מיט אַ חסידישען וואָרט וואָס מ'האָט געהערט, אַז מען האָט דעם וואָרט אַראָפּגעטראָגן פון למעלה מן המוח ביז דעם כף הרגל<sup data-n=\"743\">9</sup>, מען האָט אויסגעמושטירט דעם גוף אַז ער זאָל לעבן מיט אַ וואָרט חסידות.\nב. דער זיידע האָט געלערנט מיט דעם טאַטן דעם סידור; לבד וואָס ער האָט מיט אים געלערנט דעם ביאור עפ\"י חסידות, האָט ער מיט אים גע­לערנט דעם פשוט'ן פירוש המלות פון סידור, אַמאָל מיט מער ביאור און אַמאָל דעם פירוש המלות אַליין.\n\"מודה אני לפניך\": אַז מען איז \"מודה\", דאַן איז מען \"אני לפניך\" — מען איז \"אני\" וואָס דערהערט ווי מען איז געשטאַנען \"לפניך\"; דאַן איז די התבוננות אין \"מלך\", און ס'קומט אַראָפּ אין אַ בפועל אין \"רבה אמונתך\" אַ הגדלה אין אמונה<sup data-n=\"744\">10</sup>.\nאזוי האָט דער זיידע געלערענט מיט דעם טאַטען. האָט דער טאַטע געזאָגט אַ ביאור אויף דעם אַז \"מודה\", דאָס איז די הגבלה אין דברי הרב — אַזוי האָט דער רבי געזאָגט; און דאָס גופא גיט אַ כח אין \"רבה אמונתך\", די הגדלה אין אמונה — ניט נאָר גלויבן, נאָר מען זאָל פאַרשטיין וואָס מען גלויבט.\nג. מזגו כוס משקה לכ\"ק אדמו\"ר שליט\"א ושאל אם זה מהמשקאות שאין עליהם חשש. וענה אחד מהרבנים המסובים: בטח, על הבקבוק כתוב מפו­רש: \"פשוט ונקי\".\nואמר כ\"ק אדמו\"ר שליט\"א: מען קאָן זיי גלויבן? עס איז דאָך אַ פאַרפאַל­שעוועטע וועלט. ויאמר א' מזקני ה­רבנים: זהו דבר שאין הצבור יכולים לעמוד בו.\nוענה כ\"ק אדמו\"ר שליט\"א: פונ­דעסטוועגען צו \"ניט\" קומט דאָס ניט.\nדער טאַטע האָט אַמאָל געזאָגט, אַז פון אַ גשמי דאַרף מען זיך זייער היטן. אין רוחניות, אויב דאָס איז ניט אַזוי מכוון, נו! איז דאָס אַ נידעריקע מדריגה, אָבער אַז דער גשמי איז ניט מכוון, איז זייער פּאַסקודנע.",[["739","5","ב\"ר פמ\"ח, יד. ב\"מ פו, ב. פרש\"י עה\"פ."],["740","6","תשא לד, כח. וראה ב\"ר שם."],["741","7","תהלים קיז, ב."],["742","8","ראה גם לעיל ע' 3. וש\"נ."],["743","9","ראה גם ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 345."],["744","10","ראה גם ספר השיחות שם ע' 240."]]],[4301620318,"החסיד ר' אייזיל<sup data-n=\"745\">11</sup> איז געווען זייער אַ שאַרפער<sup data-n=\"746\">12</sup>, ער איז געווען אַ מחמיר. ר' הלל<sup data-n=\"747\">13</sup> איז געווען אַ גרויסער מחמיר בהתגלות. ר' אייזיל איז ניט געווען אַזוי פיל מחמיר בגילוי, אָבער געווען אַ מחמיר. ופעם כשהי' איזה חשש ספק על איזה דבר אמר ר' אייזיל: מען וועט דאָך אַמאָל דאַרפן אָפּגעבן אויף אַלץ אַ דין וחשבון, איז פשוט דאַמאָלסט אַ שאָד די צייט צו פאַרבריינגען אויף פאַרענט­פערן זיך אַז מען האָט דאָס געמעגט, יענע צייט קאָן מען אויסניצען אויף בעסערע זאַכן — צו הערען ענינים נעלים.\nד. איינע פון די ערשטע ווערטער­תורה פון אַלטן רבי'ן: \"ועשית חג שבועות\"<sup data-n=\"748\">14</sup> — \"שבועות\" איז וואָכן; \"חג שבועות\" — מאַכען די וואָכן פאַר אַ חג, אַז די וואָכעדיגקייט זאָל ווערן יו\"ט. דורך וואָס איז דאָס? דורך דעם \"היום יום\"<sup data-n=\"749\">15</sup>; אַז דער יום איז אַ יום שלם, דאַן איז \"ועשית חג שבועות\" — אַז די וואָכעדיגקייט ווערט חג.\nה. קומענדיק פון מעזריטש, האָט מען דעם אַלטען רבי'ן געפרעגט: וואָס האָסטו דאָרט געהערט. האָט ער געזאָגט<sup data-n=\"735\">1</sup>, אין מעזריטש האָט ער מקבל געווען, אַז אין מתן תורה איז געווען צוויי זאַכן: נעמען און געבען; מתן תורה און קבלת התורה. מתן תורה מיינט אַוועקגעבען \"זיך\" פאַר תורה, דעמאָלט ווערט מען אַ כלי צו קענען זיין אַ מקבל התורה אין אַ פנימיות; דורך וואָס קען מען זיך אַוועקגעבן צו תורה, דאָס איז דורך די דרכי התורה.\nדער שווער<sup data-n=\"751\">16</sup> האָט אַמאָל געזאָגט וועגן טאַטן<sup data-n=\"752\">17</sup>: איך האָב געזען גרויסע מענטשן, דעם טאַטן — מהרי\"נ נ\"ע<sup data-n=\"753\">18</sup> — די פעטערס, אָבער אַזאַ מסירת נפש; זיין — הכוונה על אאמו\"ר — ערשטער טראָט אין עבודה איז מיט מסירת נפש, ביי זיי איז אויך געווען מס\"נ, אָבער איך האָב דאָס ניט אזויפיל דערהערט ווי ביי דעם טאַטן. איך רייד ניט וועגן זיין גרויסקייט אין השכלה, הבנה והשגה; נאָר זיין מס\"נ אויף אידישקייט.\nאַה! ווי דאָס פעלט יעצט, דער מתן תורה, אַוועקגעבען זיך פאַר תורה; מען איז חסידים, מען לערנט, מען דאַוונט, מען האָט מדות חסידיות — עס איז טאַקע מער ניט ווי אַ דוכט, עס דוכט זיך אַז מ'האָט מדות חסידיות, אָבער מען איז חלילה ניט אָפּגעפרעגט פון דעם — אָבער דער אַוועקגעבן זיך צו תורה צו חסידות, אָט דאָס פעלט אינגאַנצן.\nאויף אַלץ איז דאָ צייט: מען לערנט, מען שמועסט אין לערנען, מען רעדט אַ ליצנות'ל, אַ רכילות'ל, אַ לשה\"ר, אַ הייליגע לשה\"ר, מען לאַכט אָפּ פון אַ גס הרוח; אָבער אַריינצונעמען זיך אַליין אין דעם אבן הבוחן — אין דעם פּרוביר­שטיין, אויף דעם איז קיין צייט ניטאָ.\nביי זיך אַליין ווייס מען אַז אַזוי ווי ס'איז טויג ניט, נאָר מען איז יוצא מיט אַ גלייכווערטל — אַ גלייכווערטל אַהער,",[["745","11","ראה אודותו לעיל ע' 25. וש\"נ."],["746","12","ראה גם ספר השיחות תש\"ג ע' 82."],["747","13","ראה אודותו לעיל ע' 29. וש\"נ."],["748","14","פ' ראה טז, י."],["749","15","שבספירת העומר."],["735","1","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."],["751","16","הרה\"ק וכו' ר' אברהם שניאורסאהן מקישינוב. ראה אודותו לעיל ע' 82."],["752","17","כ\"ק אדמו\"ר מהורש\"ב."],["753","18","בן אדמו\"ר הצ\"צ. — ראה אודותו: בית רבי חלק ג פרק ח (יד, ב [קכב, ב] ואילך). ספר השיחות תר\"פ­תרפ\"ז ע' 255 וש\"נ. תרפ\"ח­תרצ\"א ע' 239. מאמרי אדמו\"ר האמצעי הנחות תקע\"ז — הוספות ע' תנ."]]],[4301620319,"אַ גלייכווערטל אַהין, און דערמיט איז מען יוצא.\nעס איז אַ גרויסע רחמנות אויף אונז, עס איז אַ רחמנות אויפן נאָמען חסיד. מען האָט שוין אַמאָל געזאָגט אַז מען האָט אַראָפּגעפירט דעם חסידישען וואָגן אין אַ זייטיגן פעראולאק.\nאין די אַלטע מחזורים ביי \"על חטא\" אָדער \"סלח לנו\"<sup data-n=\"754\">19</sup> פלעגט שטיין: \"כאן בוכין\".\nו. איך האָב געהערט פון טאַטען בשם אדמו\"ר הזקן:\nמען קען זיך גאָרניט משער זיין דעם עונג למעלה פון די שמחה וואָס אידען זיינען זיך משמח בקבלת התורה; דער אויבערשטער זאָגט צו די מלאכים: איר קענט דאָס? איר זייט דאָך בבחי' מדות, איר זייט ניט שייך צו הבנה והשגה צו האָבן אַ חוש אין אַזאַ שמחה פון קבלת התורה.\nז. דער אַלטער רבי האָט געזאָגט, אַז חסידות האָט אויפגעטאָן האָבן אַ חוש אין אַ ענין. דאָס איז בכללות; בפרטיות מיינט דאָס, האָבן אַ חוש אין אלקות, אַז וויפיל מען פאַרשטייט ווייס מען נאָך גאָרניט, און האָבן אַ חוש אין אהבת ישראל.\nמען דאַרף דערהערן דעם פחיתות עצמו און דעם מעלת הזולת. הגם די וועלט זאָגט, מען ווייסט ניט יענעמס ווייטאָגן, אָבער עס דאַרף זיין אוקי על חזקתו, אַז יענער איז גוט; אָבער וועגען זיך אַליין ווייס מען דאָך דעם אמת.\nח. מען קען יעצט אין דעם ניט רעדן בארוכה, נאָר איך וויל זאָגן אַ וואָרט ווי דער טאַטע האָט מיר אַמאָל געזאָגט גייענדיק שפּאַצירן<sup data-n=\"755\">20</sup>:\nדי גאַנצע השכלה פון חסידות איז אַז דער וואָרט זאָל זיך דערהערן אין עבודה. האָט ער געזאָגט: עד\"מ, אַז מען לערנט דעם רמב\"ם, דעם יד החזקה, מיט אַלע סברות און מפרשים, וואָס דאָס אַלץ איז בכדי עס זאָל שפּעטער אַראָפּקומען אין אַ הלכה, אין אַ סעיף אין קיצור שו\"ע, למען ידעו את המעשה אשר יעשון.\nאַמאָל אַז מען האָט געהערט אַ וואָרט האָט דאָס חוקק געווען אין אַ פנימיות, אַז מען האָט געלעבט מיט דעם.\nט. צוה לנגן את הניגון של ד' בבות של אדמו\"ר הזקן ואמר: מען וועט זינגען דעם אַלטן רבין'ס ניגון, און יעדער זאָל זיך מכין זיין לפי כחותיו.\nי. אין די צייטן פון אַלטן רבי'ן איז אַמאָל געווען אַ שווערער זמן — אַ עת צרה ל\"ע — האָט דער אַלטער רבי געזאָגט:\nדער אויבערשטער איז דאָך געוויס צופרידן פון עם ישראל, יתן השי\"ת אַז די אידן זאָלן זיין צופרידן פון אויבער­שטן. דער אויבערשטער זאָל געבן די אידן געשמאַקע גשמיות, לעבעדיגע גשמיות; אַז די אידען זאַלען מאַכען פון די גשמיות רוחניות<sup data-n=\"756\">21</sup>.\nאיי! ווי מען דאַרף דאָס יעצט האָבן, דברי הרב חיים וקיימים לנצח.",[["754","19","בהנחה אחרת: אדער אַ \"סליחה\"."],["755","20","ראה גם שיחת אחש\"פ שנה זו. ליל ב' דחה\"פ תש\"ח (לעיל ע' 121. לקמן ע' 204)."],["756","21","ראה סה\"מ ה'ש\"ת ע' עח. סה\"מ אידיש ס\"ע 52. אגרות­-קודש ח\"ב ע' רסה (הועתק ב\"היום יום\" כז טבת). חי\"א ע' לד. חי\"ד ע' כד. ע' עט."]]],[4301620320,"דער אויבערשטער זאָל געבען אידען געשמאַקע גשמיות ווי ער קען, ניט נאָר ווי ער וויל — דאָס איז דאָך אַ ודאי — נאָר ווי ער קען, אַז די אידן זאָל זיין געשמאַק אין גשמיות, וועט דעמאָלט דער אויבערשטער האָבן הנאה פון זייערע רוחניות.\nהשמטה: אמר: מ'טרייסט זיך מיט חלשות טראָפּן."],[4301620321,"<h3>י\"ב תמוז תש\"ז<sup data-n=\"757\">1</sup></h3>\n(אחד מהמסובים אמר לכ\"ק אדמו\"ר שליט\"א: לחיים. איהר האָט אָנגעפאָנגען די גאולה, זאָל דער אויבערשטער העלפען, אַז איהר זאָלט משלים זיין די אמת'ע גאולה מיט משיח'ן אינאיינעם. ואמר כ\"ק אדמו\"ר שליט\"א):\nדי גאולה האָט זיך אָנגעהויבען פון דעם זיידען אברהם'ן<sup data-n=\"758\">2</sup>, ווען ער איז נאָך געווען אַ אברם און געלעבט מיט זיין פאָטער תרח אין חרן.\nעס איז שוין וועגען דעם אייניגע מאָל ערקלערט געוואָרען, אויף די יסודות וואָס איך האָב זוכה געווען הערען פון הוד כ\"ק אאמו\"ר הרה\"ק, וואָס ער האָט מקבל געווען פון הוד כ\"ק אביו אאזמו\"ר הרה\"ק מוהר\"ש, וואָס איז געוואָרען איבערגעגעבען מרבי לרבי לדורותיהם: די השגחה עליונה האָט בוחר געווען אין אברם'ען ווען ער איז נאָך געווען אין חרן און האָט איהם געמאַכט פאַר אַ אברהם. אברם איז — אב­רם<sup data-n=\"759\">3</sup>, שכל הנעלם מכל רעיון און אברהם איז — אבר מ\"ה, און כדי צו מאַכען אַז פון שכל הנעלם מכל רעיון זאָל ווערען אַ אבר מ\"ה, אַ ברא מ\"ה<sup data-n=\"760\">4</sup>, בעדאַרף מען האָבען די ריכטיגע מסירת נפש עבודה.\nאיבערמאַכען פון אַ מהות עצמי, וואָס איז נעלם מכל רעיון, אַז ער זאָל דורך עבודה ווערען אַ מהות מ\"ה, וואָס כל מהותו איז ביטול, האָבען אַ געשמאַק אין פרסום אלקות און לייגען מסירות נפש כחות אויף צו מאַכען די פאַר­גרעבטע פלאכעס (גולמי עץ) פאַר מאמיני האחדות, איז אַ פיין שטיקעל אַרבעט.\nאַלע אידען גלויבען אין דער גאולה בכח, דאָס הייסט, אַז עס איז ביכולתו",[["757","1","נדפס בלקו\"ד ח\"ג תצ, א ואילך.\nמועתק בזה לשון ה\"פתח דבר\" שם (תפט, ב):\nאין דער פאָרליגענדער חוברת זיינען געדרוקט די \"שיחות\" פון יב תמוז ה'תש\"ז, לויט די פאַרצייכענונגען פון די הערער, וועלכע זיינען דערנאָך דורכגעזען געוואָרען פון כ\"ק מו\"ח אדמו\"ר שליט\"א.\nזעלבסטפערשטענדליך, ווערען געדרוקט נאר עצם הענינים תוכניים וכללים, אָבער ניט די פערבינדונגס­שמועסען און דבורים לפרטים, און דערפאַר זעען אויס מאנכע סעיפים אָן אַ קישור צווישען זיך.\nווי אין די אַנדערע אויסגאַבען פון \"אוצר החסידים\" זיינען אויך דאָ צוגעגעבען געוואָ­רען אייניגע מראי מקומות און באַמערקונגען מהמו\"ל.\nמנחם שניאורסאהן\nיג אלול ה'תש\"ז, ברוקלין נ. י."],["758","2","[ראה גם ספר השיחות תורת שלום ע' 16]."],["759","3","אברם איז אב רם: זע וועגען דעם בארוכה אין לקוטי תורה לג' פרשיות (תורת שמואל שער א) פרשת לך לך [אוה\"ת לך לך ח\"ו תתערב, א ואילך]."],["760","4","אברהם איז אבר מ\"ה. . ברא מ\"ה: זע זוהר חלק א דף ג ע\"ב."]]],[4301620322,"ית' צו בריינגען די גאולה. מיר ווילען אַז ס'זאל זיין בפועל ממש. ניט נאָר בכח, נאָר בפועל.\nחסידישע מחונכים ווייסען, וואָס עס איז דער תוכן ענין פון דער ברכה פנימית, אַז דער בפועל זאָל זיין ווי דער בכח איז און דער בכח זאָל באַלעבען דעם בפועל, וואָס דאַן וועט דער בפועל זיין די כלי טהור, וואָס עס וועט מגלה זיין עצמות אין סוף ב\"ה און וועט גורם זיין דעם אמת'ן נחת רוח אין בריאת העוה\"ז און ירידת הנשמה בגוף.\nב. מען האָט מעהרערע מאָל אין דעם גערעדט און אָפטער איבערגע­זאָגט, אַז חסידים לדורותיהם, פון חניכי ותלמידי הוד כ\"ק מורנו הבעש\"ט, דעם מעזריטשער מגיד און רבינו הזקן, האָבען איבערגעזאָגט עניני עבודה אין קורצען, וואָס יעדער וואָרט איז געווען אַ הוראה אין דרכי עבודה.\nצווישען די אַלטע חסידישע ווערטער איז געווען אַ וואָרט:\nאַ איד איז ניט קיין עלענדער, וואו ער געהט און וואו ער שטעהט איז ה' עמו.\nדער וואָרט איז רבי מפי רבי ביז דעם בעש\"ט נ\"ע. דער אַלטער רבי האָט דעם וואָרט געמאַכט אַ יסוד פאַר אַ ביאור, אויף דעם וואָס אין די זמנים<sup data-n=\"761\">5</sup> פון בעש\"ט און מעזריטשער מגיד איז געווען די אידישע הויפּט­פרנסה דאָרפס­געהעריי, און אויף דעם האָט מען געזאָגט, אַז יעדער איד איז ניט עלענד, וואו ער געהט און וואו ער שטעהט איז ה' עמו, דאָס הייסט די התגלות פון שם הוי'.\nדער וואָרט איז איינער פון די ווערטער וואָס הוד כ\"ק אאזמו\"ר הרה\"ק צ\"צ האָט מקבל געווען פון די זקני חסידי הוד כ\"ק רבינו הזקן, וועלכע האָבען דאָס געהערט פון הוד כ\"ק רבינו הזקן קומענדיג פון מורו הוד כ\"ק הרב המגיד ממעזריטש.\nווען הוד כ\"ק אאמו\"ר הרה\"ק האָט מיר איבערגעגעבען דעם יסוד וואָרט האָט ער באריכות גדולה מבאר געווען, אַז דער עיקר איז די התגלות שם הוי' דורך דעם שם אלקים.\nאַ אַנדער מאָל, ווען הוד כ\"ק אאמו\"ר הרה\"ק רעדט און איז מבאר דעם ענין פון דער כוונה פנימית אין מעלת השיתוף דהוי' ואלקים האָט מען מדגיש געווען, אַז כלי מאַכט אור<sup data-n=\"762\">6</sup> פאַר אַ פועל טוב. ד.ה. אַז כלי טראָגט אַרויס די פנימיות הפנימי, אַז ער זאָל לייכטען אין אַ אור מסודר, וואָס דאַן איז דער פנימיות המאור מאיר אין אור.\nאין איינע פון מיינע רשימות איז פאַרצייכענט, וואָס הוד כ\"ק אאמו\"ר הרה\"ק האָט מבאר געווען, אַז ירידת הנשמה בגוף איז צוליב געבען אַ ריכטיגען ביאור אויף דער כוונה פנימית פון מתן תורה למטה און קיום המצות מעשיות, און האָט מסביר געווען מיט אַ טיפען עבודה­השכלה ביאור דעם ענין ווי יש הנברא גיט דעם העכסטען הבנה ביאור אין יש האמיתי.\nג. עס איז אַ מצוה לפרסם, אַז אַלע",[["761","5","אין די זמנים: זע וועגען דעם: ספר הזכרונות קאַפּיטל ט, קונטרס ח\"י אלול ה'תש\"ג פון ע' 19 [ספר השיחות תש\"ג ע' 152] אן און נאך."],["762","6","אַז כלי מאַכט אור: הוי' און אלקים זיינען אור און כלי, ווי עס ווערט ערקלערט אין חסידות<sup data-n=\"e23\">*</sup>."],["e23","*","[ראה תו\"א יתרו סט, ד. לקו\"ת בלק עג, ב. המשך תרס\"ו ע' תעו ואילך. ועוד]."]]],[4301620323,"זאָלען וויסען, אַז די מעלה פון אַ איש פשוט איז אין להעריך.\nדעם ענין האָט מגלה געווען מורנו הבעש\"ט אין עטלעכע קורצע ווערטער:\n\"די פשיטות העצמות פון עצמות א\"ס ב\"ה איז זיך מתגלה אין די פשיטות פון אַ איש פשוט\"<sup data-n=\"763\">7</sup>.\nהוד כ\"ק רבינו הזקן וואָס האָט מקבל געווען תורת הבעש\"ט מהוד כ\"ק מורנו הרב המגיד ממעזריטש, האָט עס מבאר און מסביר געווען, אַז בעלי תורה און בעלי עבודה, איז דאָך דאָס הגבלה, גילויים און ניט עצמות. תורה און מצות זיינען עצמות, אָבער ניט פשיטות העצ­מות. די מעלה פון עצמות איז דאָך פשיטות.\nפשיטות העצמות, וואָס דאָס איז גאָר אַ אַנדער זאַך, אויף דעם איז געווען תכלית ירידת הנשמה בגוף און תכלית בריאת העולמות: אצילות, בריאה, יצירה, עשי' ביז עוה\"ז הגשמי, צוליב עולה זיין צו פשיטות העצמות, וואָס איז אַ סאַך העכער פון עולם האצילות.\nאצילות נעמט נאָר אַ געוויסע מעק­לעריי, אָבער די פשיטות העצמות פון עצמות א\"ס ב\"ה איז פאַראַן אין די פשיטות פון אַ איש פשוט.\nד. (ניגנו בהתרגשות הניגון המיוסד לכבוד חג הגאולה י\"ב תמוז, אשר בתנו­עות הניגון נרגש תוקף עוז תעצומות של מסירת נפש. ואמר כ\"ק אדמו\"ר שליט\"א):\nאַמאָל פלעגט מען זאָגען, אַז אַ חסידישען ניגון דאַרף מען זינגען מיט געפיהלעכט'ס. ניט נאָר מיט געפיל, נאָר מיט געפיהלעכט'ס. (וצוה כ\"ק אדמו\"ר שליט\"א לשיר הניגון עוד הפעם).\nה. אין אַמעריקא איז פאַראַן אַ יחוס­אויסשפּראַך: אין דער אַלטער היים. דאָס מיינט צו באַצייכענען, אַז דער געבורטס­אָרט וואו דער טאַטע און זיידע איז געבאָרען, אָדער וואו ער אַליין איז געבאָרען — איז, אין דער אַלטער היים. אין דער אַלטער היים זיינען חסידישע יונגעלייט און בחורים געווען בעלי קבלה. איך מיין ניט געלערענט קבלה, נאָר זיי זיינען געווען בעלי קבלה, ד.ה. זיי האָבען מקבל געווען פון די עלטערע חסידים.\nבאַ אַ חסידישען פאַרבריינגען פלעגט מען זיך ווינשען, מען זאָל האָבען אַזאַ געשמאַק אין אַ מאמר חסידות ווי אין אַ תנועה פון אַ חסידישען ניגון, וואָס איז נוקב ויורד און נעמט דורך.\nהוד כ\"ק אאמו\"ר הרה\"ק האָט גע­זאָגט, אַז מורי הרשב\"ץ איז אַ פנימי, ער לעבט מיט אַ וואָרט. יעדער ענין ווי טיף ער זאָל ניט זיין, מאַכט צו איהם צו החסיד רשב\"ץ אַ וואָרט, וואָס דער וואָרט איז כולל דעם אור פנימי ועצמי פון דעם ענין, און מיט דעם וואָרט לעבט ער אין עבודת התפלה, מיט דעם וואָרט לייגט ער זיך שלאָפען, מיט דעם וואָרט שלאָפט ער איין און מיט דעם וואָרט שטייט ער אויף. באַ רשב\"ץ'ן איז געווען אַ מורגל — געוואוינהייט­וואָרט: דער ענין איז נוקב ויורד עד התהום, אַ חיות עצמי וואָס איז העכער פון חיות המתפשט.\nו. החסיד רשב\"ץ<sup data-n=\"764\">8</sup> איז געווען אַ",[["763","7","[ראה לעיל ע' 3. וש\"נ]."],["764","8","החסיד רשב\"ץ: בפרטיות וועגען עם זע: קובץ \"התמים\" חוברת א ע' סז און ווייטער. ס' השיחות קיץ ה'ש\"ת ע' 91 [וראה גם לעיל ע' 12. וש\"נ."]]],[4301620324,"מחונך פון החסיד הנודע ר' מיכעל'ע אַפּאָצקער<sup data-n=\"765\">9</sup>.\nאין מיינע זכרונות (פון יאָהר תרנ\"ד­נ\"ו) איז פאַרצייכענט סיפורי מורי הרשב\"ץ וועגען תולדתו וחינוכו. אין זיינע קינדער יאָהרען איז מורי רשב\"ץ געבליבען אַ יתום פון זיין פאָטער, אַ מתנגד'ישער גרויסער למדן און גרויסער מחדש אין תורה, איינער פון די וויכטיגסטע ראשי ישיבות אין זיין צייט.\nזיין מוטער, אַ מיוחסת פון איהר פאָטער'ס צד פון די ווילנער מתנגד'ישע גדולי היחוס, און בזיווג שני האָט זי געהייראַט איינעם פון די בעלי יחס בעדת המתנגדים. גליקליכערווייזע איז ער — רשב\"ץ — נושא חן באַ איינעם פון עדת החסידים אין שווינצאַן — עיירה בפלך ווילנא — און ווערט אָנגענומען אין דער שווינצאַנער עדת החסידים.\nדי עדת החסידים אין שווינצאַן האָט זיך שטאַרק פאַראינטרעסירט מיט זיין חינוך און מען האָט איהם פאַרזאָרגט מיט אַלעס וואָס ער האָט נויטיג געהאַט, אום ער זאָל קענען במנוחה זיך איבער­געבען צו שקידה אין לימוד הגמרא ופוסקים און אין לימוד החסידות. אין אַ צייט אַרום האָבען די זקני חסידי חב\"ד אין שווינצאַן ובראשם ר' יצחק חייט<sup data-n=\"766\">10</sup> מחליט געווען, אַז מען זאָל איהם — רשב\"ץ — אָפּשיקען לערנען צו החסיד הישיש ר' מיכל אַפּאָצקער, אַ גרויסער מתמיד און אַ זעלטענער עמקן.\nווען רשב\"ץ איז אָנגעקומען אין אַפּאָצק איז החסיד ר' מיכל שוין געווען אַ זקן מופלג. רשב\"ץ האָט נושא חן געווען באַ איהם און ער האָט איהם שטאַרק מקרב געווען און זיך אָפּגעגעבען מיט זיין חינוך בדרכי החסידות.\nאיינמאָל האָט הרמ\"א געזאָגט צו זיין תלמיד ותיק רשב\"ץ, מיט אַ שטאַרקער אינערלעכע פאַרביטערקייט:\nהער, שמואל בצלאל, דו ווייסט ניט, דו ביסט נאָך יונג צו פאַרשטעהן און ווער רעדט פיהלען דיין רחמנות און דעם גרויסען טעות וואָס דו מאַכסט, מיינענדיג, אַז מיר זקנים זיינען חסידים. מיר האָבען געזעהן חסידים און מיר ווייסען דעם ביטערען אמת. מיר זיינען דאָך גאָרניט, דאָרניצעס — עצים יבשים. אַמאָליגע חסידים האָבען געהאַט אַ געפיהל.\nווען מורי הרשב\"ץ האָט דערציילט דעם סיפור באַ אַ פאַרבריינגען, האָבען די חסידים ר' חנוך הענדיל<sup data-n=\"767\">11</sup>, ר' אבא צאַשניקער<sup data-n=\"768\">12</sup> און ר' שמואל ברוך<sup data-n=\"769\">13</sup> — געזאָגט: ואנן מה נעני אבתרי', מיר האָבען גאָר ניט קיין נעמען, ווי מיר זאָלען זיך אָנרופען.\nענטפערט זיי רשב\"ץ, מיט זיין געלאַסענער און רוהיגער שפת חלקות: איר ווייסט געוויס אויך ווי מען בעדאַרף",[["765","9","ראה אודותו — \"התמים\" חוברת א ע' עד [לח, ב] ואילך. ספר השיחות תש\"א ע' 96 ואילך. לעיל ע' 29. \"רשימות\" סיון­מנ\"א תרצ\"ב (חוב' קכב ע' 8). ש\"ק קדושים ר\"ח אייר תרצ\"ה (חוב' קמג ע' 7)]."],["766","10","ר' יצחק חייט: זע וועגען עם: קובץ \"התמים\" חוברת ח פון ע' צב."],["767","11","ר' חנוך הענדיל: זע וועגען עם: \"התמים\" חוברת א ע' עט. ס' השיחות קיץ ה'ש\"ת ע' 43, 85 א. א [וראה גם לעיל ע' 17."],["768","12","ראה אודותו לעיל ע' 89."],["769","13","ראה אודותו לעיל ע' 109. וש\"נ]."]]],[4301620325,"זיי — די יונגע לייט — אָנרופען, נאָר איהר ווילט ניט זאָגען. איך וועל יע זאָגען. איך מיין זיך אויך, נאָר מעהר מיין איך זיי, זיי זיינען פוליאַקעס און ווילען גרינג געבאַקענע ברויט. זיי — די יונגע לייט — ווייסען גאָר ניט, וואָס עס מיינט יגיעת המוח.\nז. רשב\"ץ פלעגט זאָגען: ביי אשמנו דאַרף מען קלאַפּען אויף דער לינקער זייט ניט מיט דער האַנד, נאָר מיט אַ דאָרניצע — עץ יבש. אַז מען קלאַפּט מיט דער האַנט, מיינט ער — היצה\"ר — אַז מען גיט איהם אַ גלעט.\nח. (אחד מהמסובים האָט אָנגעוויזען אויף אַ יונגענמאַן און געזאָגט, אַז ער פאָרט אַוועק. ואמר כ\"ק אדמו\"ר שליט\"א):\nמורנו הבעש\"ט האָט אַליין, און אויך דורך זיינע תלמידים און תלמידי תלמידים רבותינו הקדושים איינגע­קריצט אין בני ובנות ישראל, אַז אַ איד פאָרט ניט אַוועק. אַ איד פאָרט, און יעדער איד איז אַ שליח פון עצמות, פון פשיטות עצמות א\"ס ב\"ה.\nדי וואָס לערנען חסידות מיט אַ רגש פנימי האָבען אַ געפיהל אין דעם.\nרגש פנימי, האָט הוד כ\"ק אאמו\"ר הרה\"ק מבאר געווען — בעת איינער פון די שפּאַציר­גענג מיט מיר — אין צוויי ענינים: א) דער חסידות פאַרשטאַנד אין עצמות, אַז עס איז אַ אור עצמי וואָס לאָזט זיך מלביש זיין אין השגה. ב) פשיטות העצמות דא\"ס ב\"ה, וואָס עס איז העכער פון תפיסא און השגה, וואָס אויף דעם זאָגט אליהו<sup data-n=\"770\">14</sup>, לית מחשבה תפיסא בך כלל.\nבעת איינעם פון די טיולים האָט הוד כ\"ק אאמו\"ר הרה\"ק מבאר געווען מיט געוויסע הסברים, אַז יעדער איד, וואו ער געפינט זיך דאַרף ער וויסען די כוונה העליונה פון זיין קומען אין יענעם אָרט, אויף אַ קורצער אָדער אַ ליינגע­רער צייט, אָדער אַמאָל מער ניט ווי אַלס דורכגעהער, ווייל אין יענעם אָרט האָט ער געדאַרפט מאַכען אַ ברכה אָדער דאַוונען<sup data-n=\"771\">15</sup>. און מששת ימי ברא­שית וואַרט דער אָרט אויף זיין דאַוונען אָדער ברכה<sup data-n=\"772\">16</sup>. און ער דאַרף דורכ­פיהרען די שליחות, ווייל ער איז אַ שליח פון פשיטות העצמות. ער דאַרף עס ניט פאַרשלאָפען און ניט פאַר­שפּילען זיך אין איינעם פון די שפּיצלעך פון יצר הרע.\nמען דאַרף אַלעמאָל געדיינקען, די ווילדע פאַרעטערישע התחכמות שטיק­לעך פון דעם יצר הרע, אַז ער פאַר­מעסט זיך אַלעמאָל און ביי יעדע גע­לעגענהייט דורכצופיהרען זיינע שקר'­דיגע שטיק, ביז ער האָט געהאַט די חוצפא וועלען פאַרפיהרען אברהם'ן און יצחק'ן מיט זיינע שפּיצלעך.\nט. (אחד מהמסובים אמר לחיים, ואמר כ\"ק אדמו\"ר שליט\"א):\nאין מיינע קינדער יאָהרען האָב איך געהערט ווי זקני החסידים ר' אבא און ר' חנוך הענדעל פלעגען זאָגען \"לחיים עם כל הפירושים\".\nהוד כ\"ק אאמו\"ר הרה\"ק האָט דאַן געזאָגט: אַזוי איז דער נוסח ברכת לחיים וואָס חסידים זאָגען, אָבער הוד כ\"ק אאמו\"ר — אאזמו\"ר מהר\"ש —",[["770","14","[תקו\"ז בהקדמה (יז, א)."],["771","15","ראה גם רשימה ש\"פ נצבים שנה זו (לקמן ע' 151 ואילך)."],["772","16","ראה רשימת היומן של רבינו מיום ה' כז מנ\"א תרנ\"ו (לקו\"ד ח\"ד תקצו, ב)]."]]],[4301620326,"פלעגט זאָגען \"לחיים\" דאָס איז חיים עצמיים, וואָס איז העכער פון כל הפירושים. דער חילוק אין די צוויי נוסחאות — איז מובן צו די וואָס זיינען בעלי עבודה אין תפלה מיט אַ הכנה טובה אין דעם קודם התפלה.\nאַלע אידען זאַלען זיין געזונד מיט זייערע בני בית און עס זאָל זיי זיין פרעהליך אויפ'ן האַרצען.\nאָבער וואָס עס מיינט אמת'ע שמחה — ווייסען חסידים, און זיי האָבען דעם אמת'ן עבודה שכל אויסנוצען די שמחה אויף ממשיך זיין דעם חיות פנימי פון שכל אויך אין תהלים זאגער און מאַרק און דאָרפ'ס­הענדלער.\nיוד. מיר איז זעהר טייער יעדער וואָרט וואָס איך האָב זוכה געווען צו הערען מהוד כ\"ק אאמו\"ר הרה\"ק. עס זיינען פאַראַן פערשידענע ענינים וואָס ער האָט מיר מיט זיי מזכה געווען, אַז איך זאָל דאָס איבערגעבען צו אנ\"ש און תלמידי תומכי תמימים, אַז די ענינים זאָלען פאַר זיי זיין אַ וועג ווייזער אין דרכי עבודה און דרכי הנהגה אין דרכי החסידות.\nדי זכרונות באַ אַ חסידישען מחונך, איז לבד זאת וואָס זיי זיינען איבערפילט מיט דעם פנימיות'דיגען חסידות רייכטום, בריינגען זיי אויך דעם רייכען עבר אין אַ ליכטיגען געשמאַקען הווה.\nאַמאָל ווען איך האָב נאָך געלערענט באַ מורי החסיד ר' ניסן<sup data-n=\"773\">17</sup>, האָט הוד כ\"ק אאמו\"ר הרה\"ק, בעת אַ דאָנערשטאָג באַ דער נאַכט'יקען חסידות לערנען אין קליינעם מנין­זאַל, אַ פולע גערעדט און שטאַרק געוויינט.\nוואָס הוד כ\"ק אאמו\"ר הרה\"ק האָט גערעדט האָב איך ניט פאַרשטאַנען, נאָר די עטלעכע ווערטער \"דער גרויסער רחמנות וואָס איז אויף דער נשמה\", וואָס איך האָב געהערט פון איהם און זיין אינערליכער געוויין האָבען מיר אַזוי דורכגענומען, אַז זיצענדיג אויף אַ באַנק נעבען טיר פון חדר שני, האָב איך זיך פאַנאַנדערגעוויינט.\nאויף צומאָרגענס, פרייטאָג, האָב איך געדאַווענט, — לויט מיין דאַמאָלסדיגען מצב — מיט גרויס התעוררות און געזאָגט תהלים. דער שפּילען זיך יענעם פרייטאָג איז באַ מיר געווען אהן דעם געוויינליכען געשמאַק און קאָך.\nבעת סעודת שבת נאַכט האָט הוד כ\"ק אאמו\"ר הרה\"ק ווידער גערעדט מיט די מסובים החסידים ר' הענדיל און ר' אבא צאשניקער, אָבער איך האָב גאָרניט פאַרשטאַנען. החסיד רח\"ה זאָגט מיר: דו הערסט וואָס דער טאַטע זאָגט? אַז איך האָב געזאָגט, אַז איך הער, אָבער איך פאַרשטעה ניט, ענטפערט מיר הרח\"ה: מען בעדאַרף הערען און געדענקען וואָס מען האָט געהערט און אַז דו וועסט עלטער ווערען, וועסטו יעמאָלט פאַרשטעהן וואָס דו הערסט איצטער.\nהרח\"ה דערצעהלט פון אַלטע חסידים, וועלכע האָבען געזאָגט, אַז אין די עלטערע יאָהרען האָבען זיי ערשט דאַמאָלסט געפיהלט דעם הבנה און העמקה פאַרשטאַנד פון דעם וואָס זיי האָבן געהערט אין זייערע קינדער יאָהרען.\nיא. איך בין — דערציילט הרח\"ה — אַ ישוב'ניק, אויפגעוואָקסען און געלעבט אַ פולע יאָהרען צווישען דאָרפס און קרעטשמע­אידען. זעהר ווייניג פון זיי",[["773","17","ר' ניסן: זע ס' השיחות קיץ ה'ש\"ת ע' 29 [וראה גם לעיל ע' 41. וש\"נ]."]]],[4301620327,"זיינען געווען למדנים. מעהרסטענטייל זיינען זיי געווען פשוט'ע אידען, אָבער חסידות זאַפטיגע אידען.\nאין אונזער געגענד — זאָגט הרח\"ה — האָבען זיך אַלע פשוט'ע אידען געהאָ­דעוועט באַ חסידישע טאַטעס און מאַמעס און באַ חסידישע מלמדים, און די פשוט'ע אידען האָבן פאַרשטאַנען און געפיהלט דעם געשמאַק פון דעם חסידישען חינוך לויט זייער געפיל און פאַרשטאַנד מיט ערקלערונגען און הסברים פון זייער געוויינטליכען אַרבעטס לעבען.\nדי דאָרפס אידען פלעגען זאָגען: עס זיינען פאַראַן צוויי מינים אין היי: געזייטער היי — קליעווער — און גראָז­היי, וועלכער וואַקסט פון זיך אַליין און מען בעדאַרף עס ניט זייען.\nביידע מינים היי וואַקסען פון דער ערד, ביידע סאָרטען היי זיינען אַ מאכל בהמה, אָבער דער אונטערשייד פון די קאָרמע (מזון) וואָס די בהמה עסט איז ניכר אין דער מאָס און אין די פעטקייט פון די מילך וואָס די בהמה גיט.\nדי חסידישע מחונכים, פּראָסטע אידען, קרעטשמער, דאָרפס לייט, בעלי מלאכות און מאַרק הענדלער בריינגען אַריין אַ געוויסען געשמאַק אין דעם טעם רוחני פון עם ישראל.\nיב. הוד כ\"ק אאמו\"ר הרה\"ק האָט מיט מיר געלערענט צוויי מאָל דעם פירוש המלות<sup data-n=\"774\">18</sup> פון תפלות דחול, שבת ויו\"ט, הגדה ש\"פ<sup data-n=\"775\">19</sup> ולקוטי תפלות דר\"ה ויוכ\"פ. דעם ערשטען מאָל אין די קינדער יאָהרען און דעם צווייטען מאָל פון מיין בר מצוה — י\"ב תמוז תרנ\"ג — אָן.\nווען הוד כ\"ק אאמו\"ר הרה\"ק האָט מיט מיר אָנגעהויבען לערנען דעם ערשטען מאָל דעם פירוש המלות האָט ער דאַן געזאָגט: דאַוונען און ניט וויסען וואָס מען דאַווענט איז דאָך ניט קיין זאַך. און האָט מיט מיר געלערענט אַ יסודות'דיגע פאַרטייצונג פון דאַוונען.\nדעם צווייטען מאָל האָט הוד כ\"ק אאמו\"ר הרה\"ק מיט מיר געלערענט דעם חסידישען פירוש המלות, איך מיין ניט דעם געדרוקטען און די געשריבענע פירוש המלות — בדרושי חב\"ד — נאָר אַ חסידישען פירוש המלות. פון מודה אני, יעדער פסוק פאַרטייצט על דרך החסידות מיט אַ בפועל בכן. באַ יעדען ענין פלעגט הוד כ\"ק אאמו\"ר דער­צעהלען סיפורים, פון וועלכע דער רוב זיינען געווען תורות, וואָס הוד כ\"ק רבינו הזקן האָט מקבל געווען פון מורנו הבעש\"ט און מורנו המגיד ממעזריטש און אַמאָל אויך מיט די ביאורים פון הוד כ\"ק רבינו הזקן און הוד כ\"ק אבותינו רבותינו הקדושים.\nאין יאָהר תרנ\"ה נאָך חג השבועות זיינען מיינע עלטערען אַרויסגעפאָרען אין דאַטשע באָליווקע<sup data-n=\"776\">20</sup>, האָבען מיר שוין דאַן ב\"ה געהאַלטען באַ דעם לימוד פירוש המלות פון לשם יחוד וואָס מען זאָגט פאַר ברוך שאמר.\nאַזאַ מלמד און אַזאַ אופן לימוד ווערט נחקק אין קאָפּ און עס לייכט אין האַרצען מיט אַ לעבעדיגען אריכות ימים'דיגען זכרון.\nיג. איך וויל מאַכען זיך און אייך אַ",[["774","18","[ראה שיחת יום שמח\"ת תש\"ט. ה'שי\"ת (לקמן ע' 286. ע' 378)."],["775","19","ראה גם שיחת אחש\"פ שנה זו (לעיל ע' 122)."],["776","20","ראה שיחת יום ש\"ק חול המועד סוכות שנה זו (לעיל ע' 70). וש\"נ]."]]],[4301620328,"פנימיות רוחניות'דיגען עונג און איבער­געבען, וואָס הוד כ\"ק אאמו\"ר הרה\"ק האָט דאַן מבאר געווען אין דעם קאַ­פּיטעל למנצח בנגינות, וואָס מען זאָגט פאַר ברוך שאמר.\nאָבער צוליב דעם איך זאָל אייך קענען איבערגעבען דעם ענין מוז מען האָבען אַ געוויסע הכשרה הקדמה אין דעם כללות ענין פון דעם סולם דתפלה.\nאון פריהער מוז מען ערקלערען בקצרה לכל הפחות וואָס איז דער מיין אין דעם סולם, וואָס מלמעלה<sup data-n=\"777\">21</sup> האָט מען באַוויזען יעקב אבינו אין חלום<sup data-n=\"778\">22</sup>.\nחסידות חב\"ד פאַרלאַנגט, אַ חכמה עמוקה אין השגת אלקות און ווי יעדער חכמה עמוקה איז פריהער בעדאַרף מען גלויבען וואָס מען לערענט, און נאָכדעם פאַרשטייט מען מיט אַ געוויסען חסי­דישען אָפּלייג.\nיד. דעם סולם האָט יעקב אבינו געזען, ווען ער איז, נאָך די ברכות וואָס — זיין און אונזער פאָטער — יצחק אבינו האָט איהם געבענטשט, אַנטלאָפען פון דעם האַרץ­כעס פון זיין ברודער עשו, פאַר דעם וואָס יעקב אבינו האָט, אויף דעם פאַרלאַנג פון זיין מוטער רבקה אמנו, צוגענומען די ברכות וואָס יצחק האָט געדיינקט צו בענטשען מיט זיי זיין זוהן עשו.\nאין חסידות<sup data-n=\"779\">23</sup> ווערט ערקלערט דער ענין פון די ברכות וואָס יצחק אבינו האָט געהאַט בדעה צו בענטשען זיין זוהן עשו און דורך רבקה'ס עצה און אַרבעט זיינען די ברכות אָנגעקומען יעקב'ן — אַז אברהם אבינו איז די מדריגה פון ספירת החסד דעולם האצילות, יצחק אבינו איז די מדריגה פון גבורה דאצילות און יעקב אבינו איז מדריגת תפארת דאצילות.\nדי מדריגות פון עולם התהו זיינען העכער ווי די מדריגות האור פון עולם התיקון. אין אַ כלליות'דיגען<sup data-n=\"780\">24</sup> אונטער­שייד שטריך צווישען די אורות פון די צוויי עולמות תהו ותיקון: אין עולם התהו איז אורות מרובים און כלים מועטים און אין עולם התיקון איז כלים מרובים און אורות מועטים<sup data-n=\"781\">25</sup>.\nדער טיפער אונטערשייד איז אַז די אורות דתהו זיינען ענפין מתפרדין. די אַלע עשר ספירות איז יעדע ספירה אַ אור תקיף און האָט ניט קיין שייכות צו די אַנדער ספירה, און ספירות דתיקון זיינען אורות מועטים און כלים מרובים און יעדע ספירה איז נותן מקום צו די אַנדער ספירה, אויך אפילו צו די ספירה הפכית: חסד דאצי' גיט אַ אָרט צו גבורה דאצילות און תפארת דאצילות איז מייחד חסד און גבורה.\nטו. דער ישוב'ניק ר' דובער פון נעבען חאלאפעניץ<sup data-n=\"782\">26</sup>, דער פאָטער פון ר'",[["777","21","וואָס מלמעלה: זע זוהר ח\"א רסו, ב; ח\"ג שו, ב."],["778","22","ויצא כח, יב."],["779","23","אין חסידות: זע די מאמרים ויתן לך אין תורה אור, תורת חיים, אור התורה, ספר המאמרים (ה'ש\"ת­תש\"ב. איצט אין דרוק)."],["780","24","אין אַ כלליות'דיגען: זע תורה אור ביאור צום מאמר מים רבים, תורת חיים מאמר בראשית (השני), דרך מצותיך מאמר לרוקע תקס\"ב און נאך."],["781","25","[ראה עץ חיים שער י (שער התיקון) פ\"ה. מאמרי אדה\"ז תקס\"ח ח\"א ע' א ואילך. מקומות שבהערה הקודמת. ובכ\"מ."],["782","26","נזכר ברשימת היומן של רבינו מיום א', כ' אייר תרנ\"ו (לקמן ע' 424). ספר השיחות תש\"ד ע' 83 ואילך. שיחת ליל א' דחג השבועות תש\"ח (לקמן ע' 235)."]]],[4301620329,"מענדל דער משרת<sup data-n=\"783\">27</sup> איז געווען אַ פשוט'ער אַמאָליגער \"עמך\" איד, וואָס האָט גאָר ווייניק פאַרשטאַנען אין די שוואַרצע פּינטעלעך. ער איז געווען אַ תיקון חצות — תהלים איד. אַלע נאַכט פלעגט ער אָפּריכטען חצות און אָפּזאָ­גען דעם גאַנצען תהלים און במשך היום פון דער אַרבעט, פיהרענדיג זיינע מיל­כיגס אין שטעטעל חאלאפעניץ צו פאַר­קויפען צו די בעלי בתים און אויפקויפען פאַרשידענע זאַכען אין שטאָט פאַר זיין קרעטשים קרעמעל, פלעגט ער זאָגען תהלים.\nר' דובער איז געווען אַ חב\"ד חסי­דישער מחונך. זיין פאָטער איז געווען אַ חסיד, וועלכער איז געגאַנגען צו הוד כ\"ק אדמו\"ר האמצעי, און צו זיין בר מצוה האָט איהם זיין פאָטער געפיהרט צו הוד כ\"ק אאזמו\"ר הרה\"ק צמח צדק ער זאָל איהם בענטשען.\nר' דובער פלעגט אָפט איבער דער­ציילען דעם סדר ווי זיין פאָטער איז געגאַנגען מיט אַ חבריא חסידים צו הוד כ\"ק אאזמו\"ר הרה\"ק צמח צדק, און פלעגט באריכות דערצעהלען ווי עס איז געווען דער סדר ההילוך ווען דער פאָטער האָט איהם דעם ערשטען מאָל גענומען אויף מיטצוגעהן אין ליובא­וויטש.\nר' דובער האָט דערציילט די עט­ליכע ווערטער וואָס הוד כ\"ק אאזמו\"ר הרה\"ק צמח צדק האָט איהם געזאָגט, ווען זיין פאָטער האָט איהם געבראַכט: אַ איד דאַרף זיין אַ בעל קבלת עול'ניק. זאָלסט אַלע טאָג זאָגען דעם גאַנצען תהלים, אויך געהענדיג אין שטאָט און פון שטאָט זאָגען תהלים.\nפאַר מיין חתונה — דערציילט ר' דובער — אַז איך בין געווען אין ליובאַ­וויטש, איז הוד כ\"ק אדמו\"ר הרה\"ק צמח צדק געווען שוואַך אין געזונד. מיר האָט מען אַריינגעלאָזען נאָר צוליב זכות אבות, און הוד כ\"ק אדמו\"ר הרה\"ק האָט מיר געזאָגט \"געדענק זאָגען תהלים בכל עת\".\nווען איך האָב דערציילט להוד כ\"ק אאמו\"ר הרה\"ק דעם סיפור, וואָס איך האָב געהערט פון ר' דובער, האָט הוד כ\"ק אאמו\"ר הרה\"ק געזאָגט, אַז אויף אַזעלכע פשוט'ע אידען תהלים זאָגער און לא ידעי מה קאמרי'ניקעס איז באמת קאים עלמא, און זייער תהלים זאָגען איז גורם דעם גרעסטען עונג אין עצמות א\"ס, אַז שבת צו מנחה, וואָס איז דער זמן פון רעוא דכל רעוין<sup data-n=\"784\">28</sup> זאָגט מען, ומי כעמך כישראל גוי אחד בארץ<sup data-n=\"785\">29</sup>, אַז עמך ישראל זיינען ממשיך אחד האמיתי אין ארץ<sup data-n=\"786\">30</sup>.\nטז. אין אייניגע שפּאַציר­גאַנגען האָט דעמאָלט — זומער תרנ\"ה — הוד כ\"ק אאמו\"ר הרה\"ק גערעדט<sup data-n=\"787\">31</sup> בארוכה דעם ענין",[["783","27","ר' מנחם מענדל קאנטאר. — נזכר ברשימת היומן של רבינו — לקמן ע' 424. יום א', י\"ט מ\"ח תרנ\"ד (\"התמים\" חוברת ג ע' כז [קל, א]). יום ה', כ\"ה תשרי תרנ\"ח (שם חוברת ה ע' לז [רלא, א]). יום ג', כח סיון תרס\"ג (\"מבוא\" לקונטרס ומעין ע' 54). קונטרס בר מצוה תרנ\"ג ע' יח. אגרות­-קודש ח\"ג ע' צט. ספר השיחות תש\"ב ע' 91. תש\"ד ע' 142. לקמן ע' 235. ע' 398. ועוד."],["784","28","זוהר ח\"ב פח, סע\"ב. ח\"ג קכט, א."],["785","29","שמואל­ב ז, כג."],["786","30","ראה תו\"א וישב כז, סע\"ד. וראה אגה\"ק ס\"ט (קיד, א)."],["787","31","ראה ד\"ה ויחלום תש\"ח (סה\"מ תש\"ח ע' 80) שהוא ד\"ה להבין ההפרש בין ברכות ק\"ש לק\"ש מקיץ תרנ\"ה (סה\"מ תרנ\"ה ע' רכב) — \"אשר זכיתי לשמוע ביחידות מאת כ\"ק אאמו\"ר הרה\"ק זצוקללה\"ה נבג\"מ זי\"ע בקיץ תרנ\"ה, בנאות­דשא באליווקא הסמוכה לתחנת מסה\"ב קראסנאיע, המבאר ענין ארבע שליבות דסולם התפלה, והמעלה ומטה דסולם שראשו בשמים ועמידתו בארץ, להעלות את הדברים התחתונים ולעשותם כלים לאלקות כו'\" — אגרות­-קודש ח\"ט ע' של]."]]],[4301620330,"פון סולם דתפלה, זאָגענדיג אַז דאָס איז דער סולם המחבר מעלה און מטה. דער סולם איז דער עמוד המחבר שמים וארץ.\nארץ איז גשמיות, ניט חומריות, חומריות איז די גראָבע גשמיות פון עולם העשי', וואָס שבירתו און זריקתו לחוץ דאָס איז תקנתו. שמים איז עולם האצילות. דער וואָרט שמים איז אַ צוזאַמענשטעל פון צוויי ווערטער שא מים<sup data-n=\"788\">32</sup>, טעון מים, דאָס מיינט אַז מים איז אַ תואר­נאָמען אויף טוהר עצמי, קלאָר ריין, אַ העכסט קלאָרע ריינקייט.\nאין גשמיות זעהען מיר, אַז אַ סולם פאַראייניגט דעם תחתון מיט דעם עליון, און ווי עס שטעהט סולם מוצב ארצה וראשו מגיע השמימה.\nדער סולם פון תפלה, וואָס איז עומד בארץ און ראשו מגיע אין שמים, איז די כוונה אין דעם ענין החיבור אויף צו מעלה זיין די ארציים זאַכען אין שמים און אויף מוריד זיין די שמים זאַכען אין ארץ.\nדער סולם פון תפלה וואָס ער איז עומד ארצה און ראשו מגיע השמימה האָט ארבע שליבות<sup data-n=\"789\">33</sup> און איז מכוון נגד די ד' עולמות אצילות, בריאה, יצירה און עשי'<sup data-n=\"790\">34</sup> וואָס זיינען מחבר דעם עולם הגשמי מיט עצמות אין סוף ב\"ה, און דורך די שליבות ווערט נמשך אור ושפע פון עצמות א\"ס ב\"ה אין אַלע עולמות.\nיז. די ד' שליבות פון תפלה איז דער אָנהויב פון דער ערשטער טרעפּ איז הודו לה' קראו בשמו<sup data-n=\"791\">35</sup> און דער סיום איז דער מזמור<sup data-n=\"792\">36</sup> למנצח בנגינות, און זי איז מכוון נגד עולם עשי'.\nדער הפסק צווישען עולם העשי' און עולם היצירה איז דער מאמר לשם יחוד.\nדי צווייטע טרעפּ, וואָס איז מכוון נגד עולם היצירה, איז די התחלה ברוך שאמר והי' העולם און דער סיום איז ברכת ישתבח כו' חי העולמים. אין עולם היצירה ווערט דערהערט דער אור אלקי וואָס איז מחי' עולמות און נבראים, און ווי אַלע נבראים זיינען, יעדער לפי מהותו, מכיר דעם חיות אלקי וואָס איז זיי מחי'.\nדער הפסק וואָס איז פון עולם היצירה צו עולם הבריאה, דער אָנהויב הפסק איז יתגדל ויתקדש שמי' רבא און דער סוף פון דעם הפסק איז ברכו און ברוך כו' ועד.\nדי התחלה פון עולם הבריאה איז ברוך כו' יוצר אור כו' את הכל און דער סיום איז ברכת גאל ישראל.\nדער הפסק צווישען עולם הבריאה און עולם אצילות איז דער פסוק<sup data-n=\"793\">37</sup> אדני שפתי תפתח ופי יגיד תהלתך, הגם דאָס איז אַ פסוק וואָס איז מגביל און מגדיר די גדלות פון עולם הבריאה און עולם האצי'. דער הפסק וואָס איז צווישען עולם הבריאה און עולם האצילות איז",[["788","32","שא מים: בראשית רבה פ\"ד, ז."],["789","33","האָט ארבע שליבות: זע אויך קונטרס העבודה, תורת שלום ספר השיחות ע' 66 [בהוצאת תשי\"ז ואילך: ע' 61] א. א."],["790","34","[ראה גם לקו\"ת בשלח ב, ב ואילך. ובכ\"מ."],["791","35","דברי הימים­א טז, ח."],["792","36","תהלים סז."],["793","37","תהלים נא, יז]."]]],[4301620331,"ניט בדומה צו דעם מאמר ההפסק וואָס איז צווישען עשי' און יצירה און דעם הפסק פון יצירה צו בריאה, אָבער דאָך איז דאָס אַ מאמר וואָס באַווייזט אויף דעם הפסק המדריגות.\nווי עס איז מבואר אין חסידות<sup data-n=\"794\">38</sup>, איז יעדער מאמר און מדריגה וואָס איז מפ­סיק צווישען צוויי בחינות און מדריגות, אַליין כלול פון צוויי מדריגות: איין מדריגה פון מפסיק איז שייך צו דער מדריגה התחתונה און די צווייטע מדרי­גה פון מפסיק איז שייך צו די מדריגה העליונה.\nאין דעם הפסק צווישען עולם הברי­אה און עולם האצילות וואָס איז כלול פון צוויי מדריגות, זיינען די ווערטער, אדני שפתי תפתח, דער טייל וואָס איז מורה אויף עולם הבריאה. און די ווערטער ופי יגיד תהלתך איז דער טייל וואָס איז מורה אויף עולם האצילות.\nשמונה עשרה איז דער עולם האצי­לות.\nנאָך תפלת שמונה עשרה איז מרומז און מבואר דער אור הנמשך אין עולם בעבודת היום כל אחד לפי מהות עבודתו.\nפון מודה אני ביז ויכריע ביניהם איז דאָס דער שטח הארץ וואָס אויף איהם שטעהט דער סולם פון תפלה, כמאמר הכתוב והנה סולם מוצב ארצה וראשו מגיע השמימה.\nיח. בקצרה, דער ענין ווי תפלה איז איינגעטיילט אין מדריגות פון סולם:\nדי ערשטע טרעפּ פון דעם סולם התפלה איז פון הודו ביז אפסי ארץ. די מדריגה המפסקת, די עובי פון דער שליבה, איז דער מאמר לשם יחוד. די צווייטע טרעפּ איז ברוך שאמר ביז חי העולמים. יתגדל און ברכו זיינען די צוויי זייטען פון דער צווייטער שליבה. פון ברוך כו' ובורא חשך ביז גאל ישראל איז די דריטע טרעפּ. אדני שפתי תפתח ופי יגיד תהלתך איז דער מעלה ומטה פון די דריטער שליבה. שמו\"ע איז די פערטע טרעפּ.\nדי פיר טרעפּ פון דעם סולם דיעקב אין עבודת התפלה איז די ערשטע טרעפּ פון הודו ביז כל אפסי ארץ מכוון נגד עולם עשי'. ברוך שאמר ביז חי העולמים איז די שליבה שני', וואָס איז מכוון נגד עולם היצירה. די התחלה איז ווי דער עולם היצירה, וואָס ער איז שוין אַ עולם הנראה למציאות דבר לעצמו, וואָס דער כח היוצר איז נעלם ונסתר, אָבער דאָך איז דער אור אלקי מאיר בגילוי. דאָס מיינט, אַז די בריאה, דער יש ממש איז מורה אויף דעם חיות, ניט ווי עשי', וואָס איז מעלים ומסתיר לגמרי אויף דעם חיות.\nדער סוף פון עולם היצירה איז ברכת ישתבח, וואָס דער סיום פון ברכת ישתבח איז חי העולמים, דער חיות פון עולמות, עס איז טאַקע עולמות במציאות, אָבער די מציאות פון עולם היצירה איז ניט מעלים אויף דעם אור וחיות אלקי המהווה, און בכל אופן ניט אַזאַ הסתר ווי דער יש פון עולם עשי'.\nיט. אין אדם איז דער כח המעשה אַ כח נבדל, וואָס איז מכוון נגד עולם העשי'<sup data-n=\"795\">39</sup>. דער עולם היצירה, וואָס איז מכוון נגד כח הדיבור, איז הגם דיבור איז מיוחד מיט דעם מדבר, אָבער עם זה",[["794","38","אין חסידות: לדוגמא: זע מאמר עוטה אור ה'ש\"ת."],["795","39","[ראה לקו\"ת ר\"פ בלק."]]],[4301620332,"איז ער אַ מציאות דבר וואָס איז נשמע צו אַ זולת. עס איז ניט גלייך ווי דער כח המחשבה, וואָס דער זולת ווייס מער ניט אַז ער איז פאַרטראַכט, אָבער וואָס ער טראַכט ווייס מען ניט.\nאָבער נאָך אַלעם זיינען מחשבה דיבור ומעשה מער ניט ווי לבושי הנפש<sup data-n=\"796\">40</sup>, אָבער עולם אצילות איז עולם היחוד, וואָס אין משל אין אדם איז דאָס דער כח המשכיל להשכיל ולגלות שכליים עצמים.\nכ. די גאַנצע אריכות וואָס דאָ איז אַרומגערעדט געוואָרען איז אַ קיצור'­דיגע שמועס, וואָס באמת האָט מען געדאַרפט ריידען באריכות און מדגיש זיין דעם גרויסען היזק רוחני, וואָס די חסידישע בחורים און יונגעלייט האָבען, מצד דעם העדר שימת לב אויף עניני העדר העבודה, טאָן מיט זיך בכלל, און אויף העדר עבודת התפלה בפרט. חסידים בכלל און תמימים בפרט זאָלען עפענען זייערע אויערען און הערצער אויף הערען און דערהערען דעם קול חוצב בלהבת אש קדש פון הוד כ\"ק אאמו\"ר הרה\"ק — זי\"ע — אין קונטרס עץ החיים<sup data-n=\"797\">41</sup> — קיץ רס\"ד — בכלל און ביחוד די פרקים ל\"ב ל\"ג מיט דעם סיום התפלה והברכה, ובכחו וכחם של כ\"ק אבותינו רבותינו הקדושים נצליח בעבודתינו כהוראת תורת החסידות אמן, כן יהי רצון.\nכא. צוליב אַ זכרון פנימי, וועל איך איבערגעבען אַ ענין פנימי, וואָס הוד כ\"ק אאמו\"ר הרה\"ק האָט מיט מיר גערעדט בעת איינעם פון די שפּאַציר­גאַנגען.\nנאָכדעם ווי ער האָט מיט מיר גערעדט ענינים שונים, האָט הוד כ\"ק אאמו\"ר הרה\"ק גערעדט אַ ענין פנימי אין חסידות, וואָס איך קען און וויל אייך איבערגעבען, מיט דער האָפנונג, אַז איהר וועט דעם ענין פאַרשטעהן און דערפיהלען אין עבודה בפועל.\nצוליב אַ סבה פנימית, ווי עס איז פאַרצייכענט אין מיין יומן, איז הוד כ\"ק אאמו\"ר הרה\"ק דאַן געווען שטאַרק פנימיות'דיג אויפגעלייגט און האָט בארוכה מבאר געווען דעם ענין פון די שמות הוי' ואלקים, אַז שם הוי' איז גילוי און רחמים און שם אלקים איז העלם און דין. און דאַן געזאָגט אין זעהר אַ אויפגע­לייגטען טאָן: אלקים יחננו ויברכנו, יאר פניו אתנו סלה. דאָ איז עפּעס ניט גלאַ­טיק, מען בעדאַרף דאָס זיך געבען גוט צו פאַרשטעהן, מיט אַ טיף פנימיות ברייטען און פרייען הסבר: ווי קומט צו שם אלקים, מדת הצמצום וההעלם, תחנונים און ברכות. שם אלקים איז דאָך מדת הדין והצמצום, היינט וואָס איז שייך צו בעטען אַ ברכה און רחמים באַ שם אלקים.\nאלקים יחננו ויברכנו יאר פניו אתנו סלה, רעכענט ער דאָ מעלות אין שם אלקים: א) יחננו, נתינת חן. ב) ויברכנו, ער זאָל אונז בענטשען. ג) הארת פנים פון דעם שם אלקים. ד) אתנו סלה צו אונז און מיט אונז אַלעמאָל.\nאָבער באמת, ווי תורת החסידות ערקלערט איז, אַז אַ ברכה דאַרף טאַקי קומען פון שם אלקים, וואָרום עס איז דאָך בראשית ברא אלקים, אַז די התהוות בפועל פון יש הגשמי איז דורך דעם שם אלקים, וואָס דורך די עבודה ובירור וזיכוך אין שם אלקים ווערט מען אַ כלי מקבל זיין דעם זהב הטהור<sup data-n=\"798\">42</sup>.",[["796","40","תניא רפ\"ד]."],["797","41","קונטרס עץ החיים: געדרוקט אין ברוקלין ה'תש\"ו."],["798","42","זהב הטהור: זע לקוטי תורה דברים דעם מאמר ה' לי בעוזרי פ\"ה (להעיר ג\"כ מפרדס ש\"י פ\"ג. קהלת יעקב מע' זהב. מאורי אור אות זיי\"ן סקי\"א)."]]],[4301620333,"די עשירות פון דעם וואָרט איז פאַראַן אין השכלה. אָבער דאָס ליגט דאָך ליידער אונטערן טיש און קיינער איז זיך ניט עוסק אין דעם.\nאז מען נעמט אַראָפּ די בלאָטע, נאָכ­דעם ברענט מען דאָס, נאָכדעם גיסט מען דאָס און מען מאַכט אַ בירור, מען נעמט אַרויס דעם פסולת פון טוב און דעם טוב פון פסולת, דאַמאָלט איז זיך מתגלה דער זהב טהור, די פיינגאָלד, און דאָס איז, יאר פניו אתנו סלה, אַז מען דערזעהט דעם אמת ליכטיגען פנים.\nכב. בנוגע השכלה פון חסידות האָט מען אַמאָל געזאָגט אַ משל פון אַ קישקע. פריהער איז דאָס פּאַסקוד­סטווע, אָבער אַז מען רייניגט אויס די קישקע און מען פילט עס אָן מיט מעהל און שמאַלץ, דאַן ווערט דאָס אַ מאכל טוב.\nכג. מען האָט שוין אַמאָל אין דעם גערעדט, אַז ביי יעדע חסידישע שמחה זיינען פאַראַן געזונטע שעהנע אורחים: דער בעש\"ט, דער מעזריטשער מגיד און די רביים.\nמיר פאַרשטעהען ניט בכלל די מעלה פון אַ נשמה. היינט ווען זי איז למעלה און איז זיך עוסק אין השגה אלקית אין גן עדן התחתון און ג\"ע העליון, פאַר­שטעהט מען דאָך געוויס ניט.\nמען דאַרף האָבען אַ חוש צו פאַר­שטעהן דעם חילוק פון ג\"ע התחתון ביז דעם ג\"ע העליון, און אַ חוש צו דער­הערען דעם עונג אלקי פון אַ נשמה למעלה.\nדאָס רעדט זיך וועגען נשמות בכלל, בפרט נשמות הצדיקים און בפרטי פרטיות נשמות הכלליות.\nעס איז גאָרניט צו באַגרייפען מיטן שכל אנושי ווי אַזוי די נשמות הצדיקים הכלליות קענען זיך אָפּרייסען פון זייער עונג אלקי. זייער מסירות נפש דאָס אָפּצולאָזען און קומען זיך משתתף זיין אין דער שמחה פון חסידים נשמות אין גופים, וועלכע האָבען אַ נפש הבהמית און אַ יצה\"ר, און דערצו נאָך מקנא זיין, וואָס די נשמות אין גופים זיינען זיך עוסק אין אַ ענין רוחני.\nמען בעדאַרף האָבען אַ געפיהל אין דעם. חסידים האָבען דעם געפיהל, נאָר ס'איז פאַרפּילעט און פאַרשטויבט. אָבער אַז מען גיט אַ ריב ווערט דאָס נתגלה. און דער ריב, דאָס ווערט דורך התבוננות פאַרן דאַוונען און די התבוננות אין דאַוונען.\nכד. אַז מען<sup data-n=\"799\">43</sup> זינגט דעם רבי'נס ניגון — הניגון של ד' בבות — איז דאָס מעורר למעלה די התגלות הנשמה פון רבי'ן, ווי מיר האָבען זוכה געווען הערען מהוד כ\"ק אאמו\"ר הרה\"ק, אַז ווען הוד כ\"ק אאזמו\"ר הצ\"צ האָט געזונגען אין אַ מסבת חסידים דעם רבי'נס ניגון, האָט זיך יעדערער פון די חסידים המסובים אַרומגעקוקט אויב דער רבי שטעהט באַ זיין זייט.\n(כ\"ק אדמו\"ר שליט\"א ציוה לנגן את הניגון של ד' בבות מאדמו\"ר הזקן והי' בדבקות עצומה בעת הניגון. אח\"כ ציוה",[["799","43","אַז מען: זע אויך שיחת כ' כסלו תרצ\"ד אות ה' [לקו\"ד ח\"א קב, ב]. שיחת ער\"ח תמוז ה'תש\"ב ע' 12 [ספר השיחות ה'תש\"ב ע' 138. וראה גם שיחת כ' כסלו תרצ\"ב. ספר השיחות תרפ\"ח­תרצ\"א ס\"ע 11 ואילך. וש\"נ]."]]],[4301620334,"כ\"ק אדמו\"ר שליט\"א לנגן את הניגון של שמחה \"ניע זשוריטצי חלאָפצי\"<sup data-n=\"800\">44</sup>).\nכה. בכלל בעדאַרף זיך שוין איצט אָנהויבען די הכנה צו חודש אלול. מען בעדאַרף זיך אָנהויבען מושטירען.\nדער אויבערשטער זאָל געבען אַ גע­זונטען זומער און אַ פרעהליכען תמיד.",[["800","44","ניע זשוריטצי: זע וועגן דעם ניגון: תורת שלום ספר השיחות ע' 155 [ובהוצאת תשי\"ז ואילך: ע' 157 ואילך. וראה גם סה\"ש תש\"א ע' 112]."]]],[4301620335,"<h3>אור ליום ו' ט\"ו מנחם אב תש\"ז</h3>\n(התלמיד ישראל יוסף זאַלמאַנאָוו שיחי' נכנס ליחידות לכ\"ק אדמו\"ר שליט\"א. ואמר הת' הנ\"ל לכ\"ק אדמו\"ר שליט\"א שביום הש\"ק הבע\"ל ימלאו לו שמונה שנים — כ\"י. ואמר כ\"ק אדמו\"ר שליט\"א:) אַכט יאָהר איז שוין אַ גרויסער איד. (ואמר אביו — הר\"ש זאַלמאַנאָוו — שלכבוד זה חזר בע\"פ פרק משניות. ושאל כ\"ק אדמו\"ר שליט\"א: אם לומד חומש עם פירש\"י, וענה התלמיד: כן. ושאל כ\"ק אדמו\"ר שליט\"א: אם הנהו לומד נ\"ך, וענה התלמיד: כן. ספר יהושע לא למד עדיין, ועתה לומד הנהו ספר שמואל. ושאל כ\"ק אדמו\"ר שליט\"א אם לומד קיצור שו\"ע, וענה: כן. וברכהו כ\"ק אדמו\"ר שליט\"א:)\nדער אויבערשטער זאָל העלפן זאָלסט זיין געזונט אין גשמיות און אין רוחניות און די עלטערן זאָלן האָבן פון דיר נחת.\n(כ\"ק אדמו\"ר שליט\"א ביקש מהר' שמואל זאַלמאַנאָוו לכתוב להרב גאָראָ­דעצקי למסור ולפרסם לאנ\"ש והתמימים הנמצאים בפּאַריז, הוראה כללית ע\"ד הנסיעה לארה\"ב<sup data-n=\"801\">1</sup>:)\nמען דאַרף זיך ניט איילען מיט'ן קומען אַהער. דאָ איז ניט לייכט זיך מסתדר צו זיין. אַמעריקא גלייכט ניט אַזעלכע. מען קאָן דאָ ווערען גיך אַ שיינער איד, מיט אַ סיווער באָרד<sup data-n=\"802\">2</sup>...\nאיך זאָג ניט, אַז זיי זאָלען ניט קומען אַהער, פאַרקערט, איך האָב אַ כוונה פנימית, אַז זיי זאָלען זיין דאָ, וועט זיין מיט וועמען אויפצוטאָן, אָבער מען דאַרף זיך ניט אַיילען. דאָס מיינט ניט אַז זיי דאַרפען דאָרטען זיצען בחיבוק ידים, נאָר מען בעדאַרף זיך צוגרייטען יעדער לפי ערכו ומצבו.\nמען בעדאַרף דערווייל לערנען אַליין און לערנען מיט אַנדערע. מען בעדאַרף זיך צוגרייטען צו מלאכת השו\"ב. שחיטת גסות איז אַ ודאי גוט, לכה\"פ שחיטת עופות. אויך מוהל'שאַפט, חזנות — דער וואָס איז מסוגל דערצו — מלמדות וכדומה. אָבער ניט איילען און ניט געכאַפט.\nוהשי\"ת יהי' בעזרם בגו\"ר.",[["801","1","מכאן ואילך הועתק ממכתב הר' שמואל זאַלמאַנאָוו להרב\"א גאָראָדעצקי מיום ג' י\"ט מנ\"א תש\"ז (נדפס בספר תולדות חב\"ד ברוסיא הסובייטית ע' תיד): \"בהיותי ביום ה' העבר בהיכל כ\"ק אדמו\"ר שליט\"א ביקש אותי לכתוב לכבו' למסור ולפרסם לאנ\"ש והתמימים הנמצאים בפאריז הוראה כללית לאנ\"ש והתמימים ע\"ד הנסיעה לאה\"ב\" [ההמשך בפנים. ומסיים שם:] \"בטח ימסור כבו' את האמור בזה — כמעט כלשונו הק' ממש — לידידינו אנ\"ש והתמימים בפּאַריז וגם בהמחנות\"."],["802","2","ראה גם שיחת יום ב' דחגה\"ש תש\"ו (לעיל ע' 48)."]]],[4301620336,"<h3>יום ג', ג' אלול תש\"ז<sup data-n=\"803\">1</sup></h3>\nעס איז געווען אַמאָל אַ שטאַרקער פאַרבריינגען נאָך מיין בר מצוה, אין די יאָרן תרנ\"ד או תרנ\"ה, יעמאָלט האָט זיך גערעט אַז תכלית העבודה איז אויסמושטירן זיך. אַ סאָלדאַט אַז ער אַרבעט זיך אַרויף און ער ווערט אַ גענעראַל, איז תכלית המעלה פון אַ גענעראַל איז אַז ער איז אַ סאָלדאַט, אַז ער פילט ניט די מעלת הכבוד והדומה, נאָר דער תכלית איז אַז ער איז יעמאָלט אַ סאָלדאַט.\nדער תכלית פון עבודה איז פועל, דער תכלית פון השכלה איז עבודה, און תכלית פון עבודה איז מעשה.\nגשמיות איז מרמז אויף עצמות. נאָך די הפלאה פון אצילות ולמעלה מאצילות — איז גשמיות מרמז אויף עצמות<sup data-n=\"804\">2</sup>. דערפאַר דאַרף מען מייקר זיין גשמיות. איז אָבער דוקא גשמיות און ניט קיין חומריות.\nוואָס דאָס איז אַזוי אין יעדער זאַך. אַ בעל עסק איז זיין תכלית פרנסה, דער תכלית פון פרנסה איז צוליב אַ ענין רוחני, ניט קיין חומריות, יעמאָלט איז די גשמיות רוחניות.\nהיינט איז דאָך אלול, גיט אָפּ אַ געריס צו אנ\"ש מיט אַ ברכה אַ כתיבה וחתימה טובה בגשמיות וברוחניות. די וואָס דאַרפן האָבן אַ רפואה זאָל זיי השי\"ת העלפן מיט אַ רפו\"ש, און אַ התעוררות פנימי.\nאיר פאָרט דאָך — פאָרט געזונט, און זייט געזונט און קומט געזונט.",[["803","1","קודם נסיעת הרה\"ח ר' שמואל לויטין והרה\"ח ר' אליהו (ייאכיל) סימפּסאָן — הרש\"ל והרא\"ס — לטשיקאַגאָ — בכניסתם לקבל ברכת הפרידה. — מרשימת הרה\"ח ר' אליהו (ייאכיל) סימפּסאָן. ראה אודותו לעיל ע' 51."],["804","2","ראה אגה\"ק ס\"כ (קל, ב). ביאורי הזהר לאדמו\"ר האמצעי בשלח מג, ג. סה\"מ עזר\"ת ע' קנ. ספר השיחות תורת שלום ע' 120 ואילך. ועוד."]]],[4301620337,"<h3>ועש\"ק י\"ג אלול תש\"ז</h3>\nכשעה שתים וחצי אחרי הצהרים נכנסו לחדר כ\"ק אדמו\"ר שליט\"א זקני אנ\"ש והתמימים הקשישים, לברך ולהתברך ליום היובל שנים של חגיגת הנשואין של כ\"ק אדמו\"ר שליט\"א.\nכ\"ק אדמו\"ר שליט\"א פנה אליהם בפנים צהובות ואמר: איהר ווילט דאָך עפּעס זאָגן.\nהרב משה דובער ריבקין<sup data-n=\"805\">1</sup> מקשישי התמימים פתח ואמר:\nהיינט איז דאָך פרייטאָג י\"ג אלול, וואָס עס איז די זעלבע קביעות ווי אין יאָר תרנ\"ז, ב\"ה אַ פולער יובל יאָרן זינט דעם רבי'נס חתונה למזל טוב.\nמיר אַלס עדה אידן צוזאַמען מיט די כהנים וועלכע געפינען זיך דאָ, ווילן זאָגן דעם רבי'ן אַ ברכה, און ווינשן מזל טוב.\nדער אויבערשטער זאָל צושיקן דעם רבי'ן בקרוב ממש אַ רפואה שלימה צוזאַמען מיט די גאַנצע בני בית חיינו שליט\"א, מיט אריכות ימים ושנים טובים, אַ הצלחה מרובה אין אַלע",[["805","1","בעמח\"ס אשכבתא דרבי (ברוקלין, תשי\"ג). נולד כ\"א כסלו תרנ\"ג. נפטר י\"ח מר­חשון תשל\"ז."]]],[4301620338,"עבודות הקדש מתוך נחת והרחבה, און דער רבי זאָל פירן בקרוב ממש אַלע אידן לקבל פני משיח צדקנו בב\"א.\nכ\"ק אדמו\"ר שליט\"א עונה אמן על הברכות האמורות, והואיל לספר:\nווען דער אַלטער רבי איז געקומען פון מעזריטש האָבן די תלמידים מרגיש געווען באַ איהם אַ שינוי אין דער הנהגה:\nבשעת דער רבי איז געוועזען באַ זיין פאָטער הרב ר' ברוך, האָט ער געזעהן ווי מען איז מקרב אנשים פשוטים, און מען איז זיי מייקר.\nווען דער רבי איז געוואָרן אַ איידים אין וויטעבסק האָט ער זיך געפירט אין דער הנהגה. די גדולי התורה אין וויטעבסק, האָבן זיך אויף דעם געוואונדערט, אַזאַ גדול בתורה איז מקרב אנשים פשוטים, און גיט זיך אָפּ מיט זיי. אַ איש פשוט האָט מען אין יענער צייט גערופן מיטן נאָמען \"דרבן\".\nעס איז דורכגעגאַנגען עטליכע יאָר, און דער רבי איז געוואָרן עלטער, האָבן זיך צו אים צוגעקלעפט תלמידים, פערלדיגע תלמידים, און ער האָט אויף זיי משפיע געווען מתורתו. ער האָט זיך אויך אָפּגעגעבן מיט אנשים פשוטים, זיי מקרב געווען, אָבער ער האָט אַ סאַך געלערנט בינו לבין עצמו.\nדענסטמאָל האָט מען געהאַלטן אַז עס איז דאָ ג' מיני אהבה, אהבת השם אהבת התורה און אהבת ישראל. אהבת השם איז הן וואָס מען פאַרשטייט און הן דאָס וואָס מען פאַרשטייט ניט, אהבת התורה איז אפילו אויף דעם וואָס מען האָט נאָך ניט אויסגעשעפּט פון תורה, אהבת ישראל איז, האָלט האָבן אַ בן תורה<sup data-n=\"806\">2</sup>.\nווען דער אַלטער רבי איז צוריקגע­קומען פון מעזריטש, האָבן די תלמידים געזעהן אַ שינוי, הן אין די אמירת התורות, און הן אין דער הנהגה פון מייקר זיין אנשים פשוטים<sup data-n=\"807\">3</sup>.\nער האָט דאַן געזאָגט צו די תלמי­דים<sup data-n=\"808\">4</sup>: אהבת ישראל איז, אַז מען דאַרף האָלט האָבן אַלע אידן, אפילו אנשים פשוטים (און נישט ווי עס איז געווען דענסטמאָל די הנהגה אַז בני תורה זיינען געווען בדלים (אָפּגעזונדערט) פון אנשים פשוטים), און דאָס ברענגט צו אהבת התורה, און דענסטמאָל האָט מען אַ חוש אין אהבת השם<sup data-n=\"809\">5</sup>.\nבכללות איז די הנהגה פון אדמו\"ר הזקן געוועזן, אַז ער פלעגט זאָגן די תלמידים, אַז זיי זאָלן פרעגן, וואָס זיי האָבן צו פרעגן, דאַן איז געווען אַ זמן וואָס מען האָט געפרעגט, און מען האָט זיך ניט באַנוגענט מיט אמונה אַליין. האָבן די תלמידים געפרעגט: אהבת השם איז דאָך למעלה מהבנה והשגה, אהבת התורה איז דאָך קבוע בלב, און אהבת ישראל איז דאָך ניט אַלע גלייך, דעם דאַרפמען האָלט האָבן, און דעם אַנדערן בניחותא.\nוהשיב להם אדמו\"ר הזקן:\nאהבת ישראל, האָלט האָבן אַ אידן מיט אַ פנימיות, קומט מען צו דורך דעם צו אהבת התורה, אַז ניט נאָר דאָס [וואָס] עס איז באתגליא, נאָר אפילו דאָס וואָס",[["806","2","ראה ספר השיחות תש\"ה ס\"ע 117 ואילך."],["807","3","ראה גם שיחת ל\"ג בעומר שנה זו. י\"ט כסלו תש\"ח (לעיל ע' 123. לקמן ע' 181)."],["808","4","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."],["809","5","ראה גם ספר השיחות שם ע' 120. שיחת ג' דחול המועד פסח תש\"ח. י\"ט כסלו תש\"ט. רשימה מחורף ה'שי\"ת ס\"ב (לקמן ע' 213. ע' 291. ע' 347)."]]],[4301620339,"מען האָט ניט דערגראָבן, און דענסט­מאָל קומט מען צו, צו אהבת השם, אהבה עצמית, אהבתי אתכם אמר הוי'<sup data-n=\"810\">6</sup>, אַלעמען אָן חילוקים.\nדאָס איז איינער פון די סיפורים — אומר כ\"ק אדמו\"ר שליט\"א — וואָס דער טאַטע האָט דערציילט אין דעם זמן החתו­נה, בשבעת ימי המשתה, שהי' מספר אז בכל יום משבעת ימי המשתה איזה סיפור מהבעש\"ט, המגיד, פון דעם אַלטן רבי'ן, מהצ\"צ, ומאביו; און יעדען סיפור האָט ער — דער טאַטע — צוגעפירט צו אַ ענין און האָט דאָס מבאר געווען בארוכה.\nדער טאַטע האָט דענסטמאָל געזאָגט: מען זאָגט \"חסידות און מדות חסידות\"; לכאורה וואָס מיינט מען \"מדות חסי­דות\"<sup data-n=\"811\">7</sup>, חסידות איז דאָך השכלה והשגה, טא וואָס איז \"מדות חסידות\", נאָר מוחין איז צוליב עבודה בפועל — האָלט האָבן אַ איש פשוט.\nוסיים כ\"ק אדמו\"ר שליט\"א: דער אויבערשטער זאָל ממלא זיין די דבר הברכה אין אריכות ימים און בריאות הנכונה. דער אויבערשטער זאָל געבן מען זאָל האָבן נחת פון אידן ברוחניות ובגשמיות, אידן זאָל זיין באמת גוט, אין גשמיות און אין רוחניות, מען זאָל זוכה זיין צו דעם גילוי ביאת המשיח בקרוב ממש.",[["810","6","מלאכי א, ב."],["811","7","ראה גם שיחת ליל שש\"פ שנה זו (לעיל ע' 117)."]]],[4301620340,"<h3>בס\"ד, ש\"פ נצבים, תש\"ז</h3>\n<h4>רשימה<sup data-n=\"812\">1</sup></h4>\nאתם נצבים היום כולכם לפני הוי' אלקיכם ראשיכם שבטיכם זקניכם ושוטריכם כל איש ישראל טפכם נשיכם וגרך אשר בקרב מחניך מחוטב עציך עד שואב מימיך<sup data-n=\"813\">2</sup>. והנה<sup data-n=\"814\">3</sup> די פרשה לייענט מען אַלעמאָל פאַר ראש השנה<sup data-n=\"815\">4</sup> און היום איז מרמז אויף ר\"ה<sup data-n=\"816\">5</sup>, זה היום תחלת מעשיך זכרון ליום ראשון<sup data-n=\"817\">6</sup>, וואָס דאַמאָלס זיינען אַלע נשמות עולה לפני הוי' אלקיכם פון ראשיכם ביז שואב מימיך, און דוקא כולכם זיי זאָלען זיין לאחדים כאחד. איך האָב געהערט פון הוד כ\"ק אאמו\"ר הרה\"ק, וואָס ער האָט געהאַט בקבלה מרבי לרבי, אַז דער אַלטער רבי — רבינו הזקן — ווען ער איז געווען אין מעזריטש האָט אים רבו — המגיד ממעזריטש — מגלה געווען ווער ער איז<sup data-n=\"818\">7</sup>, אַז ער איז אַ נשמה חדשה דאצילות<sup data-n=\"819\">8</sup> בהתלבשות",[["812","1","נדפס בסה\"מ תש\"ז ע' 256 והוא האגרת מאלול תש\"ו \"אל ידידנו אנ\"ש ותלמידי התמימים היקרים\" [אגרות­-קודש ח\"ט ע' קסה ואילך] בתוס' התחלה וסיום ובהשמטת סיום האגרת."],["813","2","ר\"פ נצבים (כט, ט­י)."],["814","3","בכ\"ז — ראה לקו\"ת ר\"פ נצבים (מד, א ואילך)."],["815","4","תוס' מגילה לא, סע\"ב. רמב\"ם הל' תפלה פי\"ג ה\"ב. טושו\"ע או\"ח סתכ\"ח ס\"ד. לקו\"ת ר\"פ נצבים (מד, א)."],["816","5","פענח רזא ס\"פ נצבים. מגלה עמוקות נצבים ד\"ה עשירי (ס, ד). וראה זוהר ח\"ב לב, ב וברמ\"ז שם. ח\"ג רלא, א."],["817","6","תפלת מוסף דר\"ה (ר\"ה כז, א)."],["818","7","ראה גם לעיל ס\"ע 27. לקמן ע' 280. ע' 285."],["819","8","ראה שיחת ש\"פ וישב תש\"ו (לעיל ע' 22). וש\"נ."]]],[4301620341,"בגופו בגילוי<sup data-n=\"820\">9</sup>, און אַז עבודתו איז מגלה און מבאר צו זיין דעם דרך החסידות חב\"ד, און, לכל לראש — גיט איהם איבער מורו המגיד ממעזריטש בשם מורו הבעש\"ט — איז דער דרך העבודה אַז מען דאַרף מקרב זיין אויך אנשים פשוטים, ווייל מען דאַרף ליב האָבען אַ אידען ווייל ער איז אַ איד<sup data-n=\"821\">10</sup>, און יעדער איד איז ירידת נשמתו למטה בהתלבשות בגוף גשמי צוליב מאַכען דעם מטה הגשמי פאַר אַ כלי צו אלקות.\nאון ווען דער רבי — רבינו הזקן — איז צוריקגעקומען פון מעזריטש קיין וויטעבסק, וויסענדיג שוין ווער ער איז, אַז ער איז אַ נשמה חדשה און אַז באַ אים איז התגלות עצם הנשמה אין דער נשמה המאירה בגוף<sup data-n=\"822\">11</sup>, האָט ער דאַן געזאָגט אַ תורה ברבים<sup data-n=\"823\">12</sup>, נותנין עליו חומרי המקום שיצא משם וחומרי המקום שהלך לשם<sup data-n=\"824\">13</sup>. חומר איז ענינו ענין המציאות, איז בירידת הנשמה למטה נותנים עליו מלמעלה חומרי המקום שיצא משם וחומרי המקום שבא לשם.\nחומרי המקום איז דער פירוש<sup data-n=\"825\">14</sup>, דער חומר פון דעם מקום, דער חומר איז די כוונה פנימית פון דעם מקום שיצא משם און די כוונה פנימית פון דעם מקום שבא לשם. חומרי המקום שיצא משם מיינט, די כוונה אין ירידת הנשמה משרשה ומקורה אין יש האמיתי, און חומרי המקום שבא לשם מיינט דאָס וואָס די נשמה דאַרף אויפטאָן דורך עבודה אין תורה ומצות אין די ענינים הגשמיים פון דעם עולם שבא לשם, וואָס דורך עבודתו איז מען מעלה דעם חומר המקום, היינו שרש מציאות היש למקום שיצא משם די כוונה פנימית אין מציאות יש וואָס עס איז עולה אין עצמות אין סוף.\nווען אַ איד גייט ממקום למקום, זאָגט דער רבי, אַז אַ נשמה שבגוף גייט ממקום למקום, פון איין אָרט צום צווייטען, איז זיין הילוך בהשגחה פרטית ווי דער רצון העליון איז, נוסף עליהם די עניני האדם וואָס מען גיט דעם אדם דעם ענין הבחירה לבחור בטוב ולמאוס ברע.\nדי השגחה העליונה פירט די נשמה ממקום למקום, בכדי מברר צו זיין און מעלה צו זיין דעם מקום. אַ איד גייט ניט אַליין בבחירתו ממקום למקום, עצמות א\"ס ב\"ה פירט אַ אידען ממקום למקום, בכוונה מיוחדת צו פועל זיין דעם עליית ובירור המקום, דורך תורה ועבודה בקיום המצות.\nחומרי המקום שיצא משם וחומרי המקום שבא לשם, חומרי המקום שיצא משם, זאָגט הוד כ\"ק אאמו\"ר הרה\"ק, אין איינער פון זיינע שיחות הקדש בשנת תרנ\"ו, אַז דער כללות הענין פון ירידת הנשמה בגוף איז דאָס וואָס די הארת הנשמה בירידתה למטה בהתלב­שות בגוף איז צוליב אויספירען די כוונה עליונה דורך דעם הילוך ממקום למקום והתעסקות בתורה ומצות ועבו­דה שבלב, מיט דעם וואָס אַ איד גייט ממקום למקום, און אין איין אָרט דאַווענט ער און אין דעם צווייטען אָרט מאַכט ער אַ ברכה, איז מיט דעם פירט",[["820","9","ראה שיחת י\"ט כסלו שנה זו (לעיל ע' 91). וש\"נ."],["821","10","ראה שיחת ליל אחרון של פסח תש\"ו (לעיל ע' 40). וש\"נ."],["822","11","ראה שיחת יום שש\"פ תש\"ט (לקמן ע' 320)."],["823","12","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."],["824","13","משנה פסחים נ, סע\"א."],["825","14","ראה גם אגרות­-קודש ח\"ט ע' תמח."]]],[4301620342,"ער אויס די כוונה העליונה צו מברר ומעלה זיין דעם חומר המקום ווי עס איז עלה ברצונו ית'<sup data-n=\"826\">15</sup>.\n* * *\nאון דאָס איז די כוונה וואָס הוד כ\"ק אאמו\"ר הרה\"ק האָט געזאָגט, אַז דורך דעם ווערט דער עילוי פון דעם אור עצמי פון דעם עצם הנשמה בשרש שרשה ווי זי איז מושרש אין עצמות און פירט דורך די כוונת הירידה. דער עילוי איז די כוונה פון דער ירידה, און די עלי' פון דער נשמה, דורך קיום התורה ומצות ועבודה שבלב אין אַלע ענינים הגשמי' דורך דער התפשטות הנשמה אין כחות הנשמה, איז משלים די כוונה פון דער ירידה.\nבאחת משיחות הקדש, באחד הטיו­לים בנאות דשא סערעברינקאַ בקיץ תרנ\"ט, הואיל הוד כ\"ק אאמו\"ר הרה\"ק לבאר לי ענין הכוונה בירידת הנשמה בגוף צוליב דער עלית הנשמה וואָס ווערט דורך דער ירידה. און האָט מבאר געווען די מעלת עליית הנשמה וואָס ווערט דורך דעם. די ירידה איז אין מדריגת הנשמה און די עלי' וואָס ווערט דורך דער ירידה איז אין עצמות הנשמה.\nהוד כ\"ק אאמו\"ר הרה\"ק האָט דאַן מבאר געווען באריכות גדולה מעלת העלי' אין עצם הנשמה, היינו אין די מדריגות חי' יחידה, וואָס קומט דורך ירידת הנשמה, און מיט דעם האָט הוד כ\"ק אאמו\"ר הרה\"ק מבאר געווען דעם ענין פון מאסר הוד כ\"ק רבינו הזקן וואָס דורך דעם איז געווען התגלות עצם נשמתו למטה.\n* * *\nבקיץ תרע\"ה האָט הוד כ\"ק אאמו\"ר מבאר געווען דעם ענין אַז יוסף ואחיו הם אצילות ובי\"ע. יוסף איז אַ נשמה דאצילות בגילוי למטה בהתלבשות בגוף. יוסף אין מצרים איז דער מיין אין דעם, אַז יוסף וואָס נשמתו איז דער אור האצילות. חכמה דאצילות כמו שהיא באצילות איז ווי זי איז בשרש שרשה אין עצמות א\"ס קומט זי לידי גילוי למטה אין חכמה דאצילות, איז אָט די מדריגת החכמה ווי זי איז מושרש בעצמות א\"ס האָט באַ יוסף'ן מאיר געווען בגופו למטה בגילוי, אַז גייענדיק אין די מצרים'ער גאַסען האָט באַ אים מאיר געווען נשמתו דאצילות ווי זי איז מושרש בשרש שרשה אין עצמות א\"ס ב\"ה.\nבדא\"ח מבואר בארוכה בענין יוסף ואחיו שהם אצילות ובי\"ע, הנה יוסף הכיר את אחיו והם לא הכירוהו<sup data-n=\"827\">16</sup>. יוסף איז עצמות האצילות בשרש העליון בעצמות א\"ס, ואחיו שרשם בבי\"ע, הנה יוסף שהוא במדריגת האצילות אפילו בהיותו במצרים הכירם, דאצילות ענינה ענין ההכירות, אבל אחיו שהם במדריגת בי\"ע לא הכירוהו. באַ יוסף'ן איז הת­פשטות אור נשמתו דאצילות היתה גם למטה במצרים בגילוי, ולכן הנה אחיו לא הכירוהו מפני שהם נשמות דבי\"ע. נשמות דבי\"ע האָבען ניט קיין הכרה אין מדריגות האצילות.\nפאַרשטיין דעם ענין פון יוסף ואחיו במצרים אין עבודה. יוסף איז אצילות העליון ווי אצילות איז בשרש שרשה אין עצמות א\"ס ב\"ה. ואחיו בי\"ע. אצילות הוא גילוי העצמי ובי\"ע גילוי ההארה. עצמות האצילות איז בכל מקום שהוא איז דאָס עצמות. יוסף במצרים איז אַז דער",[["826","15","ראה גם שיחת י\"ב תמוז שנה זו (לעיל ע' 138)."],["827","16","מקץ מב, ח."]]],[4301620343,"גילוי העצמות איז דורך מצרים, מצרים וגבולים. עצמות האצילות ווערט נתגלה דורך דעם גילוי בי\"ע. ובעבודה הו\"ע מעלת העבודה על השכלה. כי כללות ענין ההשכלה הוא שתהי' עבודה. והעבודה היא אריכות התפלה. והיינו דאַוונען מיט אַ דערהער אין דער הת­בוננות שקודם התפלה, און דורך דער התבוננות פון אַ חסידישער השכלה, וואָס די השכלה בריינגט די הבנה פנימית אַז דער עיקר איז די התפעלות המדות.\nאון דאָס איז דער מיין אַז התעוררות המדות מאַכט דעם עובד פאַר אַ משכיל, היינו אַז מען טוט אין השכלה צוליב עבודה איז שכרו, אַז מען פילט אָט דאָס וואָס מען פאַרשטייט, וכמאמר הידוע לא כל משכיל עובד וכל עובד משכיל, אַז מען פילט די עניני התבוננות, דאָס הייסט אַז די עניני ההתבוננות קומען אין אַ עבודה בפועל אין תיקון המדות. און דאָס איז דער פירוש עבודה מלשון עורות עבודים<sup data-n=\"828\">17</sup>, אויסגעאַרבעטע פעל. אַ פעל איז בטבעה גראָב און שמעקט שטאַרק, ובעבודה ענינו אַז טוב הגשמי איז גראָב און שמעקט און די עבודה איז, פועל צו זיין דעם בירור וזיכוך הגוף ונה\"ב. און דאָס איז דער דערהער אין דעם וואָרט כל עובד משכיל אַז מען פאַרשטייט אַז דער עיקר איז התגלות המדות, היינו העבודה פון תיקון המדות, און דער תיקון המדות פועלט די התגלות עצם הנשמה, כמבואר בענין העבודה שפועלת עילוי המוחין.\n* * *\nבאחת משיחות הקדש דקיץ תרס\"ג, הואיל כ\"ק אאמו\"ר הרה\"ק לבאר בזה, דההפרש בין אצילות לבי\"ע הוא, אצילות איז אַ אור עצמי און בי\"ע איז אַ אור מתפשט. אין עבודה איז דער הפרש פון אצילות לבי\"ע משכיל און עובד. אַ משכיל האָט פאַרשטאַנד אין דעם ענין המדריגות דאצילות און אַ עובד האָט אַ דערהער אין די מדריגות דאצילות און פילט די מעלת ההרגש דבי\"ע.\nדי מעלת העובד על המשכיל איז, אַז מען פאַרשטייט אַז דער עיקר איז התגלות המדות אין עבודה פון תיקון המדות, און דער דערהער פועלט די התגלות עצם הנשמה, כמבואר בענין מעלת העבודה שפועלת עילוי המוחין, כמו ששמע הוד כ\"ק אאמו\"ר הרה\"ק מהוד כ\"ק אביו הרה\"ק אאזמו\"ר מהר\"ש שקבל מהוד כ\"ק אביו הרה\"ק אדמו\"ר צמח צדק, ששמע הוא וחותנו כ\"ק הרה\"ק אדמו\"ר האמצעי מהוד כ\"ק רבינו הזקן בענין מעלת המוחין על המדות, מוחין פאַרשטייט, מדות פיהלט. באַ אַ חסידישען דאַוונער טראָגט זיך אַרויס דער מוחין פאַרשטאַנד אין אַ מדות געפיל.\nבאריכות גדולה מבאר הוד כ\"ק אאמו\"ר הרה\"ק את מאמר המשנה<sup data-n=\"829\">18</sup> וידעו ביחוד ששם הארון נגנז, ביחוד בבירור<sup data-n=\"830\">19</sup>, אַז מען איז זיך עוסק אין מפריד זיין דאָס ווערעמדיקע פון דעם טוב, דורך עבודת התפלה, איז דער שכר אַז די ידיעה אין דער השגחה אלקית איז אַ בבירור'דיקע, און דאָס איז מעלת העבודה על ההשכלה, וואָס עבודה פועלט דעם עילוי עצם הנשמה.\nהוד כ\"ק אאזמו\"ר הרה\"ק צמח צדק",[["828","17","ראה תו\"א בראשית ה, ב. משפטים עו, א."],["829","18","שקלים פ\"ו מ\"ב."],["830","19","רש\"י ד\"ה ביחוד — פסחים לז, א. רש\"י ד\"ה ומנו — ביצה כב, ב. וראה גם אגרות­-קודש ח\"ד ע' עג."]]],[4301620344,"האָט דערציילט מה שקבל מחותנו הוד כ\"ק הרה\"ק אדמו\"ר האמצעי מה שאמר בשם החסיד ר\"פ רויזעס<sup data-n=\"831\">20</sup> שאמר מה ששמע מהוד כ\"ק רבינו הזקן — בתורה ברבים קודם פטרבורג — אַ משכיל פאַרשטייט און אַ עובד דערהערט.\nאַ חסידישער דאַוונער, מבאר הוד כ\"ק אאמו\"ר הרה\"ק באחת משיחותיו הק' במעלת התפלה בהתעוררות, איז אַ בעל עבודה, וואָס דאָס איז דער עיקר ענין פון השכלה, אַז עס זאָל זיין התעוררות הלב בתקון המדות, והיינו אַז די תפלה פון דער הארת הנשמה שבגוף איז מעלה דעם עצם הנשמה, און דער עילוי איז אַז די הארה איז פועל עילוי העצם.\n* * *\nאַ נשמה<sup data-n=\"832\">21</sup> איז דאָך אָנגעטאָן אין גוף דאַרף מען דאָך אויך האָבען ענינים גשמיים, אויך עבודתה בתורה ומצות איז דאָך אין די ענינים הגשמיים. זאָל השי\"ת ממלא זיין הצטרכות כל אחינו בני ישראל בבני חיי ומזוני בהרחבה, אַז די גשמיות זאָל זיין בהצלחה און זאָל זיין אַ כלי טובה צו די רוחניות.\nוכולנו, אתם ואנחנו ובני ביתנו יחיו, בתוך כלל אחב\"י בכל מקום שהם, נתברך בשנה טובה ומתוקה בגשמיות וברוחניות.\nלשנה טובה תכתבו ותחתמו.",[["831","20","ראה אודותו לעיל ע' 4. וש\"נ."],["832","21","ראה גם אגרות­-קודש ח\"ט שם (ע' קסט­קע)."]]],[4301620345,"<h3>ר\"ד יום ד', ח\"י אלול תש\"ז<sup data-n=\"e1\">*</sup></h3>\n<h4>— יובל שנים להתייסדות תומכי-תמימים<sup data-n=\"833\">1</sup> —</h4>\nא. כשהבעש\"ט הי' בהיכל המשיח, שמע, שפשיטות פון אַ אידן איז פשיטות העצמות<sup data-n=\"834\">2</sup>.\nב. אאמו\"ר אמר שח\"י אלול איז אַ רוקנביין (חוט השדרה). כלומר, כי ח\"י אלול<sup data-n=\"835\">3</sup> הי' ביום הרביעי בשבוע, ויום הרביעי הוא חוט השדרה של השבוע.\nג. ח\"י אלול גיט אַ חיות אין \"אני<sup data-n=\"836\">4</sup> לדודי ודודי לי\"<sup data-n=\"837\">5</sup>.\nח\"י אלול איז אַ חיות פנימי במסירה ונתינה.",[["833","1","כ\"ק אדמו\"ר שליט\"א אמר להרש\"ל שלא יתוועד מצד חלישות בריאותו. והוסיף שיתוועדו בבית המדרש. אח\"כ נכנס הרש\"ג לבקש את כ\"ק אדמו\"ר שליט\"א להתוועד מכיון שזהו חמישים שנה להתייסדות ישיבת תומכי­תמימים. והסכים כ\"ק אדמו\"ר שליט\"א."],["834","2","ראה לעיל ע' 3. וש\"נ."],["835","3","בשנת תק\"ה (שנת לידת אדמו\"ר הזקן) ובשנת תרנ\"ז (שנת התייסדות ישיבת תומכי­תמימים)."],["836","4","שה\"ש ו, ג."],["837","5","ראה ספר השיחות תש\"ה ע' 122. לקו\"ש חי\"ט ע' 250 ואילך. חכ\"ד ע' 177 ואילך. חכ\"ט ע' 161 ואילך. ועוד."],["e1","*","שיחה זו צ\"ל לפני רשימה הקודמת, ומפני סיבות טכניות נדפסה כאן."]]],[4301620346,"<h3>כ\"ט אלול תש\"ז, ערב ראש השנה תש\"ח — אחרי התרת נדרים<sup data-n=\"838\">1</sup></h3>\nהוד כ\"ק אאמו\"ר הרה\"ק זאָגט מיר ערב ראש השנה תרנ\"ח — בעת שזכיתי להכנס לחדר קדשו בסדר יחידות בשעה השלישית לילה:\nערב ראש השנה תרל\"ח בין איך געווען בהשכמה ביים טאַטען אַ פּאָר שעה פאַר דעם זמן פון זאָגען סליחות — דאָס איז געווען דער זיבעטער מאָל צו דער סדר פנימי וואָס הוד כ\"ק אאמו\"ר — אאזמו\"ר — האָט מיר מחנך געווען מיט דעם סדר המיוחד וואָס הוד כ\"ק זקנו רבנו הזקן האָט אים<sup data-n=\"839\">2</sup> מחנך געווען, זאָגנדיק דערביי:\nא רבי, אַ חסידישער מנהיג עדת חסידים ווערט ניט מעצמו. אַז מען זאָל זיך לייגן שלאָפן אַ חסיד, אפילו מיט אַ שטאַרק גוט דורכגעדרונגענע אין האַרצן און אין קאָפּ קריאת­שמע שעל­המטה און אַ חסידישער שלאָף; נאָך אַלעמען איז דאָס אַ סדר פון אַ חסיד, אַ געזונטער — און מען קען אויף דעם זאָגן אַ געהויבענער חסידישער סדר, אָבער ניט קיין רבי סדר.\nהוד כ\"ק אבותינו רבותינו הקדושים נשיאי חב\"ד, זיינען אַ המשכה פנימי דור אחר דור מהוד כ\"ק רבנו הזקן, וואָס הוד כ\"ק רבנו הזקן איז געווען אַ נשמה חדשה<sup data-n=\"840\">3</sup>, וואָס עתיקא קדישא האָט מכתיר געווען, אַז די עצם הנשמה ווי זי איז למעלה אין עולם היחוד דעולם אצילות זאָל אַראָפּקומען למטה אין דער התלב­שות פון דעם גוף<sup data-n=\"841\">4</sup>, און דער גוף זאָל מיט דעם כח פון שרש שרשו אין עצמות א\"ס הבלי גבול מגלה זיין דעם עומק פנימי פון גבול בגילוי בהמשכה לדורי דורות מיט אַ נתינת כח ועלי' ועבודה פנימית.\nאויף ירידת הנשמה למטה און אַז זי זאָל זיך מתלבש זיין אין אַ גוף, איז דאָס בדרך גזירה, וואָס הקב\"ה און בית דין שלמעלה זיינען גוזר אויף דער נשמה אַז זי זאָל אַראָפּקומען למטה להתלבש בגוף, ווייל די נשמה מצד עצמה וויל ניט אַראָפּגיין דאָ למטה, די נשמה למעלה איז איר דאָרט זייער גוט, נאָר דאָס איז מצד גזירה.\nאַז די נשמה פון הוד כ\"ק רבינו האָט געדאַרפט אַראָפּקומען האָט מען איר געזאָגט אַז לבד זאת וואָס עס וועט זיין גילוי עצם הנשמה דאָ למטה, עוד נוסף על זה, אַז ער וועט זיין דער מנהיג הראשון פון דעם סדר נשיאי חב\"ד, און אַז מיט דער מסירת נפש עבודה און די אהבה וקירוב ישראל עבודה וועט מען זוכה זיין צו גילוי משיח צדקנו.\nדעם ענין פלעגן הוד כ\"ק אבותינו רבותינו הקדושים דערמאָנען און אין דעם ריידען אין פערשידענע אויס­פירליכע אויסשפּראַכן, כל אחד מהוד כ\"ק נשיאי חב\"ד אַלע ערב ראש השנה.\nהוד כ\"ק רבינו הזקן איז ירד מרום",[["838","1","נדפס (בשינויים קלים) בספר השיחות תש\"א ע' 171 (מרשימה בלתי מוגה) [ובכותרת שם: \"ערב ראש השנה תש\"א\". וצ\"ל: \"תש\"ח\"]."],["839","2","כ\"ה בהרשימה (אינה מוגהת) וצ\"ע. — הערה בספר השיחות תש\"א שם."],["840","3","ראה ש\"פ שיחת וישב כ\"ו כסלו תש\"ו (לעיל ע' 22). וש\"נ."],["841","4","ראה גם רשימה דש\"פ נצבים תש\"ז (לעיל ע' 150 ואילך)."]]],[4301620347,"מעלה ביז מטה מטה, ניט נאָר דאָס, אַז דער מטה זאָל ווערן אַ כלי צו מעלה, נאָר אַז דורך עבודה אויפהויבן דעם מעלה גופא.\nהוד כ\"ק אאמו\"ר הרה\"ק האָט דאָס מבאר געווען, אַז עס זאָל נתגלה ווערן דער פנימיות הרצון אין עצמות, וואָרום מצד עצמות איז דאָך הכל שוה, זאָל נתגלה ווערן דער פנימיות הרצון.\nדער אויבערשטער זאָל געבען אַלע אידן בכל מקום שהם, אַ שנה טובה ומבורכת אין גשמיות און אין רוחניות. עס זאָל זיין חסידישע גשמיות. דאָס מיינט, אַז עס זאָל גאָרניט פעלן אין גשמיות, מען זאָל האָבן אַלץ וואָס מען בעדאַרף. חסידישע גשמיות מיינט, אַז מען זאָל ניט דאַרפן האָרעווען אויף אַראָפּנעמען די גראָבקייט פון גשמיות, עס זאָל זיין על דרך ווי מן ולחם מן השמים — שבאמת הם ב' ענינים: מן ולחם מן השמים — וואָס דאָס מיינט אַז די גשמיות איז רוחניות'דיק.\nדער אויבערשטער זאָל געבן אַ שנת חיים וברכה אין גשמיות און אין רוחניות און מען זאָל האָבן אַ חיות אין עבודה."],[4301620348,"<h3>ערב ראש השנה תש\"ח</h3>\n<h4>שיחה ביחידות</h4>\nא. דער מנהג ביי הוד כ\"ק אאמו\"ר הרה\"ק און אַזוי אויך ביי אַלע רביים — נשיאי חב\"ד — איז געווען, אַז מען פלעגט זאָגען די ערשטע נאַכט ר\"ה נאָך מעריב \"לשנה טובה תכתב ותחתם\" צו אַלעמען<sup data-n=\"842\">1</sup>, יעדערן באַזונדער, אפי' אויך צו קליינע קינדער.\nב. מען זאָל דערהערן די שמחה פון ר\"ה. — די שמחת המלך.\nסעודת ליל א' דראש השנה תש\"ח\nהנהגות: אכילת התפוח בליל א' דר\"ה היא אחר נטילת ידים — בתחילת הסעודה<sup data-n=\"843\">1</sup>.\nשאלה: אם יכולים לצאת בברכה בפה\"ע שעושים על התפוח גם אכילת הקאָמפּאָט שבסוף הסעודה.",[["842","1","ראה גם \"התמים\" חוברת ב ע' קלב [קיג, ב] — \"מזכרונותיו של אחד התמימים\" מחודש תשרי תר\"ס."],["843","1","סידור אדה\"ז במקומו. בלקוטי מנהגים שבקונטרס ח\"י אלול תש\"ט (סה\"מ תש\"ט ע' 232): אכילת התפוח בליל ראשון. . קודם נט\"י לסעודה (וכ\"ה בספר השיחות תש\"ה ע' 4). ובמברק מיום כ\"ח אלול תש\"ט (אגרות­-קודש כ\"ק אדמו\"ר שליט\"א חכ\"א ע' צח): בבקשה לפרסם [לאנ\"ש]. . השמטה שבלקוטי מנהגים וצריך להיות אכילת התפוח בתחלת הסעודה. וראה גם לקמן ע' 276. לקוטי מנהגים שבקונטרס ר\"ה ה'שי\"ת (סה\"מ ה'שי\"ת ע' 26). ספר המנהגים — מנהגי חב\"ד ע' 56. הטעם בזה — ראה אגרות­-קודש כ\"ק אדמו\"ר שליט\"א ח\"ג ע' רט."]]],[4301620349,"תשובה: ניט נאָר מ'קען נאָר אַזוי דאַרף מען טאָן ולכוין לצאת<sup data-n=\"844\">2</sup>.\nבסעודת ליל א' דר\"ה ויומו לא דיבר כ\"ק אדמו\"ר שליט\"א מאומה<sup data-n=\"845\">3</sup>.",[["844","2","ראה ספר השיחות תרפ\"ח­תרצ\"א ע' 139."],["845","3","ע\"ד הנהגת רבותינו נשיאינו לא לדבר בליל א' דר\"ה — ראה גם ספר השיחות תרפ\"ח­תרצ\"א שם. שיחת כ' כסלו תרצ\"ג סעיף יד. ספר השיחות: תש\"א ע' 26 ואילך; תש\"ב ע' 2; תש\"ד ע' 3 ואילך; תש\"ה ע' 3. וע\"ד המנהג לא לדבר ביום א' דר\"ה — ראה ספר השיחות תש\"ה שם. לקמן ע' 272. וראה ספר השיחות תש\"ד שם ושיחת ליל ב' דר\"ה תש\"ט (לקמן ע' 273 ואילך) — ע\"ד הנהגת כ\"ק אדמו\"ר נ\"ע לא לדבר עד אחרי המאמר בליל ב' דר\"ה."]]],[4301620350,"<h3>סעודת ליל ב' דראש השנה תש\"ח</h3>\nהנהגות: ע\"ד ברכת שהחיינו על הפרי היתה שקלא וטריא אם תיכף אחר קידוש<sup data-n=\"846\">1</sup> או בתחילת הסעודה, והחליט כ\"ק אדמו\"ר שליט\"א, שצריכים לעשות ברכת שהחיינו תיכף אחר קידוש קודם נט\"י לסעודה<sup data-n=\"847\">2</sup>, על שיעור כזית ולעשות ברכה אחרונה<sup data-n=\"848\">3</sup>.\nולמעשה עשה כ\"ק אדמו\"ר שליט\"א ברכת שהחיינו על ב' פירות שלימות מז' פירות א\"י<sup data-n=\"849\">4</sup>, תיכף אחר קידוש קודם נט\"י לסעודה ובירך ברכה אחרונה מעין ג', ואח\"כ רחץ ידיו לסעודה<sup data-n=\"850\">5</sup>.\nברהמ\"ז בליל א' ובליל ב' דר\"ה עשה כ\"ק אדמו\"ר שליט\"א על הכוס הגם שלא הי' מנין לברהמ\"ז<sup data-n=\"851\">6</sup>.",[["846","1","קודם נט\"י לסעודה."],["847","2","הטעם בזה — ראה אגרות­-קודש כ\"ק אדמו\"ר שליט\"א ח\"ג שם."],["848","3","בנוסח אחר: ואמר שיש איזה ברירות אם לאכול פחות מכזית ולא לברך ברכה מעין ג' או לאכול כשיעור כזית ולברך."],["849","4","משבעת המינים."],["850","5","ראה גם ספר השיחות תש\"ה ע' 4. לקמן ע' 276."],["851","6","ראה גם שיחת ליל ש\"ק נח, בדר\"ח מר­חשון, תש\"ז (לעיל ע' 83). וש\"נ."]]],[4301620351,"<h3>סעודת ליל ב' דר\"ה תש\"ח</h3>\nא. אין יאָר תרמ\"ח האָט הוד כ\"ק אאמו\"ר הרה\"ק ביי אַ פאַרבריינגען גע­זאָגט, אַז דער אַלטער רבי האָט געמאַכט אַ סדר פאַר ימות החול, שבתים, ר\"ח, מועדים און ימים נוראים.\nעס איז געווען אַ ספק, אם כבנים אם כעבדים, אויב דער סדר איז שייך אויך צו עבדים — חסידים, אָדער נאָר צו בנים — נשיאים, ויש בן שהוא עבד ויש עבד שהוא בן.\nדער סדר פון די ערשטע נאַכט אין ערשטען טאָג ר\"ה איז, מען איז טרוד אין מחשבה<sup data-n=\"852\">1</sup> ביז מחשבה הקדומה, אין ענינים כלליים. דער צווייטער טאָג איז אין דיבור.\nשאלה: מהו ענינים כלליים?\nתשובה: עס זיינען דאָ ענינים וואָס",[["852","1","ראה גם שיחת ליל א' דר\"ה שנה זו הערה 3."]]],[4301620352,"אָדער מען דאַרף ניט קיין ביאור, אָדער עס העלפט ניט קיין ביאור. בכלל איז אפילו אַ נשמה פרטיות האָט אויך ענינים כלליים, בפרט אַ נשמה כללית ובפרטי פרטיות אַ נשיא בישראל.\nהוד כ\"ק אאמו\"ר הרה\"ק פלעגט זאָגען דעם ראש השנה'דיגען מאמר די צווייטע נאַכט ר\"ה נאָך מעריב<sup data-n=\"853\">2</sup>. און האָט געזאָגט דעם טעם אויף דעם: מען דאַרף אַז דער דיבור הרשות אין דער המשכה חדשה זאָל זיין אין תורה און חסידות, הגברת הצורה עצמית על החומר און ווערען אַ כלי צו עבודה פנימיות<sup data-n=\"854\">3</sup>.\nב. ביי הוד כ\"ק אאמו\"ר הרה\"ק זיינען געווען פיר סדרים א) דער סדר פון יום א' דר\"ה, ב) דער סדר פון צווייטען טאָג ר\"ה ביז יוהכ\"פ, ג) דער סדר פון די ד' ימים בין יוכ\"פ לסוכות, און ד) דער סדר פון די ימי חג הסוכות.\nבמשך די זמנים פלעגט הוד כ\"ק אאמו\"ר הרה\"ק דערמאָנען יעדען טאָג, אַ סיפור, אַ וואָרט אָדער אַ הנהגה פון רשב\"י, האריז\"ל, הבעש\"ט, המגיד מ­מעזריטש, און ביחוד פון הוד כ\"ק רבנו הזקן און הוד כ\"ק רבותינו הק' זי\"ע<sup data-n=\"855\">4</sup>.\nיעדער וואָרט אָדער סיפור איז גע­ווען אַ אור מקורי וחיוני.\nג. הוד כ\"ק אאמו\"ר הרה\"ק האָט דערציילט, אַז ביי דעם אַלטן רבי'ן איז געווען אַ זמן, וואָס ער האָט געזאָגט תורות אין \"ווערטער\"<sup data-n=\"856\">5</sup>.\nאיינמאָל האָט דער אַלטער רבי גע­זאָגט אַ תורה: כי נר מצוה ותורה אור<sup data-n=\"857\">6</sup>, כי נר מצוה אַ מצוה איז אַ ליכט, זי בעלייכט דעם גאַנצען גשמי, ותורה אור, אור היום.\nושאלתי אז את הוד כ\"ק אאמו\"ר הרה\"ק: אין אַ קורצען וואָרט קען מען דאָך האָבען אַ טעות?\nוענה לי:\nאַז מען טשעפּעט זיך אָן אין אמת, האָט מען ניט קיין טעות, דוק ותשכח.\nושאלתי עוד: ווי אַזוי?\nוענה לי:\nדי ערשטע זאַך לייג \"עם\" אַוועק. \"איך בין אַ משכיל\", \"איך בין אַ עובד\", מען דאַרף אַוועקלייגען דעם \"איך\".\nד. בעת מיין בר מצוה<sup data-n=\"858\">7</sup> האָט הוד כ\"ק אאמו\"ר הרה\"ק פאַרבראַכט<sup data-n=\"859\">8</sup> יעדען טאָג מיט חסידים במשך אַ גאַנצע וואָך<sup data-n=\"860\">9</sup>.",[["853","2","ראה גם רשימת היומן — תשרי תרצ\"ה (חוב' יג סי' 12). לקמן ע' 273. \"התמים\" חוברת ד ע' פו [רח, ב] ואילך — \"מזכרונותיו של אחד התמימים\" מחודש תשרי תר\"ס."],["854","3","ראה שיחת ליל ב' דר\"ה תש\"ט (לקמן ע' 274). ע\"ד המאמר ביום ב' דר\"ה — ראה ספר השיחות תש\"ד ע' 11. תש\"ה ע' 10. וראה אגרות­-קודש כ\"ק אדמו\"ר שליט\"א ח\"ד ע' תצח."],["855","4","ראה — ע\"ד המנהג להזכיר את רבותינו נשיאינו בליל ב' דר\"ה — ספר השיחות תש\"ד ע' 3. אגרות­-קודש כ\"ק אדמו\"ר שליט\"א ח\"ג ע' תסט הערה 4. ובשיחת יום ב' דר\"ה תשד\"מ נתחדש להזכיר את האריז\"ל (הטעם לזה — ראה בשיחה הנ\"ל). ובשיחת ליל ב' דר\"ה תשמ\"ה: \"ונוסף לזה, נהוג להזכיר ענין מתורתם של כאו\"א מרבותינו נשיאינו, ומכיון שמלבד החידושים של כל נשיא ונשיא. . ישנו גם הענין ד\"יתפרנסון מיני'\", בנוגע תורת הקבלה — נמצא, שע\"י הזכרת ענין מתורתם מזכירים גם את האריז\"ל ורשב\"י\"."],["856","5","ראה גם שיחת ליל שש\"פ תש\"ז (לעיל ע' 111)."],["857","6","משלי ו, כג."],["858","7","י\"ב תמוז תרנ\"ג."],["859","8","שיחות ורשימות מהבר­מצוה — ראה קונטרס בר מצוה תרנ\"ג (קה\"ת, תש\"ס)."],["860","9","ראה קונטרס הנ\"ל ע' כ ואילך. אגרות­-קודש ח\"ט ע' שסו."]]],[4301620353,"הרי\"מ מפּאָלטאַווא<sup data-n=\"861\">10</sup> האָט דאַמאָלסט אין איינע פון די פאַרבריינגענס געזאָגט צו הוד כ\"ק אאמו\"ר הרה\"ק אַז מען האָט נאָך ניט פאנאַנדערגענומען די אותיות פון חסידות.\nהאָט אים הוד כ\"ק אאמו\"ר הרה\"ק געענטפערט:\nדאָס קען מען ניט זאָגן, יעדער דאַרף זאָגן נאָך זיין הרגש והשגה. וואָס מען קען יע זאָגן איז, אַז עס האָט נאָך ניט דערנומען.\nולקח הרי\"מ כוס משקה ובכה ואמר: אַזוי לאַנג געהאָרעוועט.\nאון אַזוי ווי רשב\"ץ<sup data-n=\"862\">11</sup> פלעגט מיר זאָגען, בעת ער האָט מיט מיר אָנגע­הויבען לערנען: אַז מען לערנט חסידות, אָבער אין עניני עבודה — לא פגע ולא נגע<sup data-n=\"863\">12</sup>.\nה. מ'קען זאָגען: אַ ליכטיגן ג\"ע זאָל האָבען מיין מלמד ר' ניסן<sup data-n=\"864\">13</sup>, ער האָט מיר מסביר געווען קליינערהייט אַ פולע ענינים. איך האָב געהערט, אָבער נאָך ניט געווען שייך צו פאַרשטיין, און ר' ניסן פלעגט מיר מסביר זיין אויף דעם וואָס איך האָב געהערט תילי תילים<sup data-n=\"865\">14</sup>.\nו. דער עלטער זיידע פון ר' ניסן<sup data-n=\"866\">15</sup> און דער זיידע פון המלמד ר' יקותיאל<sup data-n=\"867\">16</sup> זיינען געווען, די צוויי זקנים מלמדים ביי דעם אַלטן רבי'ן אין הויז<sup data-n=\"868\">17</sup>.\nעס איז ידוע די מעשה<sup data-n=\"869\">18</sup>, וואָס דער אַלטער רבי האָט געזאָגט צו איינעם פון זיי: איך וויל מיט דיר בייטען אַ מצוה פאַר אַ מצוה.\nדער אַלטער רבי האָט דאַן געזאָגט: איך גיב דיר לחם, וואָס דאָס איז פנימית, און דו זאָלסט אויך געבען אין אַ פנימית.\nז. קומענדיג פון מעזריטש האָט דער אַלטער רבי געזאָגט<sup data-n=\"870\">19</sup>, אַז דאָרט האָט ער גענומען די מעלה פון אַ חסיד, חסיד העכער פון אַ צדיק. דער טאַטע<sup data-n=\"871\">20</sup> איז געווען אַ צדיק, ער איז דאָך געווען דעם בעל שם'ס אַ מענטש<sup data-n=\"872\">21</sup>.\nאיידער מען האָט געוואוסט אַז די פשיטות פון אַ איש פשוט איז די פשיטות העצמות<sup data-n=\"873\">22</sup>, בין איך אויך געווען אריינ­געשטעלט אויף דעם סדר פון אַ צדיק, אַז איך בין געקומען אין מעזריטש האָב איך דערהערט די מעלה פון אַ חסיד.\nח. די עבודה איז אין דער הארת הנשמה שבגוף, אָבער עס איז פועל אין עצם הנשמה<sup data-n=\"874\">23</sup>. הנשמה עצמה אינה צרי­",[["861","10","ראה אודותו לעיל ע' 11."],["862","11","ראה אודותו לעיל ע' 12. וש\"נ."],["863","12","ראה גם לעיל ע' 24. לקמן ע' 329. ע' 332."],["864","13","ראה אודותו לעיל ע' 41. וש\"נ."],["865","14","ראה גם שיחת ליל א' דחה\"ש תש\"ז ס\"א (לעיל ע' 128)."],["866","15","ראה רשימת היומן של רבינו מיום א', כ' אייר תרנ\"ו (לקו\"ד ח\"ג תקכח, ב ואילך). ספר השיחות קיץ ה'ש\"ת ע' 69. לעיל ע' 43."],["867","16","ראה ספר השיחות שם ע' 161."],["868","17","ראה ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 111; ע' 119 (ושם, שחותנו של ר' יקותיאל הי' מלמד בליאַדי אשר רבינו הזקן למדו איך ללמוד ה\"אלף בית\" עם ילדים)."],["869","18","ראה שיחת י\"ג תמוז תרצ\"ב. \"היום יום\" ח אדר א. אגרות­-קודש ח\"ב ע' תצא. ח\"ג ע' שט. ספר השיחות שם. רשימת חורף ה'שי\"ת ס\"ז (לקמן ע' 395) — ושם, שהי' זה זקנו של ר' דובער ב\"ר פסח מלמד."],["870","19","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."],["871","20","ר' ברוך, אביו של אדמו\"ר הזקן."],["872","21","ראה גם שיחת פורים תש\"ו (לעיל ע' 22). וש\"נ."],["873","22","ראה לעיל ע' 3. וש\"נ."],["874","23","ראה סה\"מ תרפ\"ד ע' ד. תש\"ט ע' ו."]]],[4301620354,"כה תיקון<sup data-n=\"875\">24</sup>, אָבער אור דאַרף זי; דער עונג איז, אַז די הארת הנשמה שבגוף זאָל דערהערן דעם עצם הנשמה.\nאָבער דער עונג פון עצם הנשמה איז, אַז זי דערהערט די הפלאה פון די עבודה פון הארת הנשמה שבגוף.",[["875","24","תניא פל\"ז (מח, ב)."]]],[4301620355,"<h3>סעודת יום ב' דראש השנה תש\"ח</h3>\nא. הרמ\"ש שי' סיפר לכ\"ק אדמו\"ר שליט\"א אודות סדר תהלוכות התשליך ביום א' דר\"ה, והעיר שאחד אמר בשם כ\"ק אדמו\"ר שליט\"א שאינו שבע רצון שירקדו בשובם מן התשליך, וענה כ\"ק אדמו\"ר שליט\"א:\nאדרבא איך האָב זיך נאָכגעפרעגט אויב מען האָט געטאַנצט, און אַז מען האָט מיר געזאָגט אַז ניט, האָט עס מיר געוואונדערט.\nווי קען מען גאָר זאָגן, אַז איך בין ניט צופרידן פון אַ אידישע טאַנץ בכלל, פון אַ חסידישן טאַנץ בפרט און פון אַ תמימים טאַנץ בפרטי פרטיות. דאָס גייט ביי מיר אַריין בגדר לה\"ר.\nב. אַ סאַך אידן האָבן געבעטן און אויסגעבעטן אַ מפלה אויף די שונאי ישראל, און אַז אַלע זאָלן וויסען דעם אמת. סתם מענטשען האָבען אַ אויס­שפּראַך, דער איז שולדיג \"די פּאָליטיקע איז שולדיג\", און מען פאַרגעסט אַז טבע איז אלקות<sup data-n=\"876\">1</sup>, און בפרט אין כלליות ענינים, וואָס זיינען נוגע אידען און ארץ ישראל.\nאיך בין ניט קיין פּאָליטיקער און וויל דאָס ניט זיין, איך בין אַ אהבת ישראל מחונך איד, אַז מען דאַרף האָבן מסי\"נ אויף אידישקייט און אידן.\nאין אה\"ק ת\"ו זיינען פאַראַן יונגע לייט וואָס זיינען זעך מוסר נפש פאַר אידען, זיי טוען זייער אַ גוטע אַרבעט, דער אויבערשטער זאָל זיי שטאַרקען די הענט בהצלחה. זיי דאַרפן האָבן תיקון אין קיום מצות מעשיות, זיי דאַרפן היטן שבת, לייגן תפילין, כשרות וכו', אָבער דאָס זיינען מענטשען, נאָר מיט חסרונות. מען באַדאַרף לייגן די גרעסטע כחות מקרב זיין זיי צו קיום המצות מעשיות. אָבער אויף די גוטע זאַכן וואָס זיי טוען מיט דעם אידישן ברענענדיגן מסירות נפש באַדאַרפן אַלע אידן — בלי הבדל מפלגה — זאָגן און בענטשען: תחזקנה ידיהם.\nג. אין ליובאַוויטש פלעגט מען דעם צווייטען טאָג ר\"ה נאָכ'ן מאמר גיין אַ ריקוד אין הויף<sup data-n=\"877\">2</sup>.\nהוד כ\"ק אאמו\"ר הרה\"ק פלעגט שטיין ביי זיך אין חדר נעבען פענסטער — די פענסטער איז געווען פאַרהאָנגען אַזוי, אַז מען האָט געקענט אַרויסקוקען און ניט ווערען געזען — און זיך צוקו­קען, און דערביי האָט ער אַמאָל געזאָגט:\nאיך בין ניט קיין בעל התפעלות, נאָר דאָס דערנעמט מיר אין אַ ענין פנימי דפנימי, זיי קנעטן אויס די ערד.",[["876","1","ראה גם סה\"מ תרפ\"ט ס\"ע 41 ואילך. וש\"נ."],["877","2","ראה רשימת היומן תשרי תרצ\"ג (\"רשימות\" חוברת יד ע' 3): \"במוצאי ר\"ה היו יוצאים במחול, אבל לא [במוצאי יום א'] אור ליום ב'\". וראה גם \"התמים\" חוברת ד ע' פט [רי, א] — \"מזכרונותיו של אחד התמימים\" מחודש תשרי תר\"ס."]]],[4301620356,"ליובאַוויטשער בלאָטע איז דאָך אַ מדריגה<sup data-n=\"878\">3</sup>. עס איז ידוע וואָס הוד כ\"ק אאזמו\"ר הרה\"ק הצ\"צ האָט געזאָגט אויף די ליובאַוויטשער בלאָטע: אַלע לאָזען דאָ איבער און איך דאַרף עס אויס­טריקענען.\nאון הוד כ\"ק אאמו\"ר הרה\"ק האָט מסיים געווען: מה דאָך אַז אויף ליו­באַוויטשער בלאָטע דאַרף מען האָבן חסידישע פיס, כל שכן אויף די בלאָטע בעלמא.\nד. רשב\"ץ<sup data-n=\"879\">4</sup> פלעגט מאַכען אויף יעדע זאַך ר\"ת, אויף תומכי-תמימים האָט ער געזאָגט צוויי תוי'ן ר\"ת תילים, תניא. מען דאַרף זאָגן תהלים ווי מ'לערנט תניא און לערנען תניא ווי מ'זאָגט תהלים. אַלע אידן זאָגן תהלים און קיינער ווייס ניט דעם פשט, אין תניא אויך אַזוי<sup data-n=\"880\">5</sup>.\nהוד כ\"ק אאמו\"ר הרה\"ק האָט ניט ליב געהאַט די וואָס לערנען תניא מיט חכמה'לעך. אין עבודה קען מען יע ריידען<sup data-n=\"881\">6</sup>, דאָס איז דער פטטיא דאורייתא טבין<sup data-n=\"882\">7</sup> — פטטיא וואָס בריינגען לאו­רייתא<sup data-n=\"883\">8</sup>.\nדי וואָס זיינען קלאָר פרקים תניא אויסווייניג, נו, אָבער אַזוי דאַרף מען האָבן אין פּאַקעט — קעשענע — אַ תהלים און אַ תניא<sup data-n=\"884\">9</sup>.\nה. די סקאַרבאָווע ניגונים זיינען מקו­בל. הוד כ\"ק אאמו\"ר הרה\"ק איז ניט געווען קיין זאָגער, ניט געווען שייך צו מישען זיך אין די זאַכען — ער פלעגט שטיין ביי דער זייט אויף זיין אָרט, אָבער הוד כ\"ק אאזמו\"ר מוהר\"ש — יע.\nהוד כ\"ק אאזמו\"ר מוהר\"ש פלעגט דאַוונען יוכ\"פ אין אַ בעזונדער חדר נע­בען ביהמ\"ד, בעת דער חזן פלעגט זאָגען די עבודה איז ער אַרויסגעקומען אין ביהמ\"ד, מ'פלעגט שטעלן אַ קרעס­לע — כסא — און ער פלעגט צוהעלפן דעם חזן אין די סקארבאווע ניגונים<sup data-n=\"885\">10</sup>. ר' אלי' אבעלער<sup data-n=\"886\">11</sup> איז געווען פון די",[["878","3","ראה גם שיחת יום אחש\"פ תש\"ט (לקמן ע' 322)."],["879","4","ראה אודותו לעיל ע' 12. וש\"נ."],["880","5","ראה גם אגרות­-קודש חלק ד ע' רסז: \"התניא הוא כחומש, כל ישראל מגדול שבגאונים עד הקטן שבקטנים לומדים חומש, וכל אחד לפי ערכו יודע מה שיודע, ואין שום אחד יודע מאו­מה, וכל הגדול יותר יודע יותר הפלאת המושג\"."],["881","6","ראה אגרות­-קודש אדמו\"ר מהורש\"ב ח\"ב ע' תשכ. אדמו\"ר מהוריי\"צ ח\"ג ע' תט. ספר השיחות תש\"ב ע' 83 ואילך."],["882","7","ירושלמי ברכות פ\"ט ה\"ח."],["883","8","ראה ספר השיחות תש\"ב שם: \"הוד כ\"ק אאמו\"ר האָט אַמאָל געפרעגט דעם זיידן — הוד כ\"ק אאזמו\"ר מוהר\"ש — וואָס איז וועגן די ביאורים אויף תניא. . האָט דער זיידע אדמו\"ר מוהר\"ש נ\"ע געענטפערט: אויב מען לערנט דאָס צוליב השכלה, איז קען געמאָלט זיין אַז ניט ער ווייס פון תניא און ניט דער תניא ווייס פון איהם. אויב, אָבער, ער פאַררעט זיך אין עבודה, איז אפילו אַז דאָס איז ניט די כוונה פון תניא, נאָר צוליב מעורר זיין את הזולת מיט אַ וואָרט — קען מען אפילו די גאַנצע 70 יאָהר ריידן, וכמאמר \"כל פיטטיא בישין ופיטטיא דאורייתא טבין\"."],["884","9","ראה \"פתח דבר\" לתניא — הוצאת קה\"ת — פורמט כיס: \"כמה פעמים דיבר כ\"ק מו\"ח אדמו\"ר בהנחיצות להדפיס התניא בפורמט כזה שיהי' נוח לשאתו בכיס הבגדים, ובמילא יהי' מן המוכן בלכת בדרך וכו'\". וראה שיחת ש\"פ ויקהל מבה\"ח אדר שני תשי\"ד."],["885","10","ראה גם ספר השיחות תש\"ד ע' 26 ואילך. תש\"ה ע' 25."],["886","11","החסיד ר' אלי' וואראבייטשיק מישוב אבעל, מחסידי הצ\"צ ומהר\"ש — ראה אודותו: אגרות­-קודש ח\"ג ס\"ע שטו ואילך. שיחת כ' כסלו תרצ\"ג סעיף ג (לקו\"ד ח\"א לג, ב). ספר השיחות: קיץ ה'ש\"ת ע' 163 ואילך; תש\"ג ע' 111; תש\"ה ע' 95."]]],[4301620357,"גיבורים, וואָס פלעגן שטיין ביי דער זייט צוהעלפן הוד כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש נ\"ע ביי כורעים.\nו. הוד כ\"ק אאמו\"ר הרה\"ק האָט אַמאָל געזאָגט צו איינעם וואָס איז גע­ווען אַ וועגעטאָריער — מי שאינו אוכל מבעלי חיים: פאַרוואָס עסט דו דאָס ניט — משום בעלי חיים, נו און וואָס דו עסט יע, ביזטו זיכער? צי דען וואָס מען זעט ניט און מען הערט ניט, איז מחייב אַז די מציאות איז ניטאָ<sup data-n=\"887\">12</sup>.\nז. כ\"ק אדמו\"ר שליט\"א סיפר מהסדר שהי' בליובאַוויטש בעת אמירת דא\"ח אצל הוד כ\"ק אאמו\"ר הרה\"ק, סדר עמידת השולחנות, ושהיו כמה מוחזקים בקביעת מקום עמידתם בעת אמירת מאמר דא\"ח.",[["887","12","ראה ספר השיחות תרפ\"ח ע' 21."]]],[4301620358,"<h3>משיחות תשרי תש\"ח<sup data-n=\"888\">1</sup></h3>\nאשת מהרשנ\"ע<sup data-n=\"889\">2</sup>, חמותה אשת הצ\"צ<sup data-n=\"890\">3</sup> וכן אשת אדהאמ\"צ<sup data-n=\"891\">4</sup> היו אומרות סליחות בעשי\"ת, אבל לא האנשים<sup data-n=\"892\">5</sup>.\nסיפר אאזמו\"ר (מהרשנ\"ע) לאאמו\"ר, אשר פעם בראותו שאמו הלכה לסליחות — בעשי\"ת — ואביו (הצ\"צ) זיצט און לערנט, שאל אותו עד\"ז. ויענהו הצ\"צ: עס איז דאָ אַ צייט ווען מען דאַרף זאָגען און עס איז דאָ אַ צייט ווען מ'דאַרף טאָן<sup data-n=\"893\">6</sup>.\nבמענה על שאלתי שכתוב לאמר סליחות בצו\"ג, ענה כ\"ק מו\"ח אד\"ש: צום גדלי' איז דאָך פון די ד' צומות.",[["888","1","הועתק מאגרות­-קודש כ\"ק אדמו\"ר שליט\"א ח\"ב ע' רנב — מ\"רשימותי. . תשרי תש\"ח\".\nברשימת אחד התמימים: הרמ\"ש שי' סיפר שבעשי\"ת דיבר עם כ\"ק מו\"ח אדמו\"ר שליט\"א אודות מנהגנו שאין אומרים סליחות בעשי\"ת, וסיפר כ\"ק מו\"ח אדמו\"ר שליט\"א: המהר\"ש כשהי' נער, ראה שאמו קמה בבוקר ללכת לומר סליחות, ואביו הצ\"צ יושב ולומד. ושאל אותו עד\"ז. והשיב הצ\"צ: \"רעביצינס דאַרפן זאָגן\". ועל שאלתו מדוע הוא אינו אומר — השיב הצ\"צ: \"עס איז דאָ אַ צייט אויף זאָגן, עס איז דאָ אַ צייט אויף טאָן\"."],["889","2","הרבנית הצדקנית מרת רבקה. ראה אודותה — לעיל ע' 14. וש\"נ."],["890","3","הרבנית הצדקנית מרת חי' מושקא. ראה אודותה — לעיל ע' שם. וש\"נ."],["891","4","הרבנית הצדקנית מרת שיינא. ראה אודותה — ספר השיחות תש\"ד ע' 65. ועוד."],["892","5","ראה \"רשימות\" ר\"ה רצ\"א (ספר השיחות תרפ\"ח­תרצ\"א ע' 144. הועתק באגרות­-קודש שם)."],["893","6","ראה ספר השיחות תש\"נ ח\"א ע' 351 הערה 132: \"פתגם כ\"ק מו\"ח אדמו\"ר בשם הצ\"צ בביאור מנהג חב\"ד לומר סליחות לפני ר\"ה ולא בעשי\"ת. . שעד כאן (עד ר\"ה) מצות אמירה, ומכאן ואילך מצות עשי'\"."]]],[4301620359,"<h3>ד' תשרי תש\"ח<sup data-n=\"894\">1</sup></h3>\nכ\"ק אאמו\"ר הרה\"ק האָט מיך גע­לערנט האָבען מסירת נפש פאַר ישיבות תומכי-תמימים, איך גיב זיך אינגאַנצען אַוועק לטובת הישיבות תומכי-תמימים.\n* * *\nאיינער פון מיינע פאַרגעניגנס איז — צו ריידן אין דעם ענין פון החזקת לומדי תורה בכלל, און איבערהויפּט וועגן דעם מוסד הקדוש תומכי-תמימים ליובאַ­וויטש, וואָס דער גרונט און ווינקלשטיין פון דעם דאָזיקן מוסד האָט הוד כ\"ק אאמו\"ר הרה\"ק זצוקללה\"ה נבג\"מ זי\"ע געלייגט אין דעם הייליקן טאָג ח\"י אלול שנת תרנ\"ז אין ליובאַוויטש.\nהוד כ\"ק אאמו\"ר הרה\"ק האָט דאַ­מאָלסט געזאָגט<sup data-n=\"895\">2</sup>:\nהיינט איז דער יום הקדוש וואָס דער בית דין של מעלה האָט אָנגענומען כמה החלטות וואָס זיינען נוגע צום יסוד המעלה פון אידן און תורה.\nעס איז נחלט געוואָרן:\nא) ח\"י אלול תנ\"ח — נח\"ת — זאָל זיך די הייליגע נשמה פון מורנו הבעש\"ט מתלבש זיין אין אַ גוף<sup data-n=\"896\">3</sup>.\nב) ח\"י אלול תפ\"ד זאָל מורו הק'<sup data-n=\"897\">4</sup> צו אים נתגלה ווערן און זאָל אים מגלה זיין דעם ביאור התורה פון בראשית ביז לעיני כל ישראל<sup data-n=\"898\">5</sup>.\nג) ח\"י אלול תצ\"ד — זאָל מורנו הבעש\"ט נתגלה ווערן<sup data-n=\"899\">6</sup>.\nד) ח\"י אלול תק\"ה<sup data-n=\"900\">7</sup> — זאָל מורנו הוד כ\"ק רבינו הזקן געבאָרן ווערן.",[["894","1","אַן אויסצוג פון די רייד פון כ\"ק אדמו\"ר שליט\"א, דאָנערשטאָג פ' וילך ד' תשרי תש\"ח, פאר אַ גרופע רבנים און עסקנים, ווען ער האָט אָנגענומען די הצעה אז דער חג היובל פון תומכי­תמימים זאָל זיין געווידמעט לכבודו און דערביי געזאָגט [ההמשך בפנים:]."],["895","2","ראה עוד שיחות מח\"י אלול תרנ\"ז ע\"ד התייסדות ישיבת תומכי­תמימים — אגרות­-קודש ח\"ט ע' תמו ואילך. ספר השיחות קיץ ה'ש\"ת ע' 169. תש\"א ע' 105. תש\"ב ע' 133. וראה לקמן ע' 210."],["896","3","ראה שיחת ליל כ' כסלו תרצ\"ג ס\"א. ס\"ד (לקו\"ד ח\"א לא, א ואילך. לה, א). ספר השיחות תש\"א ע' 132. ע' 152 ואילך. תש\"ג ע' 146. תש\"ד ע' 162 ואילך."],["897","4","אחי' השילוני. — ראה לקמן ע' 232."],["898","5","ראה מכתב הבעש\"ט (ל\"הרה\"ח וכו' מ' יעקב יוסף הכהן כו' פולנאה\", מיום ג' מקץ תקי\"ג) — נדפס ב\"התמים\" חוברת ד ע' יח [קעד, ב] (והועתק בשיחת כ' כסלו תרצ\"ג שם): \"א\"דש\"ה גי\"ה קבלתי ושמחתי כעל כל הון רב והצדק את כ\"ה כי הבטחתי אותו לגלות לו באיזה יום ובאיזה שנה נתגלה אלי מורי אחי' השילוני ועתה בא העת לגלותו אני ביום מלאות לי ך' וא\"ו שנים ביום ח\"י אלול בשנת ת\"פ\"ד בעיר אקופ כחצות הלילה נגלה אלי, איך אין לי רשות, הלימוד הראשון הי' פרשה בראשית וכאשר גמרנו התוה\"ק עד לעיני כל ישר\"אל הייתי בן ל' וא\"ו ונגלתי\". וראה לקמן ע' 420."],["899","6","בשיחת כ' כסלו תרצ\"ג שם: \"עפ\"י הדב­רים האלה [מכתב הבעש\"ט שבהערה הקודמת] אשר ביום ח\"י אלול תפ\"ד נתמלא למורינו הבעש\"ט נ\"ע כ\"ו שנה, הרי נולד בשנת תנ\"ח ח\"י אלול, והתגלותו של מורינו הבעש\"ט הי' — עפ\"י המכתב הנ\"ל — ביום ח\"י אלול תצ\"ד, וכן בכל המכתבים שישנם, הן מכתבי הרה\"ק ר' אדם בע\"ש למורינו הבעש\"ט במשך ג' שנים תצ\"א­תצ\"ג בדברי תורה וביאורים מאמרי הזהר והתיקונים, ודברי תורה על אשר מסרב להתגלות, ומודיע לו אשר כולם החליטו שיתגלה, והן ממכתב מורינו הבעש\"ט לגיסו הרה\"ק ר\"ג נ\"ע, מוכח כי התגלות מורינו הבעש\"ט הי' בשנת תצ\"ד\"."],["900","7","ראה שיחת יט כסלו תרצ\"ד ס\"ב (לקו\"ד פג, א). ספר השיחות קיץ ה'ש\"ת ע' 174. תש\"א ע' 158. תש\"ג ע' 146. תש\"ד ע' 163. תש\"ה ע' 127 ואילך."]]],[4301620360,"די ישיבה תומכי-תמימים וואָס הוד כ\"ק אאמו\"ר הרה\"ק האָט מייסד געווען איז ניט געווען נאָר צוליב לערנען, נאָר אויך צוליב אַריינטראָגען יראת שמים אין וועלט<sup data-n=\"901\">8</sup>.\nאין לערנען תורה קען זיין אַ מתגאה בתורתו<sup data-n=\"902\">9</sup>, ישיבת תומכי-תמימים האָט אויפגעטאָן אַז די תלמידים זאָלן זיין בעלי מסירת נפש.\nדעם כח המסירת נפש פון כ\"ק אאמו\"ר הרה\"ק מייסד ישיבת תומכי-תמימים, קען מען היינט זען ביי די תלמידי התמימים פון דער אַלטער גע­בענטשטער היים ליובאַוויטש, אין אַלע גלות לענדער און אה\"ק תובב\"א.\nאין היילן אַ מחלה זיינען פאַראַן ב' אופנים: הא') היילן די מחלה אַליין. הב') מחזק זיין די אברים, אַריינגעבן אַ חיזוק כללי, און דאַן ווערט די מחלה ממילא געהיילט.\nאיך ווינטש אַלע עוסקים ומתעסקים און אַלע מנדבים מיט זייערע פאַמיליעס אַ גמר חתימה טובה לשנה טובה ומתוקה בגשמיות וברוחניות.",[["901","8","ראה קונטרס עץ החיים פרק כב: יסוד אגודתינו אינו להגדיל ולהרחיב עסק התורה הנגלית כ\"א זאת היא תכלית יסוד אגודתינו, אשר הבחורים העוסקים בתורה הנגלית יהיו יהודים (אידען) יראים ושלימים עם ה' ותורתו. וראה ספר השיחות תר\"פ­תרפ\"ז ע' 99. תרפ\"ח­תרצ\"א ס\"ע 75 ואילך. לקוטי שיחות חלק יד ע' 316 ואילך. ר\"ד י\"ט מר­חשון שנה זו. שיחת ליל שמח\"ת תש\"ט (לקמן ע' 180. ס\"ע 283 ואילך)."],["902","9","ראה מדרש משלי פי\"ב. פי\"ג. של\"ה נו, א. קפג, ב."]]],[4301620361,"<h3>ערב יוהכ\"פ — בעת כיסוי הדם — תש\"ח</h3>\nאמר<sup data-n=\"903\">1</sup> כ\"ק מו\"ח אדמו\"ר שליט\"א היום בוקר כשנכנס אליו השו\"ב עם מצות כיסוי הדם: דער טאַטע האָט געזאָגט (כנראה בעת כיסוי הדם דעיוהכ\"פ): די עבודה פון עריהכ\"פ, אויב מען דאַרף אָנרירען גבורות דאַרף מען עס צודעקען מיט חסד. צודעקען מיט עפר תיחוח ביטול. און מען דערהערט דעם כי ביום הזה יכפר<sup data-n=\"904\">2</sup>.",[["903","1","הועתק מאגרות­-קודש כ\"ק אדמו\"ר שליט\"א ח\"ב ע' רמח."],["904","2","אחרי טז, ל."]]],[4301620362,"<h3>ערב יוהכ\"פ תש\"ח אחר חצות</h3>\nכ\"ק אדמו\"ר שליט\"א ישב ליד שולחן הסמוך להחלון, לבוש ב\"סויבלענע היטל\" ותהלים פתוח.\nכאשר נכנסו לבקש ברכה, אמר:\nדער<sup data-n=\"905\">1</sup> אויבערשטער זאָל מעורר זיין מיט אַ התעוררות תשובה אמיתית מתוך פנימיות ונקודת הלב, עס זאָל זיין אַ שנת אורה שנת תורה שנת עבודה.\n* * *\nכ\"ק אדמו\"ר שליט\"א המשיך לומר תהלים. כאשר הקהל התחילו להדחף — אמר כ\"ק אדמו\"ר שליט\"א: עס איז בעסער אַז דער עולם זאָל זאָגן תהלים.",[["905","1","קטע זה הועתק מאגרות­-קודש כ\"ק אדמו\"ר שליט\"א ח\"ד ע' ד הערה 6."]]],[4301620363,"<h3>יום א' דחג הסוכות תש\"ח בסעודה</h3>\nא. אחד מהמסובים אמר: לחיים! עס זאָל זיין שמחה.\nואמר כ\"ק אדמו\"ר שליט\"א:\nדער אויבערשטער זאָל העלפן אַז מען זאָל דערהערן די שמחה. מלמעלה גיט מען דאָך נאָר גוט, כמאמר הידוע<sup data-n=\"906\">1</sup> אין רע יורד מלמעלה, דאָס ווערט דאָך ערשט אין השתלשלות, אָבער מלמעלה גיט מען דאָך נאָר גוט. זאָל דער אויבע­רשטער העלפן אַז מען זאָל דאָס טאַקע דערהערן.\nויאמר א' מהמסובים הנ\"ל: אין אַ טוב הנראה והנגלה.\nואמר כ\"ק אדמו\"ר שליט\"א:\nעס איז דאָך מסתמא ידוע, וואָס מען האָט גערעדט דעם חילוק פון טוב הנראה והנגלה און טוב האמיתי.\nב. אין מיינע קינדער יאָרן, אין מיינע וואַלגערישע יאָרן ווען איך האָב זיך גע­וואַלגערט אין החסיד ר' הענדל'ס<sup data-n=\"907\">2</sup> חדר, האָב איך אַמאָל בייגעוואוינט ווי החסיד המלמד ר' אהרן נ\"ע קוגעל מדאָקשיץ<sup data-n=\"908\">3</sup> — הי' בר דעת בחסידות והוד כ\"ק אאמו\"ר הרה\"ק האָט זיך דורכגעשריבן מיט איהם — האָט געזאָגט צו החסיד ר' הענדל'ען: שטייסט אויף אינדערפרי און זאָגסט מודה אני און דו וויינסט שוין, דו ביסט דאָך אַ קליינער בעל מוחין און אַ גרויסער בעל מדות, איז מילא, אַז עס גייט דורך אַ גאַנצער טאָג, און מ'טוט זאַכען וואָס מען דאַרף ניט טאָן און מען טוט ניט אַזעלכע זאַכען וואָס מען דאַרף יע טאָן, איז נאָכדעם ביי קרשעה\"מ וויינט זיך; אָבער באַלד אין דערפרי ביי זאָגען מודה אני, וואָס וויינסטו שוין.\nהאָט אים החסיד ר' הענדל געענט­פערט: איך וויין ניט, נאָר עס פאַר­קוועטשט מיר די האַרץ, עס איז שוין 67 יאָהר ווי ער — הנה\"ב — מאַטערט מיר, עס איז אַדורכגעגאַנגען אַ טאָג און ער האָט דאַכט זיך געהאַט וואָס ער וויל, איז אַז ער האָט זיך געלייגט שלאָפן האָב איך געמיינט אַז ער וועט שוין אייננעמען אַ פגירה; ערשט אינדערפרי, ער איז ווייטער דאָ. ער לאָזט מיר ניט זאָגען מודה אני ווי אַ איד דאַרף זאָגן, קען איך דאָס ניט פאַרנעמען און עס פאַר­קוועטשט מיר די האַרץ און עס וויינט זיך.\nוסיים כ\"ק אדמו\"ר שליט\"א: איך בין זיך יעצט מצייר דעם עוה\"ז פון ר' הענדל'ן, זיין קליינע שטיבל מיטן בעטל מיט די גאַנצע שטימונג און זיין אָרימע הויז, ומ\"מ אמר כנ\"ל.\nאַמאָל אַז מען האָט געזאָגט אַ וואָרט האָט מען דאָס פאַרנומען, מען האָט דאָס איינגענומען; אָבער היינט אַז מען זאָגט דעם אמת האָט מען פאַראיבעל — מען מיינט, אַז דאָס מיינט מען ניט אים. ער איז דאָך גאָר ניט, ניט קיין בעל מוחין, ניט קיין בעל מדות, נאָר אַזוי ווי הוד כ\"ק אאמו\"ר הרה\"ק האָט דאָס אָנגע­רופען: אַ \"צוצעלע\" — צוויי פלאָקענס אַרומגעוויקלט מיט אַ שמאַטע און אָנגעטאָן אַ אָפּגעריבענע היטעל, און מען שטעלט עס אַוועק אין גאָרטען אָפּצושרעקען די פייגלען. דער טאַטע פלעגט עס אויך רופען: ניט דערקאָכטע",[["906","1","כ\"ה בשל\"ה (קו, ב. ועוד) ובכ\"מ בדא\"ח (ראה תניא אגה\"ק סי\"א). ובב\"ר פנ\"א, ג \"אין דבר רע כו'\". וראה מדרש תהלים מזמור קמט."],["907","2","ראה אודותו לעיל ע' 17. וש\"נ."],["908","3","ראה שיחת ליל שביעי של פסח תש\"ז (לעיל ע' 113). וש\"נ."]]],[4301620364,"אַרבעס; קלייניקע קיילעכדיגע, אָבער אַז עס שטעלט זיך אין האַלדז קען מען זיך דערמיט דערווערגען.\nהוד כ\"ק אאמו\"ר הרה\"ק האָט אַמאָל געזאָגט דעם טעם פאַרוואָס ביי אַ פאַר­בריינגען מאָנט מען אין עניני עבודה, ווייל אַ חסידישער פאַרבריינגען איז אַזוי ווי אַ קעסיל, דער אש של מעלה קאָכט אויס דעם גאַנצען לא טוב.\nג. משה רבינו האָט מקבל געווען די תורה און האָט זי איבערגעגעבן אידן כמאמר משה קיבל תורה ומסרה כו'<sup data-n=\"909\">4</sup> ווייל משה איז געווען אַ טוב עין<sup data-n=\"910\">5</sup>.\nדער אַלטער רבי איז אויך געווען אַ טוב עין<sup data-n=\"911\">6</sup>, ער האָט אַ פולע אַוועק געגעבן פאַר חסידים, וואָס באמת יעדער חסיד, אפילו אַ איש פשוט דערהערט, ער ווייס ניט וואָס, נאָר ער דערהערט אַ גילוי אור.\nד. אין יאָר תרנ\"ג האָט הוד כ\"ק אאמו\"ר הרה\"ק געזאָגט — אין סוכה — צו רז\"א: געדענקסטו וואָס דער זיידע — כ\"ק אאזמו\"ר הרה\"ק צמח צדק — האָט געזאָגט, פאַרוואָס ביי חסידים זאָגט מען ניט קיין אושפיזין אין סוכה<sup data-n=\"912\">7</sup>?\nוסיפר הרז\"א\n— הרז\"א הי' בעת הסתלקות אדמו\"ר הצ\"צ בערך ז' שנים<sup data-n=\"913\">8</sup> והוד כ\"ק אאמו\"ר הרה\"ק הי' אַז בערך חמש, חמש וחצי שנה<sup data-n=\"914\">9</sup> —\nדער זיידע — כ\"ק אדמו\"ר הרה\"ק צ\"צ — האָט געזאָגט: אַז זיי זיינען דאָ איז נאָכוואָס דאַרף מען זאָגן?! אַז מען זעט זיי ניט — דאַרף מען זאָגן, זיי צו פאַר­בעטן, אָבער אַז מען זעט זיי — איז נאָכוואָס דאַרף מען זאָגן?!\nהוד כ\"ק רבינו הזקן — האָט זיי יע געזען. ער האָט מיר — היינו כ\"ק אאזמו\"ר הצ\"צ — געפרעגט: דו זעסט זיי? האָב איך געענטפערט: ניין. ואמר רבינו הזקן: אַה, אַז מען דערהערט ווי מען זעט, זעט מען. און האָט אַרויפגעלייגט די הענט אויף מיין קאָפּ — און מער האָט הוד כ\"ק אאזמו\"ר הצ\"צ ניט מסיים געווען.\nכשסיים הרז\"א לספר, אמר הוד כ\"ק אאמו\"ר הרה\"ק: דער זיידע — הוד כ\"ק אאזמו\"ר הרה\"ק צ\"צ — האָט געזען און האָט אונז מנחיל געווען<sup data-n=\"915\">10</sup>.\nמען דאַרף דאָך יעדע זאַך פאַרשטיין אין השכלה והשגה, הגם השגה איז נאָר צוליב עבודה, אָבער צוליב עבודה דאַרף מען דאָך האָבען השגה, איז דער ביאור אין דעם וואָרט זען — ראיית השכל, השגת המהות.\nה. נאָך מנחה הויבט זיך אָן דער זמן שמחת בית השואבה<sup data-n=\"916\">11</sup>. איך מיין ניט שולל זיין איצטער, נאָר עס איז חילוקי דרגות אין זמן השמחה.\nו. אַז<sup data-n=\"917\">12</sup> דער אַלטער רבי איז געווען",[["909","4","אבות פ\"א מ\"א."],["910","5","משלי כב, ט. נדרים לח, א."],["911","6","ראה גם שיחת ליל שש\"פ תש\"ו (לעיל ע' 39)."],["912","7","ע\"ד מנהגנו שאין אומרים הנוסח דהזמנת האושפיזין — ראה גם שיחת ליל ב' דחה\"ס תשמ\"ו ועוד."],["913","8","ראה לעיל ע' 14 ובהערה 3."],["914","9","נולד כ' חשון תרכ\"א."],["915","10","ראה גם שיחת ליל ו' דחה\"ס תשמ\"ו שכאשר כ\"ק מו\"ח אדמו\"ר דיבר ע\"ד האושפיזין החסידיים — הראה באצבעו ואמר: כאן יושב הבעש\"ט, כאן יושב הרב המגיד וכו'."],["916","11","ראה שיחת ליל ב' דחה\"ס תש\"ז (לעיל ע' 66)."],["917","12","הובא ונתבאר בשיחת שמחת בית השואבה תשכ\"ב."]]],[4301620365,"דעם ערשטען מאָל אין מעזריטש<sup data-n=\"918\">13</sup>, האָט ער געהערט אַ תורה פון מעזריטשער מגיד בשם הבעש\"ט, אַז פון ענן הקטרת פון יוהכ\"פ ווערט נמשך דער סכך הסוכה<sup data-n=\"919\">14</sup>, וואָס דאָס איז דער אהבתי אתכם אמר ה'<sup data-n=\"920\">15</sup>, האָלט האָבן אַ אידן.\nפון דענסטמאָל אָן איז געוואָרן אַ שינוי אין דרך פון אַלטן רבי'ן, וואָס ער האָט אָנגעהויבן מקרב זיין אנשים פשוטים. פריער איז דאָך געווען בדרך הבדלה און ריחוק פון אנשים פשוטים, אָבער פון דענסטמאָל אָן האָט ער אָנגעהויבען מקרב זיין אנשים פשוטים<sup data-n=\"921\">16</sup>.\nביים טאַטן<sup data-n=\"922\">17</sup> איז דאָ אַ ביאור אויף דעם ענין וואָס פון ענן הקטרת של יוהכ\"פ ווערט דער סכך הסוכה, בבחי' אהבתי אתכם אמר ה'.\nבכלל איז פון דעם קירוב צו אנשים פשוטים איז מען משלים וואָס עס פעלט זיי בגילוי; בהעלם האָבען זיי דאָך אַלץ, און דורך דעם אהבת ישראל און קירוב צו די אנשים פשוטים איז מען משלים וואָס עס פעלט זיי בגילוי.\nז. אין יאָר תרמ\"ח האָט מען פאַר­בראַכט אצל הרבנית הזקנה<sup data-n=\"923\">18</sup>. און הוד כ\"ק אאמו\"ר הרה\"ק האָט גערעדט בענין אהבת ישראל, און האָט אַ זאָג געטאָן: אַי! אַ איד. והי' שם ג\"כ החסיד ר' הענדל, ואמר: אַי! רבש\"ע, דו ווייסט דאָך אַ ודאי וואָס אַ איד איז און וואָס ער טוט אויף דיין וועלט, גיב זיי פרנסה בהרחבה זיי זאָלען זאָגען תהלים בשמחה.",[["918","13","ראה גם לעיל ע' 23 הערה 7. וש\"נ."],["919","14","ראה עטרת ראש שער יוהכ\"פ כט, א ואילך. לו, סע\"א ואילך. מאמרי אדמו\"ר האמצעי דברים ח\"ג ע' א'קלד ואילך. ח\"ד ע' א'רכז ואילך. אוה\"ת סוכות ע' א'תשכב ואילך. המשך וככה תרל\"ז פרק פד. סה\"מ תרנ\"ז ע' קסב ואילך. ד\"ה בסוכות תשבו תשל\"ו. תש\"מ (סה\"מ מלוקט ח\"א ע' קעז. ע' שנז). ובכ\"מ."],["920","15","מלאכי א, ב."],["921","16","ראה לעיל ע' 28. וש\"נ."],["922","17","ראה סה\"מ תרנ\"ז שם."],["923","18","הרבנית הצדקנית מרת רבקה. ראה אודותה לעיל ע' 14. וש\"נ."]]],[4301620366,"<h3>שבת חול­המועד סוכות תש\"ח בסעודה</h3>\nא. אחד מהמסובים שאל, האם צריכים להעמיד דבש על השולחן בש\"ק חול­המועד סוכות.\nואמר כ\"ק אדמו\"ר שליט\"א:\nהאָניג איז אַ גוטע זאַך, נאָר מטביל זיין בדבש פלעגט מען נאָר די ערשטע טעג און הושענא רבה, אָבער חול המועד ניט, און שבת חול המועד אויך ניט<sup data-n=\"924\">1</sup>.\nב. מן הראוי אַז מען זאָל מאַכן אַ קונטרס פון הנהגת הרב<sup data-n=\"925\">2</sup>.\nג. הוד כ\"ק אאמו\"ר הרה\"ק איז מצד בריאות געווען אַ מוגבל אין אכילה, האָט ער אויף דעם דואג געווען, ער איז אַ",[["924","1","ראה גם שיחת שבת חוה\"מ סוכות תש\"ד (ספר השיחות תש\"ד ע' 24). ספר המנהגים­מנהגי חב\"ד ע' 67. וראה לקו\"ש חי\"ד ע' 372 ובהערה 27 שם."],["925","2","להעיר שבשנה זו (בקונטרס פורים תש\"ח) התחיל כ\"ק אדמו\"ר נשיא דורנו להדפיס, \"ע\"פ פקודת כ\"ק מו\"ח אד\"ש\", לקוטי מנהגים בהוספות לקונטרסי מאמרי כ\"ק אדמו\"ר מהוריי\"צ."]]],[4301620367,"מיוחס, ער איז אַ שיינע זאַך, עס איז אַ כלי צו אמת'ע שיינקייט — דער גוף — מען פאַרשפילט זיך אין משל — עצמות דער­הערט זיך אין גשמיות.\nד. ביי הוד כ\"ק אאמו\"ר הרה\"ק איז געווען אַלץ מכוון. עס זיינען דאָ אַזעלכע וואָס ווייסן שולחן ערוך, קבלה, אָבער עס איז לא נגע; הוד כ\"ק אאמו\"ר איז געווען אַ מדוד.\nה. עס זיינען דאָ צוויי אופני הכנות, הכנת הצורה על החומר און הכנת החומר על הצורה; אין הכנת הצורה על החומר איז עכ\"פ ווערט ער ניט נתעלה, און אין הכנת החומר על הצורה — דאָ דערהערט זיך די הפלאה.\nו. שבת און יו\"ט זיינען צוויי מדריגות חלוקות הן בעצם ענינם והן במהותם.\nהוד כ\"ק אאמו\"ר הרה\"ק האָט אַמאָל גערעדט בארוכה אין אַ פאַרבריינגען בענין וואָס איז דער צירוף פון שבת­חול­המועד, ואמר על זה: אַז מען מאַכט פון חול — מועד, וואָס מועד איז ענינו יום קבוע; די נשמה איז דאָך אַראָפּ­געקומען מיט אַ שליחות, דאַרף מען מייקר זיין יעדע רגע. אַנדערע מאַכען פון מועד חול, און שבת איז מעלה דעם חול אין דעם מועד.\nז. מען דאַרף זיין ווי מען ווייס, און מען דאַרף ניט זיין ווי מען ווייס; מען ווייס דאָך דעם יע און דעם ניין. היינט איז דאָך אָבער זמן שמחתנו, בכלל דאַרף מען זיין בשמחה.\nדער רבי האָט ניט געוואָלט אַז מען זאָל וויינען. אַמאָל איז געווען חודש אלול — אַ חושך, מען האָט זיך מפנה געווען פון די געשעפטן און מען האָט געטראַכט וועגן תיקון.\nח. אַלטע חסידים פלעגן זאָגן: אַז מען זאָגט יוכ\"פ על חטא איז נאָך ניט געענדיגט, נאָך יוכ\"פ מאַכט מען אַ קנייטש; אַז עס קומט סוכות זאָגט ער צום נפש הבהמית: נו! וואָס, דו האָסט גענומען דעם גוף און הויבסט אָן צו קאָמאַנדאָווען, קריך אַריין אין סוכה און אַרבעט מיט די פיס, שמע\"צ — דער­הערט מען שמחת תורה, איז דעמאָלסט דער בראשית אַ אַנדערער.\nט. אַז די קאָפּ וואָלט פאַרשטאַנען און די האַרץ וואָלט פילען וואָס די מויל רעדט, וואָלט געווען אַנדערש.\nי. נאָר באמת אַלץ טוט זיך אָפּ, נאָר עס פעלט די דאיאנקע (הכלי שמקבלים בו את החלב).\nיא. אחד הי' אברהם<sup data-n=\"926\">3</sup>, אברהם איז געווען אַ אחד'יגער<sup data-n=\"927\">4</sup>, און ער האָט עס מנחיל געווען צו אַלע אידן.\nאַז דער אַלטער רבי איז געקומען פון מעזריטש האָט ער אָנגעהויבען מקרב זיין אנשים פשוטים, וואָס דאָס איז געווען דער נייעס ביי חסידים פון פאַר מעזריטש ביז נאָך מעזריטש.\nאַז דער רבי איז געקומען פון מעזריטש האָט ער געזאָגט קורצע תורות, אַ וואָרט — אַ תורה.\nאיינע פון די קורצע תורות איז געווען<sup data-n=\"928\">5</sup>: אחד הי' אברהם, אַז אברהם איז געווען — אחד. איז דערפון געוואָרען אַ שטורעם.\nמיין מלמד ר' ניסן<sup data-n=\"929\">6</sup> האָט מיר אין די",[["926","3","יחזקאל לג, כד."],["927","4","ראה גם ספר השיחות תש\"ד ע' 72 (נת' באגרות­-קודש כ\"ק אדמו\"ר שליט\"א ח\"ג ע' רמו). וראה ספר השיחות תש\"ג ס\"ע 46."],["928","5","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."],["929","6","ראה אודותו לעיל ע' 41. וש\"נ."]]],[4301620368,"קינדער יאָהרען מבאר געווען וואָס דער טאַטע האָט גערעדט ביי אַ פאַרבריינגען:\nאחד הי' אברהם — אַז אפילו אין מצרים איז געווען קענטיג גייענדיג אין גאַס דער אחד הי' אברהם, עס איז געווען אַ שינוי אין אויר פון פאַרן גיין ביז נאָכ'ן גיין, און דאָס האָט אברהם מנחיל געווען לדורות.\nיב. דרכי החסידות איז אַ נחלה בלי מצרים."],[4301620369,"<h3>ליל הושענא רבה תש\"ח</h3>\nא. הוד כ\"ק אאמו\"ר הרה\"ק פלעגט אַ זייגער זעקס אין אָווענד אַריינגיין אין סוכה און זאָגן משנה­תורה פאַר זיך, תהלים פלעגט ער זאָגן מיט דעם עולם.\nהוד כ\"ק אאמו\"ר הרה\"ק פלעגט זאָגען נאָך יעדען ספר תהלים דעם \"יהי רצון\" פאַר הושענא רבה, און דעם \"יהי רצון\" וואָס נאָך צאת הלבנה, אָבער ניט דעם יום טוב \"יהי רצון\" וואָס איז געדרוקט אין די תהלים'ס.\nב. שאלה: מאחר ואמירת תהלים בליובאַוויטש נמשך רק לערך שעה ורבע<sup data-n=\"930\">1</sup>, האם היו בליל הושענא רבה עוד ענינים מיוחדים?\nתשובה: הכנות צו דעם שמיני עצרת'דיגען מאמר.\nלייענען די פדיונות בליל הושענא רבה נאָך אַמאָל — איז נאָך אַ ענין.\nג. הוד כ\"ק אאמו\"ר הרה\"ק פלעגט אויף זיין אַ גאַנצע נאַכט הושענא רבה<sup data-n=\"931\">2</sup>, דערנאָך גיין אין וואַסער; קומענדיג פון וואַסער, פלעגט ער טרינקען אַ גלאָז מילך און זיך צולייגען, און דאַוונען אַזייגער 9.\nד. שאלה: אם כן הטבילה היא לא בתור הכנה לתפלה, רק שייכת לעניני ליל הושענא רבה?\nתשובה: אַזוי איז דאָס<sup data-n=\"932\">3</sup>.\nה. זיין אויף שמיני עצרת ביינאַכט געדענק איך מער ניט ווי איין מאָל, בשנת תרמ\"ח או תרמ\"ט.\nו. הושענא רבה איז דער מנהג ליובאַוויטש, אַז מען נעמט אַרויס צו אמירת הושענות אַלע ספרי תורות.\nז. ווינשען הו\"ר גמח\"ט אַ פתקא טבא<sup data-n=\"933\">4</sup> וכיו\"ב — האָט מען זיך ניט נוהג געווען אין ליובאַוויטש<sup data-n=\"934\">5</sup>.",[["930","1","ראה ספר השיחות תרפ\"ח­תרצ\"א ע' 143: \"בליוב' הי' מסיימין תילים במשך 54 שעה\"."],["931","2","ראה גם \"היום יום\" כא ניסן. ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 295. תש\"ב ע' 100."],["932","3","בהנחה אחרת: כן הדבר."],["933","4","ראה זח\"ג לב, א. פרי עץ חיים שער הלולב פ\"ד. שיחת ליל הושענא רבה תשמ\"ו."],["934","5","סעיף זה הועתק מגוכי\"ק כ\"ק אדמו\"ר נשיא דורנו."]]],[4301620370,"<h3>יום שמע\"צ תש\"ח בסעודה</h3>\nא. אַז מען האָט איבערגעגעבן דעם אַלטן רבי'ן צו שרייבן דעם שו\"ע און עס איז געקומען צום דין פון בני ארץ ישראל וועגען יו\"ט שני של גליות<sup data-n=\"935\">1</sup> איז ער געווען אין אַ פאַרלעגענהייט, ווי אַזוי נעמט מען צו פון בני ארץ ישראל דעם יו\"ט שני וכו'.\nיו\"ט שני של גליות איז דער פירוש, אַז דאָס איז אַ יו\"ט וואָס מען מאַכט דעם גלות אויס גלות — מאַכן דעם חוץ לארץ פאַר \"ארץ\"<sup data-n=\"936\">2</sup>, עס זאָל זיין די המשכה למטה כמו למעלה.\nאון דער גאַנצער פּעקיל ליגט אויף אונזערע פּלייצעס.. . <sup data-n=\"937\">3</sup>.\nב. חסידות לערנט, אַז פון די נידעריקערע מדריגה קומט מען צו די העכערע מדריגה, און אַז מען שטייט ביי די העכערע מדריגה דאַרף מען וויסן אַז מען איז צוגעקומען צו די העכערע מדריגה דורך די נידעריקע מדריגה. וואָס איז דער שכר דערפאַר? אַז מען דערהערט די הפלאה פון די מדריגה התחתונה.\nעס איז פאַראַן אַ עבודה קטנה און אַ עבודה גדולה רמה ונשאה, מען קען ניט צוקומען צו די מדריגה גדולה רמה ונשאה סיידן דורך די עבודה קטנה; אַז מען שטייט אין די עבודה רמה ונשאה און מען ווייס אַז דאָס איז געקומען פון די עבודה קטנה, דאַן דערהערט מען די הפלאה פון די עבודה קטנה.\nג. בערע אברהם'קעס<sup data-n=\"938\">4</sup> און טובי'. . . זיינען אַמאָל אַריינגעקומען צו דעם טאַטן און געזאָגט: גוט יום טוב, היינט איז דאָך שמחת תורה. האָט דער טאַטע זיי געענטפערט: איך האַלט נאָך ביי די עבודה פון שמיני עצרת.\nד. שמיני עצרת מאַכט אַ רושם אין נפש, און נשמה מאַכט אַ רושם אין שמיני עצרת.\nהנהגה:\nכ\"ק אדמו\"ר שליט\"א צוה להתפלל שחרית ביום שמיני עצרת קודם חצות היום.",[["935","1","או\"ח סימן תצו."],["936","2","להעיר מפתגם אדמו\"ר הצ\"צ לאחד החסידים: \"מאַך דאָ ארץ ישראל\" — אגרות­-קודש ח\"א ע' תפה ואילך. חי\"א ע' סא. שם ע' סו. חי\"ד ע' תלו. לקו\"ש ח\"ב ע' 621. ספר השיחות תנש\"א ח\"ב ע' 703 ואילך. ובכ\"מ."],["937","3","ברשימת ההנחה: \"מפני הרעש שהי' ברחוב לא זכינו לשמוע הדברים על בירורם וצריכים לשאול ולתקן מה שחסר. — המעתיק\"."],["938","4","קאַצענעלענבויגן. — נזכר בספר השיחות תש\"ד ע' 27. קונטרס בר מצוה תרנ\"ג (קה\"ת, תש\"ס) ע' יח."]]],[4301620371,"<h3>ליל שמח\"ת קודם הקפות תש\"ח</h3>\nא. דער \"תכין לבם\"<sup data-n=\"939\">1</sup> איז דאָ, דער אויבערשטער זאָל העלפן, אַז עס זאָל אַראָפּקומען אין אַ פנימיות.\nשמיני עצרת און שמח\"ת זיינען צוויי דרגות חלוקות, אָבער ביידע אין המשכה פנימיות.\nב. איך וויל אייך איבערגעבן אַ גערוס פון זעכציג יאָר צוריק. אין יאָר תרמ\"ח האָט הוד כ\"ק אאמו\"ר הרה\"ק געזאָגט שמח\"ת: וואָס פרייט זיך דער אויבער­שטער שמח\"ת; בשלמא אידן פרייען זיך וואָס זיי האָבן מקבל געווען די תורה, אָבער למעלה, שטייט דאָך אַז אלפים שנה קדמה תורה לעולם<sup data-n=\"940\">2</sup>, איז מיט וואָס פרייט זיך דער אויבערשטער שמח\"ת?\nאון הוד כ\"ק אאמו\"ר הרה\"ק האָט געענטפערט:\nדער אויבערשטער פרייט זיך מיט דעם, וואָס אידן זיינען מקבל די תורה בדעת.\nדער אויבערשטער זאָגט: איך גיב זיך אַוועק אין תורה צו דעם וואָס גיט זיך אַוועק צו תורה.\nרש\"י איז מפרש התורה, אין רש\"י האָט מען געגעבען דעם כח, אַוועק­צוגעבען די עצמיות פון תורה צו די עצמיות פון אַ אידן.\nמען דאַרף לערנען אַלע טאָג אַ פרשה חומש עם פרש\"י, ווייל רש\"י איז ממשיך די עצמיות פון תורה אין עצמיות פון אידן.\nג. הוד כ\"ק אאמו\"ר הרה\"ק האָט געזאָגט אַ כלל, אַז ווען דער זיידע<sup data-n=\"941\">3</sup> זאָגט: \"עס איז אַ דבר ידוע\", מיינט דאָס, ווי עס איז בהרגש נשמתו אין ג\"ע העליון.\nדער רבי האָט געזאָגט, אַז אַ איד דאַרף זאָגן שמחת תורה לחיים<sup data-n=\"942\">4</sup>.\nאויף בני חיי מזוני האָט זיך דער אויבערשטער משעבד געווען, וואָס מיר בעטן איז אַז עס זאָל זיין רויחא.\nוואס מיינט רויחא — דאָס איז שוין מיין אייגענער ביאור — אַז די גשמיות זאָל דערהערן די כוונה פנימיות וואָס איז לכתחלה געשטאַנען אין יש הגשמי.\nאין רויחא איז פאַראַן חילוקי מדרי­גות, רויחא פון אַ בעל עסק פון אַ בן תורה און פון אַ חסיד. דער רויחא פון אַ חסיד מיינט, אַז ער שטעלט זיך דאַוונען טראַכט ער גאָר ניט וועגן דעם שטיקל ברויט, וואָס ער דאַרף עסן נאָכן דאַוונען אַ גאַנצן טאָג, ע\"ד ווי הרה\"צ ר' זושא פלעגט זאָגן: \"זושא דאַרף עסן\".\nד. מיט 58 יאָר צוריק האָט הוד כ\"ק אאמו\"ר מבאר געווען בעת אַ פאַרבריינ­גען דעם ענין: לוו עלי ואני פורע<sup data-n=\"943\">5</sup>.\nשבת איז די עבודה פון יחודא עילאה — הוד כ\"ק אאמו\"ר הרה\"ק פלעגט אויף יחודא עילאה זאָגען: עפּעס גאָר אַנדערש —\nא חסיד אַז עס קומט שבת, ווייס ער אַז היינט איז שבת, שבת דאַרף מען גיין",[["939","1","תהלים י, יז."],["940","2","ראה מדרש תהלים צ, ד. ב\"ר פ\"ח, ב. תנחומא וישב ד וש\"נ. זח\"ב מט, א."],["941","3","ברשימת ההנחה כותב המניח: \"כפי הנראה הכוונה על כ\"ק אדמו\"ר הצ\"צ. המעתיק\"."],["942","4","ראה גם ספר השיחות תר\"פ­תרפ\"ז ע' 28. תש\"ב ע' 13."],["943","5","ביצה טו, ב."]]],[4301620372,"אינדערפרי אין וואַסער, מעביר זיין די סדרה<sup data-n=\"944\">6</sup>, זאָגן תהלים, נאָכן דאַוונען מאַכען קידוש, עסען. ער ווייס אַז היינט איז שבת, ער איז מסולק פון אַלע דאגות, דאגת הפרנסה, דאגת ב\"ב וכו'; אַז ער שטעלט זיך דאַוונען איז ער פאַרנומען נאָר מיט'ן דאַוונען און איז מסלק פון זיך אַלע דאגות.\nדאָס איז דער לוו עלי, מלשון באַ­העפטן זיך, אַז מען בעהעפט זיך מיט דעם עלי איז דאַן ואני פורע, פורע מלשון אָפּדעקן, עפענען. ואני פורע איז דער פירוש אַז השי\"ת עפענט אויף די גשמיות, אַז עס זאָל זיין אַ כלי צו עצמות. וואָס דאָס מיינט ברויחא — אַז עס איז ניט שולט קיין עין לא טובה, אַז מען גיט איהם אַ מתנה איז דאָס בהרחבה ובשלימות.\nה. אחד מהתמימים שבא לא כבר ממדינה שמעבר לים (אפריקה הדרומית) בשליחות כ\"ק אדמו\"ר שליט\"א, אמר לחיים. וענה לו כ\"ק אדמו\"ר שליט\"א: לחיים ולברכה.\nדו ביזט אַ מהיר, גיסט אַ שמיר מיט די ליפן און יוצא. מען דאַרף מאַכן אַ תוך אין מקבל, אַז ער זאָל נתעורר ווערן מיט אַ תמידיות.\nהחסיד ר' בערע וואָלף<sup data-n=\"945\">7</sup> פלעגט זאָגן: שאוני והטילני<sup data-n=\"946\">8</sup>, טראָג מיר וכו'.\nאיר ווייסט ניט ווער עס גייט פאַר אייך. דעם וועלטישן טעות, צו מיינען אַז איר זייט \"מאַכערס\" — אַז איר אַליין טוט דאָס אויף, דאָס האָט איר ניט; אָבער איר ווייסט ניט ווער עס גייט פאַר אייך.\nאַ ודאי דאַרף מען זיין צופרידן וויפל מען טוט אויף. אַז איינער פוילט זיך און לייגט אָפּ דעם דאַוונען אויף מאָרגן און די תפילין אויף מאָרגן און מען פועל'ט אויף אים ער זאָל דאַוונען היינט און לייגן תפלין היינט, דאַרף מען זיין זייער צופרידן, אַיי מנחה און מעריב, איז נאָך דערווייל ניטאָ, נו! מען דאַרף אָבער מקרב זיין, און נעמען יענעמס גוטע זייט און דאָס מגביר זיין; עס איז אָפּגעטויט אַ אבר — ער איז ניט ווי מ'דאַרף, דאַרף דאָס זיין ביי זיך אַ ווייטאָג אין האַרצן, אָבער פאַר יענעם דאַרף מען ווייזען אַ פנים צהובות און אים מקרב זיין.\nאַז מען זעט אַז די דברי התעוררות וואָס מען זאָגט אים פועל'ט ניט, דאַרף מען זיך גוט אויספּלאָנ'חענען (אויס­וויינען) און אונטערפאַסטען אויך, און זאָגן אַ שטאַרקן פעטן \"על חטא\", און תולה זיין די אשמה אין זיך, ווייל עס דערנעמט ניט יענעמס רחמנות. אַז מען זעט איינעם אַ מחוסר לחם, אָדער ער האָט אַ צער פון ב\"ב ח\"ו, דעמאָלסט ווערט מען נתעורר מיט רחמנות אויף יענעם, אָבער אַז מען זעט יענעמס חסרון אין רוחניות דערנעמט דאָס ניט. און דער ניט דערנעמען מאַכט אַ סתימה אין כלי המקבל.\nמען דאַרף ניט זיין קיין מהיר. דער אויבערשטער זאָל העלפן, אַז די \"זרעא\" וואָס דו האָסט פאַרזייט בדרך אגב, זאָל זיין חייא וקיימא.\nו. א' מאנ\"ש מפליטי רוסיא אמר לחיים לכ\"ק אדמו\"ר שליט\"א. ואמר לו כ\"ק אדמו\"ר שליט\"א:\nדו ווייסט מסתמא נאָך וואָס דו ביסט געקומען אַהער. קיין דאגת הפרנסה",[["944","6","ראה שו\"ע אדה\"ז או\"ח סרפ\"ה ס\"ה ואילך."],["945","7","הרה\"ח ר' דוב זאב קאָזעווניקאָוו. רב ביעקאַטרינאָסלאַוו. — ראה אודותו: ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 231. וש\"נ."],["946","8","יונה א, יב."]]],[4301620373,"דאַרף מען ניט האָבן, דער אויבערשטער איז אַ זן ומפרנס לכל בריותיו, דאַרף מען קיין דאגת הפרנסה און דאגת ב\"ב ניט האָבן.\nוענה הנ\"ל: דער אויבערשטער האָט מיר שוין מזמין געווען אַ פרנסה.\nואמר כ\"ק אדמו\"ר שליט\"א: איך ווייס. איך ווייס פון יעדערן, אידן בכלל, אנ\"ש בפרט, און חסידים וואָס מען האָפט מיט זיי עפּעס אויפטאָן בפרטי פרטיות, איז מיר נוגע אין אַ פנימיות דפנימיות.\nדאגת הפרנסה דאַרף ניט זיין, אָבער מען דאַרף וויסן נאָך וואָס איז מען גע­קומען אַהער, יעדערער האָט אַ שליחות אין עלמא דין.\nז. איך וואָלט זיך ווינשען, אַז אַלע תמימים זאָלן האָבען בני חיי מזונא רוי­חא בתכלית ההפלגה, נאָר זיין מלמדים. זיי זאָלן האָבן ברויט מיט'ן פולן מויל, ברויט מיט פּוטער, און פלייש מיט קאָמ­פּאָט, מיט אייגענע הייזער און זיידענע זופּיצעס אויף שבת<sup data-n=\"947\">9</sup>, אָבער די מלאכה זאָל זיין מלמדות.\nאַה! וואָס פאַר אַ עושר דער אויבער­שטער וואָלט געווען.\nעס איז דאָ אַ כתה ביי אידען וואָס האַלטן, אַז זיי האָבן אַ חוש אין תורה — אפשר, תורה לשמה זיכער ניט. אָבער לימוד התורה, זיין אַ מלמד און אויס­לערנען יענעם ווי אַזוי צו לערנען דאָס איז גאָר אַ אַנדער זאַך.\nח. אידן בכלל, חסידים בפרט און תמימים בפרטי פרטיות, ווייסן ניט וואָס פאַר אַ כחות זיי פאַרמאָגען און זיי ניצן זיי ניט אויס.\nמען קלאָגט זיך. דאָס וואָס מען קלאָגט זיך אויף גשמיות זיינען זיי גע­רעכט, זיי דאַרפן טאַקע האָבן בני חיי ומזוני רויחא און דער אויבערשטער זאָל זיי העלפן; אָבער דאָס וואָס מען קלאָגט זיך אויף רוחניות איז אַ עוולה.\nצייטנווייז טראַכט איך, אַז דאָס איז דערפאַר ווייל מען פוילט זיך, מען פוילט זיך אויספּאַקן דעם פּעקל, מען מיינט אַז דאָרט געפינט זיך גאָר ניט, ע\"ד אַן אָרימאַן וויל ניט עפענען זיין פּעקל; אַ עושר עפענט זיין פּעקל, ווייל ער ווייס ער וועט דאָרטן עפּעס געפינען, אָבער אַן אָרימאַן ווייס אַז ער וועט אין זיין פּעקל גאָר ניט געפינען, סיידן אַ טרוקן שטיקל ברויט, אַ דאַרע סקארינקע אָדער אַ פאַרשימעלטע שטיקל גאמעלקע.\nזיי ווייסן ניט די אייגענע כחות און נוצען זיי ניט אויס, אַז מען וואָלט געטאָן וואָלט מען געזען אַז אחד יהי' לרבבה<sup data-n=\"948\">10</sup>.\nט. מען האָט אַ טעות, אַז השכלה איז אַ עיקר; ניין, דער עיקר איז עבודה בפועל, נאָר אַזוי איז דער סדר התהוות, חב\"ד, חג\"ת, נה\"י, דער עיקר איז די פיסלעך אויף וואָס צו שטיין.\nמען דאַרף לערנען שו\"ע או\"ח, צו וויסען שמירת התורה והמצוות בפועל, מען בעדאַרף אויסמושטירען דעם גוף עפ\"י שו\"ע.\nאיך האָב שוין אַמאָל דערציילט<sup data-n=\"949\">11</sup>, אַז",[["947","9","ע\"ד לבישת בגדי משי בשבת ויו\"ט — ראה המשך תער\"ב ח\"ב ס\"ע תתעב ואילך. תרס\"ב ע' רלא בשוה\"ג (וסיום הענין שם ס\"ע שמז). ד\"ה זה יתנו תש\"כ (סה\"מ תש\"כ ע' 87). ר\"ד יום ה', כד תשרי תשי\"א (תורת מנחם התוועדויות תשי\"א ח\"א ע' 53. וש\"נ). שיחת פורים תשט\"ו."],["948","10","ראה לקמן ע' 178."],["949","11","ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 98. קיץ ה'ש\"ת ע' 82. \"היום יום\" כ שבט."]]],[4301620374,"הרה\"ג החסיד. . . האָט אַמאָל געפרעגט הוד כ\"ק אאמו\"ר הרה\"ק, פאַרוואָס ער וואַשט זיך נט\"י לסעודה דריי מאָל אויף יעדע האַנט, איז דאָס נאָר אַ מנהג?\nהאָט אים הוד כ\"ק אאמו\"ר הרה\"ק געענטפערט: דער מקור הדין געדענק איך ניט, נאָר אַז איך טו אַזוי בין איך זיכער אַז דאָס איז אַ הלכה, ווייל ווען איך האָב — פאַר מיין בר מצוה — גע­לערנט שו\"ע או\"ח האָב איך אויס­מושטירט מיין גוף אַז יעדער אבר זאָל טאָן דאָס וואָס איז נוגע צו אים עפ\"י הלכה<sup data-n=\"950\">12</sup>.\nנאָכדעם האָט אים הוד כ\"ק אאמו\"ר הרה\"ק געוויזן אַ ב\"י אין טור יו\"ד הלכות מליחה<sup data-n=\"951\">13</sup>, וועגען הדחת הבשר ג' פעמים אחר מליחה וכן לנטילת ידים.\nי. הרב\"ג<sup data-n=\"952\">14</sup> אמר לחיים והזכיר את אנ\"ש והתמימים שבפּאַריז, ואמר כ\"ק אד\"ש: עס איז קבוע בלב [והראה בידו הקדושה על לבו].\nאח\"כ נתן כוס משקה לרב\"ג ואמר: גיב זיי איבער אַ פנימיות'דיגן גערוס און אַ פנימיות'דיקע ברכה.\nיא. מען האָט אַמאָל גערעדט, אַז דער הפרש פון אַ עצמי און אַ פנימי איז, וואָס אַ עצמי איז מרחיב די כלי המקבל און אַ פנימי איז מכניס אור אין מקבל.\nהוד כ\"ק אאמו\"ר הרה\"ק, מיט זיין פאַרבריינגען שמח\"ת פאַר הקפות, האָט געעפנט ביי יעדערן די פנימיות דפני­מיות פון זיינע עצמיות; נאָר מען האָט דאָס ניט געדאַרפט פאַרשלאָפן<sup data-n=\"953\">15</sup>.\nהערט תמימים! אָט דאָס וואָס מען גיט אייך יעצט, זאָלט איר דאָס ניט פאַרשלאָפן און עס זאָל ניט זיין אין דעם קיין סתימה, מיט אַ טרער אָדער אַ טאַנץ יעצט קען מען אַ פולע נעמען.\nיב. שמח\"ת איז ווייניג גערעדט, גוט געטראַכט.\nיג. אין קדושה אין גורעין אלא מוסיפין.\nיד. לחיים, אָט דאָס וואָס דער אויבער­שטער גיט אידן זאָל זיי דאָס אָנקומען.\nדער אויבערשטער גיט אידן אַ סאַך, דער אויבערשטער זאָל העלפן אַז עס זאָלן ניט זיין קיין מניעות ועיכובים, עס גייט דאָך פון זייער ווייט און עס זיינען דאָ אויפ'ן וועג אַ סאַך פאראגעס, אָבער אַז עס גייט מיט אַ תוקף ברעכט דאָס דורך אַלץ.",[["950","12","ראה ספר השיחות תרצ\"ו­חורף ה'ש\"ת שם. וש\"נ."],["951","13","סימן סט קרוב לתחילתו ד\"ה ואחר ששהה — מהגהות אשרי חולין קיג, א: \"דמדיחין אותו ג' פעמים. . וכה\"ג אומר ריב\"א גבי נטילת ידים\". הובא ב\"היום יום\" שם."],["952","14","הרב בנימין אליהו גאָראָדעצקי, בא כח רבינו באירופה."],["953","15","בנו\"א: אַז מען איז געווען ביים טאַטן שמע\"צ האָט מען געזען אַ גילוי עצמי. נאָכהער האָט מען געדאַרפט טאָן אויף צו ניט פאַרלירן דאָס."]]],[4301620375,"<h3>שמח\"ת תש\"ח בסעודת היום</h3>\nא. מיר זיינען ביידע בטוחים: איך בין אַ בטוח אַז איך וויל אייך געבען און איר זייט אַ בטוח אַז איר וועט נעמען, נאָר דער עיכוב איז מצד הזמן, די הגבלה פון זמן; דער זמן פון שמח\"ת איז זייער יקר און מען קען אים ניט אויסציען. איך אייל זיך, ווייל ביני לבין עצמי האָב איך נאָך ענינים וואָס איך דאַרף משלים זיין, וואָס איז שייך צו דעם יו\"ט שמח\"ת; וועל איך ריידען בקצרה.\nב. חסידים דאַרפען קובע זיין זמן אויף אריכות התפלה, איינמאָל אין 8 טעג, אין צען טעג, שבת און בכלל אין אַ עת המוכשר.\nמען ווערט דאָך פאַרפּראָסטעט, מצד העדר העבודה און העדר ההרגש פילט מען מעלת עצמו און מען זעט חסרון הזולת. דאַרפען דאַרף זיין, אַז מען זאָל זען מעלות הזולת און חסרון עצמו. אמת, מען דאַרף מעלות עצמו אויך ניט פאַרלייקענען, אָבער דאָ דאַרף שוין זיין אַ מדידה אויף וויפיל דער קלוגינקער האָט ניט קיין יד אין דעם.\nג. החסידים הגבירים ר' ישעי' ברלין<sup data-n=\"954\">1</sup> און ר' יעקב הורוויץ<sup data-n=\"955\">2</sup> האָבען אַמאָל געמאָנט ביי הוד כ\"ק אאמו\"ר הרה\"ק פאַרוואָס ער איז מיר מסכן אין שליחות'ן פון עניני הכלל מיט אַזויפיל מסירת נפש.\nדי מעשה איז אַזוי געווען<sup data-n=\"956\">3</sup>:\nהוד כ\"ק אאמו\"ר הרה\"ק האָט מיר געשיקט אין אַ שליחות פון עסקנות הכלל אין פּעטערבורג. דאָרט האָב איך זיך געדאַרפט טרעפן מיט אַ מיניסטער, אַ רשע מרושע, ער איז געווען אַ רבי פון סטאָליפען הצורר.\nדער מיניסטער מיט וועלכען איך האָב זיך געדאַרפט זען, האָט געוואוינט הינטער פּעטערבורג אין דעם געגענד וואו עס האָבן געוואוינט די קניאזען (פירשטען), יעדער האָט זיך דאָרט גע­האַט זיין פּאַלאַץ מיט אַ גאָרטן און אַ סאַך הינט.\nגראָד איז אַזוי אויסגעקומען, אַז איך האָב געקענט זען דעם מיניסטער נאָר פרייטאָג צונאַכט. בין איך פרייטאָג ביי­טאָג דאָרט צוגעפאָרן, קיין גאַסטיניצע (האָטעל) איז דאָרט ניט געווען, בין איך אַריין צו אַ טראקטאר און געגעבן דעם חאזאיען (בעל הבית) אַ פיינע מטבע, אים געגעבן באַהאַלטן מיין טלית, ווייל איך האָב געדענקט אַז איך וועל דאָרטן דאַרפן בלייבן דעם גאַנצן שבת. איך האָב דערציילט דעם גוי וואוהין איך דאַרף גיין ביינאַכט, און אים געבעטן ער זאָל מיר דאָרט צופירן און דערנאָך צוריק אָפּפירן, מחמת אין פּעטערבורג זיינען די וועטערן ניט קביעות'דיג, אָט רעגענט, אָט",[["954","1","מריגא. חתן אחות כ\"ק אדמו\"ר מהר\"ש (הרבנית ראדע פריידע). נפטר בקיץ תרס\"ח. ראה אודותו: אגרות­-קודש אדמו\"ר מהורש\"ב ח\"ב ע' תשא­תשב. ובהנסמן במפתח שמות אנשים לאגרות­-קודש שם ח\"ה. נזכר בספר השיחות תש\"ב ע' 98. ס\"ע 117. תש\"ה ע' 24. ע' 28. ע' 30 ואילך. ע' 41. ועוד."],["955","2","מריגא. נזכר בספר השיחות תש\"ב ע' 97 ואילך. תש\"ד ע' 18. תש\"ה ע' 24. אגרות­-קודש ח\"ח ס\"ע קי ואילך. ועוד."],["956","3","ראה ר\"ד כ\"א סיון תש\"ו (לעיל ע' 51). וראה שיחת כ\"ד טבת תשי\"א (תורת מנחם התוועדויות ח\"ב ע' 174 ואילך). יו\"ד שבט תש\"כ (לקו\"ש ח\"ו ע' 287 ואילך). י\"ב תמוז תשמ\"ה (התוועדויות תשמ\"ה ח\"ד ע' 2457 ואילך)."]]],[4301620376,"שנייט מיט אַ ווינט און גליטשיג. איך האָב אים אויך געבעטען אַז מוצאי שבת זאָל ער מיר צוריק אָפּפירען אין שטאָט צו מיין גאסטיניצע.\nדערזעענדיק די מטבע, אַ 25'ער איז דער חאזאיען — דער גוי — געוואָרן איבערראַשט און געטאָן אַלץ וואָס איך האָב אים געבעטן.\nפרייטאָג צו נאַכט בין איך אַוועקגע­גאָנגען צו דעם מיניסטער. אַריינגייענ­דיג צו אים אין צימער איז ער מיר גלייך בעפאַלן מיט'ן שימפ וואָרט \"קאנאליע\", ווי אַזוי האָסט דו זיך איינגעשטעלט צו מיר צוקומען יעצט, דו ביסט דאָך אַ בן יחיד ביי דיין טאַטן — ער האָט שוין וועגן מיר אַלץ געוואוסט — ווי אַזוי האָט ער דיר געלאָזן גיין צו מיר ביינאַכט, מיינע הינט האָבן דאָך דיר געקענט צורייסן און אויפפרעסן.\nהאב איך אים געענטפערט: אַ איד האָט ניט קיין מורא פאַר אַ הונט, אַ הונט האָט מורא פאַר אַ איד.\nאָט די געשיכטע האָט גורם געווען, וואָס ר' ישעי' ברלין און ר' יעקב הורוויץ האָבען נאָכדעם געמאָנט ביים טאַטן, ווי אַזוי שיקט ער מיר אויף אַזעלכע שליחות'ן, עס איז צופיל מסירת נפש.\nהוד כ\"ק אאמו\"ר הרה\"ק האָט זיי געענטפערט:\n\"די כוונה פנימית דאַרף מען דאָך דורכפירען, — ניע פאציאם<sup data-n=\"957\">4</sup>, אויף וואָס דען איז געווען ירידת הנשמה למטה, איז דאָך נאָר אויף מסירת נפש.\nאיך בין בטוח אַז ער וועט מאריך ימים זיין\".\nאַז די נשמה איז מאיר בגוף, איז דער גוף בדרך ממילא בטל צו דעם אור הנשמה.\nאיך דערצייל אייך דאָס בהמשך צו דעם וואָס מען האָט נעכטן גערעדט<sup data-n=\"958\">5</sup>, אַז אחד יהי' לרבבה, איינער קען אויפהויבן אַ גאַנצע מדינה.\nד. איך וויל אייך איבערגעבן אַ ענין וואָס איז ביי מיר שוין לאַנג כמוס באוצרותי, מען קען ניט ריידען באריכות ווייל ווי געזאָגט איך אייל זיך, אָבער איך קען דעם ענין פון אייך ניט מעלים זיין<sup data-n=\"959\">6</sup>.\nהוד כ\"ק אאמו\"ר הרה\"ק האָט געזאָגט אין אַ פאַרבריינגען, אַז מוצאי יו\"ט שמח\"ת, דאַרף מען אָפּשניידן די שטריקלעך.\nדעם ענין דאַרף מען דערהערן אין השגה, הבנה און הסברה, נאָר יעצט ריידן מיר בקצרה.\nאין חודש אלול און תשרי נעמט דאָך יעדער איד, לא מיבעי עצם הנשמה נעמט דאָך אַ ודאי, נאָר דאָס איז דאָך וואָס עצמי נעמט, נאָר אפילו כחות הגלויים נעמען אויך אַ פולע.\nאיז אַז עס קומט מוצאי יו\"ט דאַרף מען אָפּשניידן די שטריקלעך פון די טאָרבע וואָס מען האָט איינגעפּאַקט במשך חודש אלול און תשרי.\nדי ערשטע קריאת שמע שעל המטה מוצאי יו\"ט דאַרף זיין מיט אַ געעפענטע טאָרבע.\nאיר קענט זיך גאָר ניט פאָרשטעלן דעם קורת רוח למעלה פון אַ שמע",[["957","4","{6} אין לזה ערך."],["958","5","לעיל ע' 175."],["959","6","בהנחה אחרת נוסף: א[ון] איך האָף אַז דער [וואָרט וועט זיך איבערק]ייקלען אין אַ סאַך ערטער."]]],[4301620377,"ישראל וואָס עס זאָגט אַ פשוטער איד אין קריאת שמע שעל המטה, בפרט פון דעם ביי וועמען עס דערהערט זיך דער שמע ישראל אין השכלה אין הבנה און אין אַ החלט אויף אַ בפועל טוב.\nווי דער מאמר הידוע פון אַ חסיד, וואָס פלעגט זאָגען נאָך קריאת שמע שעל המטה: \"אַה! מאָרגן דאַרף מען אויפשטיין גאָר אַ אַנדערער\"<sup data-n=\"960\">7</sup>; די אומ­צופרידענהייט מיט דעם היינט, און די קבלה אַז מאָרגן דאַרף מען זיין בעסער.\nה. איך בין מחוייב אַ קרבן תודה ושלמים אויף דעם חסד ה' וואָס ער האָט געטאָן מיט אונז.\nדער אויבערשטער ווייס — איך וויל ניט זאָגן דעם לשון המורגל ביי בני אדם, וואָס מאַכען דעם אויבערשטען פאַר אַ עדות — ווי צובראָכן איך בין געווען פאַרענדיק אַהער אין אַמעריקע, איך בין געווען כחרס הנשבר; איך האָב גע­וואוסט אַז דאָ זיינען דאָ אידען, חסידים, תמימים, אָבער איך האָב זיך געשראָקען פאַר דעם רעש און הו­האַ פון אַמעריקא.\nווען איך בין נאָך געווען אין ריגאַ האָב איך געציילט די שעות וואָס איך בלייב נאָך דאָרט. אַז מיר זיינען געפאָרן אויפ'ן שיף צוועלף­דרייצן טעג<sup data-n=\"961\">8</sup> האָב איך געוואָלט, אַז מען זאָל נאָך לענגער פאָרען. קומענדיג אַהער בין איך געווען אַזוי צובראָכן, אַז איך האָב ניט געוואוסט וואָס עס טוט זיך מיט מיר.\nווען איך האָב אָנגעהויבן רעדן וועגען מייסד זיין דאָ אַ ישיבה תומכי-תמימים, האָט מען מיר אָנגעקוקט וואָס איך רייד און האָבן געזאָגט אַז דאָ אין אַמעריקא איז דאָס אוממעגליך<sup data-n=\"962\">9</sup>.\nעס זיינען אַריינגעקומען צו מיר תלמידים פון אַנדערע ישיבות, אָבער אָן לייב און לעבן, אַן באָרד און פאות, אָן ציצית; יע, זיי האָבן אפשר די ציצית אין די הויזן, אָבער...\nב\"ה, אַז עס האָט זיך אויפגעטאָן וואָס איך האָב אַליין ניט משער געווען, עס איז למעלה מדרך השתלשלות; הגם עפ\"י סדר והדרגה אַז מען טוט העלפט דער אויבערשטער, אָבער אַזאַ הפלאה איז נאָר למעלה מסדר השתלשלות.\nמען האָט ב\"ה געפענט פענסטער אין דעם טומאן — נעפּעל<sup data-n=\"963\">10</sup>. אָבער אַ ציור פון אַ ליובאַוויטשער — רוסישער — תמים האָבען זיי דאָ נאָך ניט געזען.\nדער אויבערשטער זאָל שיקן משיח'ן בקרוב און מיר זאָלן אַלע גיין בקרוב אין ארץ ישראל, אָבער דערווייל האָבען זיי דאָרט — הכוונה על התמימים מרוסיא שבאו כעת לפּאַריז — \"פּלענטי\" (גענוג) אַרבעט, זיי דאַרפן דאָרט זיין, זיי האָבן דאָרט גענוג אַרבעט.",[["960","7","ראה שיחת יום א' דחה\"ס תש\"ו (לעיל ע' 5). וש\"נ."],["961","8","ביום ב', כ\"ד אדר ראשון ה'ש\"ת נסע רבינו באוירון מריגא לשטוקהולם. וביום ג', כ\"ה אדר ראשון עזב את שטוקהולם ונסע במסילת הברזל לגעטעבארג. ביום ה', כ\"ז אדר ראשון הפליגה הספינה בדרך לניו יארק. ביום ב', ח' אדר שני — אחרי נסיעה של שנים עשר יום — בשעה הרביעית אחר חצות היום הגיע הספינה לנמל ניו יארק, אבל על­פי החק אשר כל ספינה הנכנסת לנמל ניו יארק אחרי שעה הרביעית אחרי חצות היום אין מניחים את הנוסעים לרדת עד יום המחרת בבקר — ירד רבינו מהספינה ביום השלישי, ט' אדר שני ה'ש\"ת."],["962","9","ראה ספר השיחות תש\"ה ע' 75 ואילך."],["963","10","ברשימה אחרת: [דער] \"מען מעג\" האָט מען אַראָפּגענומען, דער \"מען דאַרף\" איז [...] האָט גערירט, נאָר קיין מקוה וואַסער איז דאָס נאָך ניט געוו[אָרן]."]]],[4301620378,"ו. דער אויבערשטער זאָל געבן אַז דעם יאָר זאָל זיין אַ סאַך תנאים'ס, חתונות, און שמחות ביי אידן; עס זאָל זיין אַ ריבוי, עס זאָל נתמלא ווערען וואָס מען האָט ביי אונז צוגענומען.\nדער אויבערשטער זאָל געבן אַ גאולה שלימה בקרוב בפועל ממש און ניט נאָר בכח."],[4301620379,"<h3>יחידות </h3>\n<b>י\"ט מר­חשון תש\"ח</b>\nמען דאַרף זיין אַנדערש, אַ תלמיד דאַרף זיין אַנדערש.\nדער טאַטע האָט געזאָגט, ער האָט געמאַכט דער ישיבה ניט נאָר אויף לערנען, דער עיקר מען זאָל זיין ירא שמים'ס<sup data-n=\"964\">1</sup>. מען דאַרף זיין שטאַרק — מען האָט מיט וואָס צו זיין שטאַרק נאָר מען איז פאַרשלאָפן, מען דאַרף ניט מתפעל ווערן פון קיין מגרעות הזמן.\nדער טאַטע האָט געזאָגט אויף דער ישיבה: איך האָב פאַרפלאַנצט אַ כרם — אַ וויינגאָרטן — פון אתרוגים. אתרוגים נעמען צו אַלע אוירים און בלייבן גאַנץ<sup data-n=\"965\">2</sup>, מען דאַרף זיין גאַנץ און שטאַרק. מען דאַרף זיין אַ קובע עתים לתורה און דער אויבערשטער וועט העלפן.\nאח\"כ נתן פ\"ש להישיבה שבמאָנט­רעאַל.",[["964","1","ראה שיחת ד' תשרי שנה זו (לעיל ע' 166). וש\"נ."],["965","2","ראה המשך וככה תרל\"ז פרק צד."]]],[4301620380,"<h3>י\"ט כסלו תש\"ח</h3>\nא. עס איז דאָ אַ אויסשפּראַך \"פותחין בברכה\"<sup data-n=\"966\">1</sup>, דאָס מיינט זינגען אַ ניגון. ניגון איז העכער פון דיבור<sup data-n=\"967\">2</sup>, אין ניגון זאָגט זיך אַרויס די עצמיות, און דאַמאָלט דערהערט מען די פנימיות ועצמיות פון דיבור.\nדאָס איז דער נקודת הענין וואָס חסידים זינגען אין דאַוונען<sup data-n=\"968\">3</sup>. עס איז דאָ אַ ניגון פאַרן דאַוונען און אַ ניגון אין דאַוונען. דער ניגון פאַרן דאַוונען דאָס איז אַ הכנה אַרויס צושלאָגן דאָס וואָס עס דאַרף ניט זיין אין דאַוונען.\nמען דאַרף זאָגן אַ ניגון, ניט בכדי עס זאָל דערנעמען יענעם, נאָר עס זאָל דערנעמען זיך.\nב. מען מאַכט אַ טעות, מען מיינט אַז חב\"ד איז השכלה, חב\"ד איז דאָך חכמה בינה דעת, טאָ ווי קומט דאָס צו עבודה מדות חג\"ת?\nאַמאָל האָט מען גערעדט אַז עס איז דאָ חסידים חג\"ת — חג\"ת'ניקעס, און חסידים חב\"ד — חב\"ד'ניקעס, מיינט מען",[["966","1","פתיחת אגרת הראשונה באגה\"ק שבתניא. וראה לקו\"ש חכ\"ד ע' 641 בהערה."],["967","2","ראה ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 221."],["968","3","ראה שיחת י\"ט כסלו תש\"ו ס\"ט (לעיל ע' 18)."]]],[4301620381,"ניט אַז חג\"ת'ניקעס איז נאָר חג\"ת און ניט חב\"ד, חב\"ד'ניקעס מיינט מען ניט נאָר חב\"ד און ניט חג\"ת, עס ווענדעט זיך נאָר אין די התחלה פון וואַנען מען הויבט אָן. און דער עיקר פון חסידות איז עבודה.\nדער אַלטער רבי ביז ער איז געפאָרן אין מעזריטש האָט זיך אָפּגעגעבען נאָר מיט בני תורה<sup data-n=\"969\">4</sup>, לאחר ווי ער איז צוריק­געקומען פון מעזריטש און וויסנדיק די כוונה פנימית, האָט ער זייער מקרב געווען דוקא אנשים פשוטים<sup data-n=\"970\">5</sup>.\nאין דעם בריוו וואָס כ\"ק אאמו\"ר הרה\"ק האָט מיר צוגעשיקט צו י\"ט כסלו תרס\"ב ווען ער איז ניט געווען אין ליובאַוויטש<sup data-n=\"971\">6</sup> — \"היום הזה הוא ר\"ה לדא\"ח אשר הנחילנו אבותינו הקדושים זצוקללה\"ה נ\"ע זי\"ע, והיא היא תורת הבעש\"ט ז\"ל. זה היום תחלת מעשיך כו'\" — איז דאָרט אָנגעדייטעט דער ענין ברמז.\nג. ווען<sup data-n=\"972\">7</sup> דער אַלטער רבי איז געקו­מען פון פּעטערבורג האָט ער געזאָגט: פאַר זיך האָב איך גאָר קיין מורא ניט געהאַט, איך האָב געזאָגט: ב\"ה וואָס דער מאסר האָט פּאַסירט נאָך 25 יאָר<sup data-n=\"973\">8</sup> אַרבעט עבודה פנימית מגלה זיין תורת הבעש\"ט, דער ענין האָט זיך שוין אויף געטאָן. איך פאַר זיך אַליין האָב איך ניט מורא געהאַט.\nדער אַלטער רבי האָט זיך מוסר נפש געווען אויף דריי זאַכן: פאַר דעם אויבערשטן, פאַר תורה, און פאַר ארץ ישראל. א) פאַר דעם אויבערשטן — קידוש השם. ב) פאַר תורה — דאָס איז תורה ומצות, תורה אַן מצות איז גאָרניט. תורה מיינט מען ניט ווי ער פאַרשטייט די תורה מיט זיין שכל, נאָר מיט זיין שכל זאָל ער פאַרשטיין די תורה וואָס די תורה וויל. וה­ג) ארץ ישראל, ווי עס איז ידוע<sup data-n=\"974\">9</sup> אַז דער אַלטער רבי האָט אויסגעהאַלטען רבותינו הקדושים מיט זייערע משפחות און משפחות אנ\"ש וואָס האָבען זיך באַזעצט אין ארץ ישראל<sup data-n=\"975\">10</sup>.",[["969","4","נוסחא אחרת: נאָר מיט גדולים בעלי מדריגה."],["970","5","ראה גם שיחת ל\"ג בעומר תש\"ז (לעיל ע' 123). וש\"נ."],["971","6","נדפס באגרות­-קודש כ\"ק אדמו\"ר מהורש\"ב ח\"א ע' רנט."],["972","7","הבא לקמן הובא ונתבאר בשיחת פורים תש\"כ."],["973","8","נוסחא אחרת: נאָך 30 יאר."],["974","9","ראה גם ספר השיחות תרפ\"ח­תרצ\"א ע' 176. וש\"נ."],["975","10","בשיחת פורים תש\"כ שם:\n\"ס'איז געווען אין תש\"ח, האָט דעמאלט דער רבי דער שווער פאַרבראַכט י\"ט כסלו. . און האָט דעמאלט גערעדט אז י\"ט כסלו איז אן ענין פון דעם אַלטן רבי'נס גאולה. . און האָט געזאָגט אז דער אַלטער רבי. . האָט זיך מוסר נפש געווען אויף ארץ ישראל, און האָט מסיים געווען: וכידוע אַז דער אַלטער רבי האָט געשיקט און אויסגעהאַלטן רבותינו וואָס זיי זיינען געווען באה\"ק אין ארץ ישראל.\n.. . דער קישור מיט י\"ט כסלו איז: איינע פון די מסירות אויפן אַלטן רבי'ן איז געווען אַז ער שיקט געלט אין ארץ ישראל. . דער אַלטער רבי וויל אויפשטעלן אַ מלכות אין ארץ ישראל. . און ער וויל דאָרטן ווערן אַ מלך. . בפנימיות הענינים איז דאָס אזוי געווען: דער אַלטער רבי האָט געוואָלט אייננעמען ארץ ישראל, און האָט געוואָלט אַז דאָרטן זאָל ווערן דער מלך דער \"יפוצו מעינותיך חוצה\" פון תורת החסידות. . האָט דער אַלטער רבי, דורך שיקן אַהין און אויפהאַלטן דאָרט תלמידי הבעש\"ט און תלמידי המגיד וחביריו, און מ'זאָל דאָרטן לערנען פנימיות התורה, האָט דאָס געדאַרפט אויפשטעלן דער מלכות אין ארץ ישראל, און חסידות זאל דאָרטן ווערן מלך. . דאָס הייסט, אַז ווען חסידות ווערט אַ מלכות אין ארץ ישראל, איז דאָס איז וואָס דער אַלטער רבי איז געוואָרן מלך אין ארץ ישראל.\n.. . אָט דאָס איז געווען י\"ט כסלו תש\"ח, דערנאָך אין אַ שטיקל צייט אַרום איז דאָרט נתייסד געוואָרן כפר חב\"ד<sup data-n=\"e24\">*</sup>. וואָס דער נאָמען איז דאָך געווען בידיעה ובהסכם פון דעם רבי'ן דער שווער<sup data-n=\"e25\">**</sup>\"."],["e24","*","ראה אגרות­-קודש חי\"ג ע' ע' תצח. חי\"ד ע' ס\"ע תיב ואילך."],["e25","**","ראה אגרות­-קודש ח\"י ע' רעג: בחסדי השם יתברך האָב איך פאַר זיי געגרינדעט אַ קאָלאָניע מיטן נאָמען \"כפר חב\"ד\"."]]],[4301620382,"איז אין די אַלע ענינים האָט ער שוין אויפגעטאָן און פאַר זיך האָט אים גאָר ניט געאַרט.\nדער אַלטער רבי האָט געהאַט מס\"נ צוליב אַ איש פשוט אין אַ ענין גשמי אָדער אַ ענין רוחני, ער האָט געזען דעם עצמי פון די פשוט'ע אידען, אין בעל הבית'שקייט ווען דער גלות וועט זיך ענדיקען האָט ער זיך ניט געמישט; זיין עבודה איז געווען אויף אַריינבריינגען ליכטיגקייט ביי אידן. השי\"ת זאָל העלפן עס זאָל זיין גילוי המשיח בקרוב ממש אָן פאַלשע פירושים, נאָר מען זאָל דער­הערען דעם גילוי העצמי והפנימי אין תורה ועבודה.\nדעם כח המס\"נ האָט דער אַלטער רבי מנחיל געווען צו חסידים נאָר דאָס איז בהעלם, און בכדי מגלה זיין מההעלם אל הגילוי איז דאָס אויך דורך מס\"נ, און יעדער מעדת החסידים דאַרף האָבן מסירת נפש.\nעס איז דאָך מתי יבא לידי ואקיי­מנה<sup data-n=\"976\">11</sup>, אין מסירת נפש איז ניט דער עיקר הכוונה דער מסירת נפש, נאָר דער עיקר איז דער ואקיימנה — עס דאַרף זיין דער קיום. להבדיל באלף הבדלות ביי גויים איז פאַראַן, ער שיכור'ט זיך אַן און נאַכהער פגר'ט ער אַוועק, דאָס איז פון דעם בראָנפן און צוליב דעם בראָנפן; אָבער ביי אידן איז די כוונה פון מסירת נפש דער ואקיימנה — דער קיום הדבר.\nוואָס איז מסירת נפש? דאָס וואָס ער וויל דאַרף מען ניט און דאָס וואָס ער וויל ניט דאַרף מען יע.. .\nד. עס זיינען דאָ אַזעלכע וואָס זאָגן אַז צו ענינים רוחניים איז ער קיין מחותן ניט, ער איז ניט שייך צו דעם. אָבער דער אמת איז אַז ער האָט באַ זיך אַ שרץ'ל<sup data-n=\"977\">12</sup> וואָס מאַכט אים שוין גאָר פאַר אַ מחותן. דער נפש הבהמית קאָרמעט ער ווי אַ מאפס — וואַרפט אים צו אַ שטיקל פלייש, אַ שטיקל חלה, און דער נפש האלקית דאַרט ביי אים. דער נה\"ב קומט צו איהם מיט זיינע חכמה'לאַך: עס איז דאָך עסקא דשבתא כפול<sup data-n=\"978\">13</sup>, דאַרף ער שבת עסן צווייערליי פיש צווייערליי פליישען צווייערליי פּיטשאַ, און אַזוי פירט ער אים אין לאָך אַריין: מנחה ומעריב ווי אַמאָל, קריאת שמע שעל המטה לאָזט מען דורך<sup data-n=\"979\">14</sup>, ער איז יוצא מיט אַרומדרייען די תפילין, און ער קאָרמעט דעם נה\"ב, און דער נפש האלקית דאָרט ביי אים.\nה. חסידים זיינען חכמים מחוכמים, מ'זאָגט זיך אַליין. ביי חסידים מאָנט מען ניט קיין ריבוי, דער עיקר צו אָנהערן דעם אמת.",[["976","11","ברכות סא, ב."],["977","12","נוסחא אחרת: עס זיינען דאַ אַזעלכע וואָס זאָגן ווי קומען זיי צו ענינים רוחניים, זיי זאָגן וואָס פאַר אַ מחותן בין איך צו דעם, אין בין ניט שייך צו דעם, דאַרף מען אים זאָגן: ברודער'ל דו האָסט ביי דיר אַ שרץ'ל."],["978","13","ראה מדרש תהלים צב."],["979","14","נוסחא אחרת: איין מאָל אין דריי וואָכן."]]],[4301620383,"מען קען זיין אַ בקי בש\"ס, ריידן אין אַ רמב\"ם, מחדש זיין חידושי תורה, ניט דאָס איז דער עיקר, דער עיקר איז לערנען אַ פסוק חומש און דערהערן דעם אמת.\nו. היינט קען מען פועל'ן אַ פולע.\nעפ\"י תורה דאַרף אַ טאַטע מפרנס זיין אַ בן קטן<sup data-n=\"980\">15</sup>, ובפרט אַ עבד איז רבו דאָך מחוייב במזונותיו<sup data-n=\"981\">16</sup>, זאָל דער אויבערשטער געבען אַ פולע השפעה בגשמיות וברוחניות אַז עס זאָל זיין ביי אידן געלעבט, חי — געלעבט.\nז. אידן זיינען זייער רייך, מילא אין גשמיות דאַרף מען זיי געבען וואָס זיי דאַרפן, נאָר אין רוחניות זיינען אַלע אידן רייך, נאָר דאָס איז בהעלם און מען בעדאַרף דאָס אַרויסנעמען מההעלם אל הגילוי.\nח. אין חסידות ודרכי החסידים איז דער עיקר עבודה, השכלה אַליין איז גאָרנישט — מיט השכלה איז ניע פאציאם<sup data-n=\"982\">17</sup>. עס איז דאָ אַ סדר: מוחין מדות מחשבה דיבור ומעשה, דער עיקר איז מעשה עבודה בפועל.\nאַ פּוד השכלה קומט ניט צו עבודה בפועל, למעלה איז אַ גוט וואָרט פון אַ ישובניק העכער פון אַ פּוד השכלה. אַ ישובניק באַגעגענט אַ צווייטן אידן, זאָגט אים: שלום עליכם, נעמט אים אַריין צו זיך אין הויז, גיט אים צו עסן ברויט מיט זויער מילך, וואַרפט אַריין נאָך אַ שײַטל האָלץ אין אויוון כדי ער זאָל זיך אָנוואַרעמען<sup data-n=\"983\">18</sup>, נאָכדעם זאָגט ער אַ קאַפּיטל תהלים פאַרוואָס אין אַזאַ שניי דאַרף יענער גיין אין וועג זוכען אַ קעלבל אויף לפרנס בני ביתו; דאָס איז למעלה זייער הויך<sup data-n=\"984\">19</sup>.\nאַ ישובניק האָט אַמאָל געזאָגט דעם טאַטן: איך ווייס גאָר ניט נאָר ווי צו איינשפּאַנען דעם גוף. האָט דער טאַטע געזאָגט: דורך אַ קאַפּיטל תהלים<sup data-n=\"985\">20</sup>.\nט. עס איז זיכער אַז דער רבי אין גן עדן העליון מיט די רביים אבות החסידות און חסידים וואָס האָבן זיך מוסר נפש געווען אויף חסידות און דרכי החסידים איז ידעי מה דהוי בהאי עלמא<sup data-n=\"986\">21</sup>, און האָבן אַ קורת רוח וואָס מען איז זיך דאָ משמח בשמחתו. די נשמות החסידים וואָס זיינען זיך צונויפגעקומען אין דעם טאָג צום אַלטן רבי'ן זיינען מקבל אַ ברכה פון רבי'ן פאַר בניהם ובני בניהם.\nי. די דריי ענינים אהבת השם אהבת התורה און אהבת ישראל דאַרף זיין ביי חסידים אויסגעפלאָכטען צוזאַמען אַזוי ווי אַ נר הבדלה.\nיא. עס איז אַ גרויסע רחמנות אויף די יונגעלייט דאָ. די עלטערע חסידים געדיינקען נאָך פון דער היים, זיי האָבן געזען אַ זיידן, אַ טאַטן; ווי מען רופט",[["980","15","ראה כתובות סה, ב."],["981","16","ראה רמב\"ם הל' עבדים פ\"א ה\"ט. פ\"ג ה\"א."],["982","17","{6} אין לזה ערך."],["983","18","נוסחא אחרת: זאָגט צו די בעל הבית'טע: וואַרף אַריין נאָך אַ שטיקעל האָלץ אין אויוון עס זאָל ווערן וואַרעמער — מיר האָבן אַ אורח, און זאָגט צו דעם אורח: גייט אַרויף אויפן אויוון און וואַרעמט זיך אָן און רוהט זיך אויס."],["984","19","נוסחא אחרת: איז דאָס למעלה אַ פולע טייערער מער ווי אַ גאון'ס חידושי תורה."],["985","20","נוסחא אחרת: אַ ישובניק האָט אַמאָל געזאָגט צו הוד כ\"ק אאמו\"ר הרה\"ק: איך ווייס גאָרניט, איך ווייס נאר אַז מ'דאַרף איינשפּאַנען דעם גוף מיט אַ קאַפּיטל תהלים."],["986","21","ראה גם סה\"מ תרפ\"א ע' רב ובשוה\"ג שם."]]],[4301620384,"דאָס דאָ \"דער אַלטע היים\"<sup data-n=\"987\">22</sup>. אָבער די יונגעלייט, זיי זיינען דאָך לא ראו אור, ובפרט אין דער מדינה. מ'טאָר דאָס ניט זאָגן, איך בין דאָך אַ בטלן — איך גיי ניט אין גאַס, איך זע נאָר דורכ'ן פענסטער איז יאָגט אַריין אַזאַ פראָסט אַז עס נעמט טרייסלען; דער היגער הו­האַ, אַ ציצה באַהאַלט מען, אַ באָרד דאַרף מען ניט, עס איז פּאַסקודנע. אין דער היים איז געווען אַ אויסשפּראַך \"עס איז חלשות\".\nאַלע אידען זיינען טייער, דער חסרון איז אין אונז.\nעס איז נאָר איין טרייסט! ווען אייז צוגייט אויף מים איז דער שטח פון די מים גרעסער ווי בעת עס איז געווען אייז, איז דאָך ווען דער אַמעריקאַנער אייז וועט צוגיין וועט דערפון ווערן מים רבים און מים חיים; און פון דעם אַליין דאַרף מען זיין בשמחה.\nיב. אח\"כ צוה כ\"ק אדמו\"ר שליט\"א לשיר ניגון, ואמר: מ'דאַרף זינגען אַ פנימיות'דיגן ניגון. חב\"ד מאָנט אין אַלץ פנימיות; אַ טאַנץ — אַ פנימיות'דיגן, אַ ניגון — אַ פנימיות'דיגן.\nיג. אמר לשאר בשרו ר\"מ שניאור­סאָהן מארץ הקודש: דו זאַלסט פאָרן געזונט, קומען געזונט און דערהערן ארץ ישראל אין אַ פנימיות.\nיד. אחד מזקני החסידים הרבנים רצה לישב אל השולחן, ומצד הצפיפות הי' קשה עבורו להתיישב, והעיר על זה כ\"ק אדמו\"ר שליט\"א: דאָס איז דאָך דער קונץ פון אַ למדן, אַז פון דעם ויש ליישב בדוחק זאָל ווערן אַ התרחבות.\nטו. כ\"ק אדמו\"ר שליט\"א צוה לנגן הניגון של ד' הבבות מאדמו\"ר הזקן, כ\"ק אדמו\"ר שליט\"א ניגנו ג\"כ בדביקות גדולה ובבכי' עצומה. אח\"כ צוה לנגן הניגון \"ניע זשוריצי חלאָפּצי\" וצוה לנגן בשמחה גדולה, וכל הנאספים ניגנו ורקדו בשמחה רבה.",[["987","22","ראה שיחת י\"ב תמוז תש\"ו ס\"א (לעיל ע' 52)."]]],[4301620385,"<h3>טבת תש\"ח</h3>\n<h4>להת' הנוסעים לאירופא<sup data-n=\"988\">1</sup></h4>\nס'איז מיר שווער צו רעדען בארוכה.\nאיך וויל איבערגעבן אַ גערוס, אַ פנימיות'דיגען גערוס, צו אַלע אידן בכלל און צו אנ\"ש בפרט. איך וויל וויסן וואָס יעדער מאַכט — אנשים, נשים, זייערע משפחות, קינדער. די וועלכע האָבן זיך מסדר געווען, די וועלכע האַלטן ביי מסדר זיין זיך בגשמיות ורוחניות. ווי גייט אָן דער לערנען, צי מ'האָט מייסד געווען חדרים סיי לנערים, סיי לנערות.\nמען איז זיך דאָך מכין אויף צו פאָרן, לערנען זיי דאָך ענגליש, זאָלן זיי ניט לערנען ביי דער וואָס קען זיי לערנען אַנדערע זאַכן, השפעות בלתי נעימות.\nאיר זאָלט איבערגעבען יעדען אַ גרוס בפרטיות, אַ פנימיות'דיגן וואַרימען גרוס.",[["988","1","בסוף חודש טבת תש\"ח נשלחו הת' הרב יצחק זלמן פאזנער והרב מנחם מענדל בוימגארטן לבקר את אחב\"י במדינות אירופא בכלל ומחנות הריכוז באשכנז ואוסטריא בפרט (ראה אגרות­-קודש ח\"ט ע' שפד. חי\"ג ע' תנג. אגרות­-קודש כ\"ק אדמו\"ר שליט\"א ח\"ב ע' רצב. וש\"נ)."]]],[4301620386,"איך גיב אייך געלט פאַר פאַרבריינ­גען. וואו איר קומט זאָלט איר מאַכן אַ חסידישע סעודה מ'זאָל זינגען אַ פנימיות'דיקען ניגון, גיין אַ ואַרימען ריקוד. בכלל מעורר זיין פנימיות. וואָס איז אַ חסידישע סעודה — אַ עקיל פון אַ הערינג און אַ ריינע קלאָרע גלעזל משקה. ניט עסן און טרינקען, דאָס איז ניט קיין חסידישע סעודה.\n(ואמר בנותנו פרוטות: און אויך קליין געלט).\nמען זאָל זען וואָס מען קען טאָן וועגען זייער הסתדרות, און שיקען רע­קומענדאַציעס.\nמ'דאַרף זיך ניט איילען. טאָן די אַר­בעט ניט איילענדיג, ניט טראַכטן וועגן באַלד צוריקפאָרן. נאָר טאָן די אַרבעט אין יעדן מקום (ווי עס באַדאַרף?).\nפאָרט געזונט, זייט געזונט, קומט געזונט. איר וועט מסתמא שרייבן אַמאָל טעלעגראַפיש וואָס איז נויטיק. און מען זאָל זיך זען געזונטערהייט."],[4301620387,"<h3>ר\"ד מה שאמר כ\"ק אדמו\"ר שליט\"א </h3>\n<b>להבע\"ב מעסקני הישיבה שנכנסו לחדר כ\"ק אדמו\"ר שליט\"א </b>\n<b>ביום ה' ט\"ז אדר ראשון תש\"ח<sup data-n=\"989\">1</sup></b>\nאַז מען ווערט עלטער געדענקט זיך די יוגענד קלערער, איך בין געשטאַנען ווען מיין הייליקער פאָטער דער גרוי­סער אוהב ישראל און בעל מסירת נפש פאַר אַ אידן\n— ניט רעכענענדיג זיך וואָס ער איז און ווי ער איז, צי ער איז אַ ירא שמים אָדער ניט, נאָר וויילע ער איז אַ איד<sup data-n=\"990\">2</sup>, ווי דאָס איז דער אמת און דאָס האָט ער געהאַט בירושה פון זיינע הייליקע עלטערען אַז אַ איד איז גוט —\nהאָט מיסד געווען די ישיבה.\nעס איז דאָ בקבלה פון בעש\"ט הקדוש, אַז אויף אַ אידן דאַרף מען קוקן אויף זיינע מעלות<sup data-n=\"991\">3</sup>, און חסרונות דאַרף מען זען אין זיך<sup data-n=\"992\">4</sup>, איז דענסמאָל דערזעט מען דעם אמת. וויילע טאָמער איז ער יעצט ניט ווי מען בעדאַרף, וועט אָבער פריער אָדער שפּעטער בעסער ווערן, אַ איד האָט דאָך אין זיך משמעת, ער האָט האָלט צו הערן אַ דבר תורה און העלפט דאָך תורה.\nמיר דאַרפן יעצט האָבן אַ ברכה, אויף דעם מצב פון אידן וואו זיי געפינען זיך. מיר זיינען דאָ אויך ניט זיכער, ווי די האַרץ איז ניט צואווייטאָגט אויף דעם מצב פון אונזערע ברידער אומעטום, דאַרפן מיר קוקען מיט אַ שטאַרקער אויג אויך אויף אונזער היים. דער אויבער­שטער וועט געוויס רחמנות האָבן, אָבער מען דאַרף וויסן אַז דאָס איז דורך תורה, וויילע תורה איז דאָך מגנא ומצלי<sup data-n=\"993\">5</sup>.",[["989","1","בהמשך לחגיגת חג היובל לתומכי­תמימים שהי' ביום א' ה' אד\"ר תש\"ח."],["990","2","ראה שיחת ליל אחש\"פ תש\"ו (לעיל ע' 40). וש\"נ."],["991","3","ראה ספר השיחות תש\"ה ע' 109."],["992","4","ראה ספר השיחות תרפ\"ח­תרצ\"א ע' 62. וש\"נ. כתר שם טוב (הוצאת קה\"ת, תשנ\"ט) סקע\"ה­קעו. וש\"נ."],["993","5","ראה סוטה כא, א."]]],[4301620388,"איר שטיצט די ישיבה תומכי-תמימים ניט נאָר מיט געלט, נאָר אויך מיט געפיל; דער אויבערשטער זאָל העלפן אייך און אַלע וואָס העלפן דער ישיבה תות\"ל, און באַגליקן אייך און זיי מיט די פאַמיליעס אין אַלע ענינים בגשמיות וברוחניות.\n(אמר רא\"ד קריימער נ\"י: אַז עס איז שוין ניטאָ קיין געלט. ע\"ז השיב כ\"ק אדמו\"ר שליט\"א:) דער אויבערשטער זאָל העלפן אידן זאָלן האָבן געלט אויף אַלץ וואָס זיי דאַרפן, און אויף תורה זאָל שטענדיג פעלן, דאָס הייסט מען זאָל מאַכן אַזוי פיל ישיבות אַז עס זאָל פעלן געלט, די אַרבעט איז נאָך ניט געקאָנ­טשעט.\nדער אויבערשטער זאָל העלפען אַז מען זאָל אינגיכען זוכה זיין טאַקע צו ביאת המשיח.\nאיך בעט איבערגעבן מיין ברכה צו אַלע משתתפים."],[4301620389,"<h3>פורים תש\"ח בסעודה</h3>\nא. עס איז אַ מנהג — בפרט ביי חסידי חב\"ד, אַז ביי יעדער חסידישע שמחה, שמחה של מצוה, איז די התחלה מיט אַ דבר מלכות<sup data-n=\"994\">1</sup>.\nאַ וואָרט פון בעש\"ט ותלמידיו דער מעזריטשער מגיד ותלמידיו — די רביים פון רבי'ן, אַ וואָרט פון רבי'ן, וואָס ביי אונז איז סתם רבי — דער אַלטער רבי.\nדבר מלכות איז אַ ענין פון הודאה. דערפאַר הויבט מען אַן אינדערפרי גלייך מיט \"מודה אני\"; מיט דעם הויבט מען אָן היינט, נעכטן, אייער­נעכטן, און אַ וואָך צוריק, און פאַר­אַ­יאָרן. \"מודה אני\" איז הודאה וואָס איז העכער פון השגה — פון כלי השגה און ניט פון כלי השכל, וויילע השגה איז לפי ערך המשיג ולפי אופן המושג, אָבער הודאה איז מצד העצם, הודאה איז בלתי מושג; אין השגה איז דאָ קשיות, וואָס באמת איז די מעלה פון השגה איז קשיות, ווי מיר זעען באַ אַ מלמד אַ בר פועל, אַז ניט נאָר וואָס ער קען זאָגן דעם ענין בפרטיות, נאָר ער קען אויך אויף מאַכן אַז דער תלמיד זאָל פרעגן אַ קשיא, און מיט דערויף איז מען מרחיב די כלי השגה פון דעם תלמיד<sup data-n=\"995\">2</sup>.\nעס איז דאָ אַ מקובל'דיקער וואָרט פון טאַטן. — ביים איבערזאָגן אַ וואָרט, דאַרף מען דערציילן דעם זמן ומקום ומצב ווען דער וואָרט איז געזאָגט געוואָרן, וואָס דאָס לעבט אויף דעם וואָרט; נאָר מצד כמה טעמים וועל איך דאָס איצטער מעלים זיין.\nמ'האָט געפרעגט ביי דעם אַלטן רבי'ן, וואָס האָט אויפגעטאָן מעזריטש? והכוונה: וואָס האָט אויף אים אויפגעטאָן מעזריטש? האָט ער געענטפערט: מעז­ריטש האָט מגלה געווען<sup data-n=\"996\">*2</sup> דעם פנימיות",[["994","1","ראה גם שיחת ל\"ג בעומר ושיחת י\"ב תמוז שנה זו (לקמן ע' 224. ע' 241 ואילך)."],["995","2","ברשימה אחרת: אַ מלמד אַ בר פועל, ווען ער לערנט מיט'ן תלמיד, זאָגט ער אים ניט דער ענין בפשיטות אַז עס זאָל זיין אַלעס רעכט, נאָר ער זאָגט אים אַזוי אַז דער תלמיד זאָל פרעגן: רבי, עס איז דאָך אַ קשיא! און דאָס איז מרחיב באַ אים די כלי השכל — ניט די כלי השגה, נאָר די כלי השכל.\nאָבער דאָס איז איז אַלץ אין דעם וואָס איז שייך צו השגה, משא\"כ הודאה נעמט עצם."],["996","*2","ברשימה אחרת: מעזריטש האָט אין אים מגלה געווען."]]],[4301620390,"האור פון בעש\"ט, דער בעש\"ט האָט אין אים ממשיך געווען פנימיות האור פון נשמת הרשב\"י.\nחסידות איז חג\"ת, הגם חסידות איז חב\"ד, אָבער דער עיקר איז חג\"ת<sup data-n=\"997\">3</sup>.\nעס איז פאַראַן קאָפּ און האַרץ, הש­כלה און עבודה, פאַרשטאַנד און געפיל, לערנען און דאַוונען; עס דאַרף אַראָפּ קומען די השכלה אין עבודה. דער לערנען איז צוליב דעם דאַוונען, דער דאַוונען איז צוליב דעם נאָך דעם דאַוונען — אין כל היום; און דער דאַוונען דאַרף מאַכען אַ חלל אין די אבנים וואָס פאַרשטיינען די האַרץ<sup data-n=\"998\">4</sup>, און דאָס מאַכט אַ חלון עס זאָל אַריינלייכטן אור און ניט אַריינלאָזן די שלעכטע ווינטן.\nדער אור אלקי איז פועל אַ המשכת החיות און צחצוח הכלי, צחצוח הכלי מיינט, ניט זיין קיין פרא אדם; ער רעדט זיך איין אַז ער איז עפּעס, אויב ער טוט אַ אידן אַ טובה פּאַטשט ער זיך אין בייכעל. המשכת החיות איז אָפּמינטערן, דורך דעם וואָס מען טוט פאַר עבודת התפלה.\nחסידים זיינען דאָך קלוגע: ניט מעלים דעם טוב, און ער ווייסט דעם לא טוב, ער זאָגט אשמנו בגדנו. מ'זאָגט דאָך אַלע אשמנו בגדנו, אָבער דער חסידישער אשמנו — ניט סתם זאָגען די ווערטער אשמנו, נאָר דער אַריינדרינגען: וויסען וואָס איז אשמנו, וואָס איז בגדנו.\nדער עיקר איז מען דאַרף דאַוונען.\nהערן — דאַרף מען נעמען אַ סאַך משקה, דערהערן — גאָר אַ סאַך משקה. און בפרטי פרטיות דאַרף מען דורכלעבן דעם ענין<sup data-n=\"999\">5</sup>.\nב. (ר' מיכאל דוואָרקין<sup data-n=\"1000\">6</sup> אמר לחיים, ואמר שהשי\"ת יעזור עס זאָל ווערן שלום אויף דער וועלט — ומה בקשתך — עד חצי המלכות! ואמר עוד כמה מלים — לשון של בקשה בנוגע המצב<sup data-n=\"1001\">7</sup>, וע\"ז אמר כ\"ק שליט\"א:) אין פּאַראַדקעס דאַרף מען זיך ניט מישן. דער אויבערשטער זאָל העלפן, אַז די כוונה פנימית זאָל אויסגעפירט ווערען בחסד וברחמים.\nג. אַמאָל האָט מען ווינציגער געטאָן<sup data-n=\"1002\">*7</sup>, און מער אויפגעטאָן, און מען איז געווען פאַרבונדן מיט פנימיות העצם; היינט — איז גאָרניט! מען טוט גאָרניט! ער רעדט זיך איין אַז ער איז אַ משכיל, ער איז אַ עובד — עס איז פאַראַן אַ געבאָרענער משכיל, אַ געבאָרענער עובד: בשעת דער מוהל איז מתקן וואָס מען דאַרף, און זאָגט \"זה הקטן גדול יהי'\" — מיט דעם איז ער אַ חסיד! עס איז ניטאָ דעם פאַרן דאַוונען, ניטאָ קיין דאַוונען, און עס איז ניטאָ נאָכן דאַוונען. זיי האָבן גאָרניט אָנגעפאַנגען טאָן. יונגעלייט, ובפרט תלמידי התמימים טוען ניט אין עבודת התפלה, צייטן­ווייז ברענגט דאָס אַ גיעול נפש<sup data-n=\"1003\">8</sup>.",[["997","3","ראה גם שיחת ליל שמח\"ת ושיחת י\"ט כסלו שנה זו (לעיל ע' 175. ע' 180 ואילך)."],["998","4","ברשימה אחרת: דער דאַוונען מאַכט אַ חלל אויף אַרויסנעמען די אבנים פון די שטיינערנע האַרץ."],["999","5","ברשימה אחרת: אויף הערן אַזאַ וואָרט דאַרף מען נעמען משקה, בפרט אויף דערהערן דעם וואָרט, און גאָר בפרטי פרטית אויף אַ דורכלעבן דעם וואָרט."],["1000","6","ראה אודותו לעיל ע' 120."],["1001","7","כנראה הכוונה בנוגע המצב בארץ ישראל. — ראה גם שיחת יום ב' דר\"ה שנה זו ס\"ב (לעיל ע' 162)."],["1002","*7","ברשימה אחרת: נאָר דאָס וואָס מ'האָט געטאָן איז געווען געטאָן."],["1003","8","ברשימה אחרת: צייטן וואָס עס איז אַ גועל נפש צו קוקן אויף אַ יונגערמאַן — אָן עבודה."]]],[4301620391,"פון די גרויסע פינסטערניש אין וועלט זעט מען אַז עס הויבט זיך אַן צו טאָגען — מיר זיינען ניט מגביל קיין זמן, און דער וואָס איז מגביל איז קלאָר אַז ער ווייסט ניט — און אין דער פינסטער זעט מען ניט ווי די בגדים זיינען איינגעשמירט, די שערות צופודעלט, פון מויל פיהלט זיך אַ ריח, די אויגן פאַר­קלעפּטע, און אַלע אברים זיינען ניט ווי עס דאַרף צו זיין. אַמאָל נאָך חצות האָט מען זיך משמח געווען מיט אַ דבר תורה, און דאָס איז אַ הכנה צו דעם דאַוונען.\nד. ביי חסידים, האָבן זיך די נעמען ניט געביטן. עס איז היינט אויך דאָ די נעמען: משכיל, עובד; אָבער דער מהות איז אַ אַנדערער. פאַראַן אַ קליין מהות, און אַז ער איז זיך מתעסק אין דעם וואָס מען דאַרף טאָהן, איז \"זה הקטן גדול יהי'\". אָבער אַז עס איז גאָר קיין מהות ניט. . .\nלערנען קאָן ער דאָך, דאַוונען פוילט מען זיך, און מען מאַכט זיך גרינג דעם לעבען.\nער רופט זיך אַ \"משכיל\", און ער איז לא ידע מאי קאמר, ניט נאָר ווייס ער ניט וואָס ער זאָגט, נאָר ער פאַרשטייט גאָרניט וואָס יענער זאָגט. ער האָט אַ כח הדיבור — לאפאטשעט ער. אַיי דער אַלטער רבי, דער צ\"צ זאָגט ניט אַזוי, איז וואָס; דער אַלטער רבי זאָגט אין לקו\"ת אַזוי און דער צ\"צ אין הגה\"ה זאָגט אַזוי — ער ווייס גאָרניט אַז עס איז אַ סתירה, ער זאָגט און ווייס אַליין ניט וואָס ער זאָגט; אָבער דאָס איז ניט אַזוי מזיק, און פאַר יענעם איז דאָס ניט אַזאַ היזק. משא\"כ העדר העבודה, העדר מדות חסידות, ער איז מבזה תורת החסידות — \"פוק חזי מאי עמא דבר\"<sup data-n=\"1004\">9</sup>, \"דבר\" (אויך) מלשון \"דַבֵר\" — \"רעדן\", וואָס עמא מדבר וועגן אים: ער איז אַ חסיד? דאָס איז מדת חסידות?\nדי נשמות פון די רביים ווי זיי זיינען העכער פאַר גופים וועלען זיך אַריינ­מישן, קענען זיי מאַכן אים פאַר אַ בעל מום אויף זיין גאַנצן לעבן. עס איז שווער צו ריידן אין היפך, נאָר מ'דאַרף ריידן אין טוב, וועט מען וויסן דעם לא טוב<sup data-n=\"1005\">10</sup>.\nה. ווען איינער וויל טאָן דעם צווייטן אַ טובה וואָס דאָס איז שלא לפי ערכו הן מצד מצבו הגשמי. . . ער וויל אים טאָן די טובה מיט אַ אמת, העלפן אים די רביים צו זיך אויפהויבן למעלה ממד­ריגתו אַז עס זאָל אַראָפּקומן אין פועל.\nו. חסידים גייען לאט לאט, אַ טראָט נאָך אַ טראָט<sup data-n=\"1006\">11</sup> מיט אַ תוקף, דער חסרון איז וואָס מען בריינגט ניט אַראָפּ אין פועל, עס דאַרף זיין \"טאָפּאָראַ דאַ פּלאַחאַ\"<sup data-n=\"1007\">12</sup>, מ'דאַרף זיך קענען אויף דעם קלוגינקען מיט אַלע זיינע חכמה'לעך: ער זאָגט צום מענטשן: איך האָב דיר געזאָגט פריער; עס איז אַזוי מצד המצב; ער איז ניט שולדיג; די אַלע תביעות איז מצד המצב. — אָבער מ'דאַרף אים קענען, חסידים חאַפּן דעם קלוגינקען ביים האַנט<sup data-n=\"1008\">13</sup>, וידוע המעשה מיט ר' נחום",[["1004","9","לשון חז\"ל — ברכות מה, א. פסחים יד, ב. ובכ\"מ."],["1005","10","ברשימה אחרת: איך וויל ניט ריידן אין דעם צד הלא טוב, איך וויל ריידן אין דעם צד הטוב."],["1006","11","ברשימה אחרת: ביי חסידים איז דער סדר לאט לאט, מ'חאַפּט ניט, אַז מ'חאַפּט — פאַר­חליפּעט מען זיך, אַלס איז בסדר והדרגה."],["1007","12","{6} הקרדום (הגרזן) על העץ. — ראה לעיל ע' 26. וש\"נ."],["1008","13","ברשימה אחרת: חסידות ווייסט אויף יעדערן ווי צו חאַפּן אים ביי דעם האַנט; ער איז אַ קלוגינקער, און דרייט זיך שטענדיק אַרויס. עס זשובעט, מאַכט אַ לאָך."]]],[4301620392,"מטשערנאָבעל וועגן הבחנה שכלית מיט די הונדערט רענדלעך<sup data-n=\"1009\">14</sup>.\nז. אַ וואָרט פון אַלטן רבי'ן: מען דאַרף פאַרשטיין וואָס מען וויל, און מען זאָל איבערלעבן וואָס מ'איז. אַז מען וועט וויסן וואָס מען וויל, וועט מען איבערלעבן וואָס מען איז, און עס וועט ליכטיגער ווערן אין דעם איבערלע­בונג<sup data-n=\"1010\">15</sup>.\nעס דאַרף זיין מדות חסידות. מדות טובות איז פאַראַן ביי אַלע אידן, ביי אַלע אידן איז פאַראַן גוטס, נאָר מ'דאַרף קוקען מיט אַ שפאקטיוו, מיט אַ פאַר­גרעסערונג­גלאָז, כדי דאָס צו זען. מדות חסידות איז מדות נעימות, ווען ער טוט אַ צווייטן די טובה, פילט זיך ניט די טובה, נאָר די זיסקייט. מדות טובות איז \"פּאַרעווע\", ער טוט יענעם אַ טובה מצד רחמנות; עס איז בעסער ווי גאָרניט, אָבער ביי חסידים דאַרף זיין מדות חסידות.\nח. דער אויבערשטער זאָל העלפן מ'זאָל אַראָפּנעמען דעם פאַרהאַמערקייט פון מוח און דעם פאַרשטיינטקייט פון האַרצן.\nדער אויבערשטער זאָל העלפן, ער זאָל אויפרעכטן די אידישע הערצער, וועט ער זען וואָס זיי קענען<sup data-n=\"1011\">16</sup>.\nעס זאָל ניט זיין נאָר גערעדט, נאָר בפועל.\nדער אויבערשטער זאָל העלפן אַז מען זאָל זיך זען געזונטערהייט, און די ווערטער זאָלען אַראָפּקומען אין אַ פנימיות.\nט. מצד חומר הענין וויל איך נאָכ­אַמאָל מזהיר זיין פאַרוואָס מ'טוט ניט אין עבודת התפלה, חסידישע יונגעלייט ובפרט תלמידי התמימים מוזן טאָן אין דאַוונען.\nדער אויבערשטער זאָל העלפן עס זאָל אַראָפּקומען אין עבודה בפועל.\nי. כשניגנו את הניגון של הבינוני צוה כ\"ק אדמו\"ר שליט\"א לחזור עליו כמה פעמים.\nלפני שניגנו את הניגון של ד' הבבות מכ\"ק אדמו\"ר הזקן אמר כ\"ק אדמו\"ר שליט\"א: מ'דאַרף זינגען דעם אַלטן רבין'ס ניגון, נאָר מ'דאַרף זיך פריער מכין זיין, אפשר דאַרף מען פריער זאָגן אַ ניגון פון טאַטן (וניגנו הניגון הידוע בשם: \"דער ראַסטאָווער ניגון\"<sup data-n=\"1012\">17</sup>).",[["1009","14","ראה ספר השיחות תש\"ג ע' 67 ואילך. וראה אגרות­-קודש אדמו\"ר מהורש\"ב ח\"ב ע' תשמא."],["1010","15","ברשימה אחרת: אַז מ'לעבט איבער וואָס מען איז, פאַרשטייט מען וואָס מען וויל, ווערט ליכטיקער אין דעם איבערלעבן."],["1011","16","ברשימה אחרת: דער אויבערשטער זאָל העלפן אַלעמען בהרחבה, וועט מען זען ווי אַלע אידן, ווי זיי זיינען, קענען זיין שומרי תורה ומצוות."],["1012","17","תוי הניגון — בספר הניגונים חלק א ניגון מד."]]]]});
